    fn has_nonconst_alloca_count(module: &trust_ir::Module, func_idx: usize) -> bool {
        let func = &module.functions[func_idx];
        let const_values: HashSet<ValueId> = func
            .blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter_map(|node| match (&node.inst, node.results.first().copied()) {
                (
                    Inst::Const {
                        value: Constant::Int(_),
                        ..
                    },
                    Some(result),
                ) => Some(result),
                _ => None,
            })
            .collect();
        func.blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .any(|node| {
                matches!(
                    &node.inst,
                    Inst::Alloca { count: Some(count), .. } if !const_values.contains(count)
                )
            })
    }

    fn has_const_alloca_count(
        module: &trust_ir::Module,
        func_idx: usize,
        expected_count: i128,
    ) -> bool {
        const_alloca_count(module, func_idx, expected_count) > 0
    }

    fn const_alloca_count(
        module: &trust_ir::Module,
        func_idx: usize,
        expected_count: i128,
    ) -> usize {
        let func = &module.functions[func_idx];
        let const_values: HashMap<ValueId, i128> = func
            .blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter_map(|node| match (&node.inst, node.results.first().copied()) {
                (
                    Inst::Const {
                        value: Constant::Int(value),
                        ..
                    },
                    Some(result),
                ) => Some((result, *value)),
                _ => None,
            })
            .collect();
        func.blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter(|node| {
                matches!(
                    &node.inst,
                    Inst::Alloca { count: Some(count), .. }
                        if const_values.get(count) == Some(&expected_count)
                )
            })
            .count()
    }

