    fn lower_straightline_invariant_with_dense_set_bitmask_regs(
        func: &BytecodeFunction,
        name: &str,
        dense_regs: &[(u8, u32)],
    ) -> Result<trust_ir::Module, TrustIrError> {
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            func,
            name,
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )?;
        let mut block = ctx.block_index_for_pc(0)?;
        for (pc, opcode) in func.instructions.iter().enumerate() {
            for &(reg, universe_len) in dense_regs {
                ctx.aggregate_shapes
                    .insert(reg, dense_int_one_to_n_set_bitmask_shape(universe_len));
            }
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)?
                .unwrap_or(block);
        }
        Ok(ctx.finish())
    }

    fn lower_straightline_invariant_with_tagged_scalar_or_set_regs(
        func: &BytecodeFunction,
        name: &str,
        tagged_regs: &[(u8, Vec<SetBitmaskElement>)],
    ) -> Result<trust_ir::Module, TrustIrError> {
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            func,
            name,
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )?;
        let mut block = ctx.block_index_for_pc(0)?;
        for (pc, opcode) in func.instructions.iter().enumerate() {
            for (reg, universe_values) in tagged_regs {
                ctx.aggregate_shapes.insert(
                    *reg,
                    AggregateShape::TaggedScalarOrSet {
                        scalar: ScalarShape::ModelValue,
                        universe_len: u32::try_from(universe_values.len()).unwrap(),
                        universe: SetBitmaskUniverse::from_elements(universe_values),
                        proof_source: tla_core::intern_name("TaggedScalarOrSetEqTest"),
                    },
                );
            }
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)?
                .unwrap_or(block);
        }
        Ok(ctx.finish())
    }

    // =====================================================================
    // WP-05 item 2: TaggedScalarUnion carrier + arm-aware ISel
    // =====================================================================

    fn tagged_scalar_union_layout(universe: Vec<SetBitmaskElement>) -> CompoundLayout {
        CompoundLayout::TaggedScalarUnion {
            universe,
            proof_source: tla_core::intern_name("UnionTypeOK"),
        }
    }

    #[test]
    fn test_tagged_scalar_union_int_arm_derivation() {
        let nil = SetBitmaskElement::ModelValue(tla_core::intern_name("NIL"));
        let mv = |n: &str| SetBitmaskElement::ModelValue(tla_core::intern_name(n));

        // Contiguous Int prefix {1,2,3} then the model value -> Some(1..=3, base 0).
        let contiguous = vec![
            SetBitmaskElement::Int(1),
            SetBitmaskElement::Int(2),
            SetBitmaskElement::Int(3),
            nil,
        ];
        assert_eq!(
            derive_tagged_scalar_union_int_arm(&contiguous),
            Some(TaggedUnionIntArm {
                lo: 1,
                hi: 3,
                base: 0
            })
        );

        // Non-contiguous Int members {1,3,7} -> no int arm (fail closed).
        assert_eq!(
            derive_tagged_scalar_union_int_arm(&[
                SetBitmaskElement::Int(1),
                SetBitmaskElement::Int(3),
                SetBitmaskElement::Int(7),
            ]),
            None
        );

        // A split int arm (an Int after a non-Int) -> no int arm: a runtime `v`
        // in the prefix range could otherwise map to a wrong slot.
        assert_eq!(
            derive_tagged_scalar_union_int_arm(&[
                SetBitmaskElement::Int(1),
                SetBitmaskElement::Int(2),
                mv("x"),
                SetBitmaskElement::Int(5),
            ]),
            None
        );

        // A model-value-only union has no int arm but is still a valid shape.
        assert_eq!(
            derive_tagged_scalar_union_int_arm(&[mv("a"), mv("b")]),
            None
        );

        // The shape derivation preserves universe order and carries the arm.
        match tagged_scalar_union_shape_from_carrier(&contiguous, tla_core::intern_name("T")) {
            Some(AggregateShape::TaggedScalarUnion {
                universe, int_arm, ..
            }) => {
                assert_eq!(universe, contiguous);
                assert_eq!(
                    int_arm,
                    Some(TaggedUnionIntArm {
                        lo: 1,
                        hi: 3,
                        base: 0
                    })
                );
            }
            other => panic!("expected TaggedScalarUnion shape, got {other:?}"),
        }

        // An empty universe never earns a shape.
        assert_eq!(
            tagged_scalar_union_shape_from_carrier(&[], tla_core::intern_name("T")),
            None
        );
    }

    #[test]
    fn test_store_var_tagged_scalar_union_runtime_int_emits_range_guard() {
        // v0 : Nodes \cup {NIL} = {1,2,3} \cup {NIL}; v1 : a runtime Int.
        // `v0' = v1` must encode with a fail-closed lo<=v<=hi guard then
        // (v-lo)+base -- never a raw store of the int payload.
        let nil = SetBitmaskElement::ModelValue(tla_core::intern_name("NIL"));
        let layout = StateLayout::new(vec![
            VarLayout::Compound(tagged_scalar_union_layout(vec![
                SetBitmaskElement::Int(1),
                SetBitmaskElement::Int(2),
                SetBitmaskElement::Int(3),
                nil,
            ])),
            VarLayout::ScalarInt,
        ]);

        let mut func = BytecodeFunction::new("union_store_runtime_int".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });
        func.emit(Opcode::LoadBool { rd: 1, value: true });
        func.emit(Opcode::Ret { rs: 1 });

        let module = lower_next_state(
            &func,
            "union_store_runtime_int",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("runtime int into a union slot should encode with a range guard");

        // The range guard: lo<=v (Sge) and v<=hi (Sle), plus the (v-lo) Sub.
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp {
                    op: ICmpOp::Sge,
                    ..
                }
            )) >= 1,
            "expected a lo<=v range-guard ICmp"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp {
                    op: ICmpOp::Sle,
                    ..
                }
            )) >= 1,
            "expected a v<=hi range-guard ICmp"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp { op: BinOp::Sub, .. }
            )) >= 1,
            "expected the (v - lo) index shift"
        );
        // Out-of-range values take a typed runtime-error path, never a wrong slot.
        assert!(
            has_runtime_error_status_path(&module, 0),
            "an out-of-range int must return a typed runtime error"
        );
    }

    #[test]
    fn test_store_var_tagged_scalar_union_const_member_uses_const_index_no_guard() {
        // v0 : {5,6,7}; `v0' = 6` -> const universe index 1, no range guard.
        let layout = StateLayout::new(vec![VarLayout::Compound(tagged_scalar_union_layout(vec![
            SetBitmaskElement::Int(5),
            SetBitmaskElement::Int(6),
            SetBitmaskElement::Int(7),
        ]))]);

        let mut func = BytecodeFunction::new("union_store_const_member".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 6 });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });
        func.emit(Opcode::LoadBool { rd: 1, value: true });
        func.emit(Opcode::Ret { rs: 1 });

        let module = lower_next_state(
            &func,
            "union_store_const_member",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("const universe member should encode to a const index");

        // Index of 6 in {5,6,7} is 1, emitted as a compile-time constant.
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(1),
                }
            )) >= 1,
            "const member should materialize its universe index (1)"
        );
        // A const in the universe needs no runtime range guard: no (v - lo) Sub.
        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp { op: BinOp::Sub, .. }
            )),
            0,
            "an in-universe const must not emit the range-guard index arithmetic"
        );
    }

