    #[test]
    fn test_tagged_scalar_union_eq_const_member_emits_index_compare() {
        // v0 : {1,2,3} \cup {NIL}; `v0 = 2` -> compare the index slot against
        // the const universe index of 2 (which is 1).
        let nil = SetBitmaskElement::ModelValue(tla_core::intern_name("NIL"));
        let layout = StateLayout::new(vec![VarLayout::Compound(tagged_scalar_union_layout(vec![
            SetBitmaskElement::Int(1),
            SetBitmaskElement::Int(2),
            SetBitmaskElement::Int(3),
            nil,
        ]))]);

        let mut func = BytecodeFunction::new("union_eq_const".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::Eq {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        func.emit(Opcode::Ret { rs: 2 });

        let module = lower_invariant(
            &func,
            "union_eq_const",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("union `= const member` should lower to an index compare");

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp { op: ICmpOp::Eq, .. }
            )) >= 1,
            "expected an equality ICmp on the index"
        );
        // The compared constant is the universe index (1), not the raw value 2.
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(1),
                }
            )) >= 1,
            "the const side must be translated to universe index 1"
        );
    }

    // =====================================================================
    // WP-ARGS: scalar-or-tuple union carrier with PER-POSITION element layouts
    // =====================================================================

    /// btree's `args` carrier: `NIL` (a model value), `<<key>>`, or
    /// `<<key, val>>` — the arity in the TAG, each tuple position with its OWN
    /// layout. Position 0 is an `Int` and position 1 a model value, which is
    /// exactly the mixed-kind case a single shared element layout cannot encode.
    fn args_per_position_union_layout() -> CompoundLayout {
        CompoundLayout::TaggedUnion {
            variants: vec![
                CompoundLayout::String,
                CompoundLayout::Tuple {
                    element_layouts: vec![CompoundLayout::Int],
                },
                CompoundLayout::Tuple {
                    element_layouts: vec![CompoundLayout::Int, CompoundLayout::String],
                },
            ],
            max_payload_slots: 2,
            proof_source: tla_core::intern_name("scalar-tuple-union:writer-coverage"),
        }
    }

    /// v0 = the `args` union, v1 = a runtime Int (`key`), v2 = a model value
    /// (`val`).
    fn args_per_position_union_state_layout() -> StateLayout {
        StateLayout::new(vec![
            VarLayout::Compound(args_per_position_union_layout()),
            VarLayout::ScalarInt,
            VarLayout::Compound(CompoundLayout::String),
        ])
    }

    #[test]
    fn test_store_var_tagged_union_arity2_mixed_kinds_emits_per_position_stores() {
        // `args' = <<key, val>>` with key : Int and val : ModelValue. The whole
        // point of the per-position carrier: each slot's encode is decided by
        // its OWN position layout, so no element universe is folded.
        let layout = args_per_position_union_state_layout();

        let mut func = BytecodeFunction::new("args_store_arity2".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::LoadVar { rd: 1, var_idx: 2 });
        func.emit(Opcode::TupleNew {
            rd: 2,
            start: 0,
            count: 2,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 2 });
        func.emit(Opcode::LoadBool { rd: 3, value: true });
        func.emit(Opcode::Ret { rs: 3 });

        let module = lower_next_state(
            &func,
            "args_store_arity2",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("a mixed-kind arity-2 tuple must store per position");

        // The ARITY selects the tag: `<<k,v>>` is variant 2.
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(2),
                }
            )) >= 1,
            "the arity-2 arm must store tag 2"
        );
    }

    #[test]
    fn test_store_var_tagged_union_arity1_takes_its_own_tag_and_zero_fills() {
        // `args' = <<key>>` is a DIFFERENT variant from `<<key, val>>`, so its
        // unused trailing payload slot must be canonically zeroed — that zero
        // fill is what keeps the flat encoding collision-free.
        let layout = args_per_position_union_state_layout();

        let mut func = BytecodeFunction::new("args_store_arity1".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::TupleNew {
            rd: 1,
            start: 0,
            count: 1,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 1 });
        func.emit(Opcode::LoadBool { rd: 2, value: true });
        func.emit(Opcode::Ret { rs: 2 });

        let module = lower_next_state(
            &func,
            "args_store_arity1",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("an arity-1 tuple must store per position");

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(1),
                }
            )) >= 1,
            "the arity-1 arm must store tag 1"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(0),
                }
            )) >= 1,
            "the unused payload slot must be zero-filled"
        );
    }

