    #[test]
    fn test_scalar_neq_folds_bare_name_id_imm_vs_model_value_constant_as_int_mismatch() {
        let name = "nameid_model_value_fold_guard";
        let name_id = i64::from(tla_core::intern_name(name).0);
        let mut pool = ConstantPool::new();
        let model_idx = pool.add_value(Value::ModelValue(name.into()));

        let mut func = BytecodeFunction::new("neq_nameid_imm_model_value".to_string(), 0);
        func.emit(Opcode::LoadImm {
            rd: 0,
            value: name_id,
        });
        func.emit(Opcode::LoadConst {
            rd: 1,
            idx: model_idx,
        });
        func.emit(Opcode::Neq {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        func.emit(Opcode::Ret { rs: 2 });

        let module = lower_invariant(
            &func,
            "neq_nameid_imm_model_value",
            LoweringOptions::new().with_constants(&pool),
        )
        .expect("NameId immediate vs model-value comparison should lower");
        // A bare LoadImm has no NameId provenance, so the Int/ModelValue lanes
        // mismatch and the `/=` folds to `true` (Const i64 1) without comparing
        // the operands. The lone `ICmp Ne` that remains is the Bool-result
        // normalization in `emit_success_return` (commit f6287aca), which
        // compares the *folded true* against 0 — not the operands. This test
        // predates that normalization, so the old expected count of 0 is stale;
        // exactly 1 confirms no operand-level `Ne` compare was emitted.
        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp { op: ICmpOp::Ne, .. }
            )),
            1,
            "only the Bool-return normalization Ne may remain; the inequality must fold"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(1),
                }
            )) > 0,
            "Int/ModelValue mismatch should materialize true"
        );
    }

    #[test]
    fn test_scalar_equality_keeps_specialized_name_id_loadimm_dynamic() {
        let pool = ConstantPool::new();
        let p1 = i64::from(tla_core::intern_name("p1").0);

        let mut func = BytecodeFunction::new("compact_name_id_loadimm_cmp".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: p1 });
        func.emit(Opcode::Neq {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        func.emit(Opcode::Ret { rs: 2 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::String)]);
        let module = lower_invariant(
            &func,
            "compact_name_id_loadimm_cmp",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("LoadImm name id compared to compact string slot should lower dynamically");
        // The specialized name-id LoadImm vs a *dynamic* compact string slot
        // must NOT fold; it emits a real runtime `slot != name_id` compare. That
        // is the first `ICmp Ne`. The second `ICmp Ne` is `emit_success_return`'s
        // Bool-result normalization (commit f6287aca), which postdates this test
        // — so the old expected count of 1 is stale. Exactly 2 confirms the
        // runtime compare is still emitted (it would drop to 1 if it folded).
        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp { op: ICmpOp::Ne, .. }
            )),
            2,
            "specialized model-value LoadImm must compare the runtime compact slot, not fold as Int/String mismatch"
        );
    }

