    /// The M0-G3 guard must also cover transitively inlined chunk callees:
    /// they receive `state_in_ptr` and lower through the same `LoadVar` choke
    /// point, so a helper that reads a Dynamic placeholder var declines the
    /// whole entry compile.
    #[test]
    fn test_hybrid_flat_view_callee_reaching_dynamic_var_declines() {
        let mut chunk = BytecodeChunk::new();
        // The helper reads the Dynamic placeholder var and returns a bool
        // (`v1 = v1`), so the ENTRY lowers cleanly and the decline can only
        // come from the callee body's own LoadVar choke point.
        let mut helper = BytecodeFunction::new("ReadCompound".to_string(), 0);
        helper.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        helper.emit(Opcode::Eq {
            rd: 1,
            r1: 0,
            r2: 0,
        });
        helper.emit(Opcode::Ret { rs: 1 });
        let helper_idx = chunk.add_function(helper);

        let mut entry = BytecodeFunction::new("hybrid_callee_dynamic".to_string(), 0);
        entry.emit(Opcode::Call {
            rd: 0,
            op_idx: helper_idx,
            args_start: 0,
            argc: 0,
        });
        entry.emit(Opcode::LoadImm { rd: 1, value: 7 });
        entry.emit(Opcode::StoreVar { var_idx: 0, rs: 1 });
        entry.emit(Opcode::Ret { rs: 0 });

        let layout = hybrid_two_var_layout();
        let err = lower_entry_next_state_with_chunk(
            &entry,
            &chunk,
            "hybrid_callee_dynamic",
            LoweringOptions::new().with_layout(&layout),
        )
        .expect_err("a chunk callee reading a hybrid Dynamic placeholder var must decline");
        let message = format!("{err}");
        assert!(
            message.contains("hybrid flat-view placeholder (Dynamic) var v1"),
            "unexpected hybrid callee decline error: {message}"
        );
    }

    /// The guard is scoped to hybrid flat-view layouts only: the SAME bytecode
    /// against the SAME var layouts WITHOUT the hybrid marker must not hit the
    /// hybrid decline (whole-state `Dynamic` keeps its historical
    /// handle-bridge/serialized semantics — it may lower or fail for other
    /// reasons, but never with the hybrid placeholder message).
    #[test]
    fn test_non_hybrid_dynamic_var_access_does_not_hit_hybrid_guard() {
        let mut func = BytecodeFunction::new("non_hybrid_load_dynamic".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });
        func.emit(Opcode::LoadBool { rd: 1, value: true });
        func.emit(Opcode::Ret { rs: 1 });

        let layout = StateLayout::new(vec![
            VarLayout::ScalarInt,
            VarLayout::Compound(CompoundLayout::Dynamic),
        ]);
        if let Err(err) = lower_next_state(
            &func,
            "non_hybrid_load_dynamic",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        ) {
            let message = format!("{err}");
            assert!(
                !message.contains("hybrid flat-view placeholder"),
                "non-hybrid layout must not trip the hybrid guard: {message}"
            );
        }
    }

