    #[test]
    fn test_func_except_string_range_materializes_load_imm_name_id_replacement() {
        // Gap #35: inner-EXISTS / split-action specialization bakes a String
        // (or ModelValue) binding into action-local bytecode via
        // `LoadImm <interned NameId>`. Shape inference can only see the integer
        // immediate, so the value register is tracked as Scalar(Int), but the
        // FuncExcept destination is a String-valued function range slot. The
        // raw i64 IS the interned NameId, so this must compact-materialize
        // rather than bailing to the interpreter (mirrors Slush AssignColorToNode
        // `pick' = [pick EXCEPT ![node] = color]`).
        let blue = i64::from(tla_core::intern_name("Blue").0);
        let mut func =
            BytecodeFunction::new("func_except_string_range_load_imm_name_id".to_string(), 0);
        // r0 = pick (function var), r1 = baked node key (ModelValue NameId),
        // r2 = baked color value (String NameId, via LoadImm).
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm {
            rd: 1,
            value: i64::from(tla_core::intern_name("n1").0),
        });
        func.emit(Opcode::LoadImm { rd: 2, value: blue });
        func.emit(Opcode::FuncExcept {
            rd: 3,
            func: 0,
            path: 1,
            val: 2,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 3 });
        func.emit(Opcode::LoadBool { rd: 4, value: true });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::Compound(
            model_value_scalar_function_layout(&["n1", "n2", "n3"]),
        )]);
        let module = lower_next_state(
            &func,
            "func_except_string_range_load_imm_name_id",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect(
            "FuncExcept pick[n1] := <LoadImm String NameId> should compact-materialize, not bail",
        );

        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "LoadImm NameId String replacement should keep fixed compact materialization"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

