    /// WP-08 (item 6): the audit's named unpinned residue — a FuncExcept
    /// replacement of a SetBitmask range slot with a DYNAMIC singleton
    /// (`![1] = {v}` where `v` is a runtime state scalar, the btree
    /// `![newRoot] = {pivot}` pattern). Must compile via the fail-closed
    /// runtime loop: universe bit per element, out-of-universe element =>
    /// typed runtime error (TypeMismatch) — never a silent drop.
    #[test]
    fn test_func_except_setbitmask_value_accepts_dynamic_singleton_replacement() {
        let mut func = BytecodeFunction::new(
            "func_except_setbitmask_dynamic_singleton_value".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: 1 });
        func.emit(Opcode::LoadVar { rd: 2, var_idx: 1 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 2,
            count: 1,
        });
        func.emit(Opcode::FuncExcept {
            rd: 4,
            func: 0,
            path: 1,
            val: 3,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 4 });
        func.emit(Opcode::LoadBool { rd: 5, value: true });
        func.emit(Opcode::Ret { rs: 5 });

        let layout = StateLayout::new(vec![
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(int_range_set_bitmask_layout(1, 4)),
                pair_count: Some(3),
                domain_lo: Some(1),
            }),
            VarLayout::ScalarInt,
        ]);
        let module = lower_next_state(
            &func,
            "func_except_setbitmask_dynamic_singleton_value",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("FuncExcept ack[1] := {v} with runtime v should convert via the fail-closed loop");

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::Shl,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "dynamic element should compute its universe bit at runtime (shl)"
        );
        assert!(
            has_runtime_error_status_path(&module, 0),
            "out-of-universe element must reach a typed runtime-error branch (fail closed)"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

    /// WP-08 (item 6): same dynamic-singleton conversion on the RUNTIME-path
    /// FuncExcept (the replace index is itself a runtime scalar), exercising
    /// the masked-replacement chain rather than the static-index fallback.
    #[test]
    fn test_func_except_setbitmask_value_accepts_dynamic_singleton_with_runtime_path() {
        let mut func = BytecodeFunction::new(
            "func_except_setbitmask_dynamic_singleton_runtime_path".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadVar { rd: 1, var_idx: 2 });
        func.emit(Opcode::LoadVar { rd: 2, var_idx: 1 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 2,
            count: 1,
        });
        func.emit(Opcode::FuncExcept {
            rd: 4,
            func: 0,
            path: 1,
            val: 3,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 4 });
        func.emit(Opcode::LoadBool { rd: 5, value: true });
        func.emit(Opcode::Ret { rs: 5 });

        let layout = StateLayout::new(vec![
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(int_range_set_bitmask_layout(1, 4)),
                pair_count: Some(3),
                domain_lo: Some(1),
            }),
            VarLayout::ScalarInt,
            VarLayout::ScalarInt,
        ]);
        let module = lower_next_state(
            &func,
            "func_except_setbitmask_dynamic_singleton_runtime_path",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect(
            "FuncExcept ack[k] := {v} with runtime k and v should convert via the fail-closed loop",
        );

        assert!(
            has_runtime_error_status_path(&module, 0),
            "out-of-universe element must reach a typed runtime-error branch (fail closed)"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

    /// WP-08 (item 6): StoreVar of a DYNAMIC materialized singleton into a
