    /// WP-08 (item 6): membership-only lazy union over a symbolic numeric
    /// domain — `x \in Int \cup {NULL}` (the Disruptor RingBuffer TypeOk
    /// `Values \cup {NULL}` pattern with `Values <- Int`). The union compiles
    /// as a LazyUnion and SetIn lowers per-arm: symbolic-domain membership
    /// OR'd with the exact model-value compare.
    #[test]
    fn test_set_in_lazy_union_symbolic_int_domain_with_model_value_arm_compiles() {
        let mut pool = ConstantPool::new();
        let int_idx = pool.add_value(Value::ModelValue(Rp::from("Int")));
        let null_idx = pool.add_value(Value::ModelValue(Rp::from("NULL")));

        let mut func = BytecodeFunction::new(
            "set_in_lazy_union_symbolic_int_model_value".to_string(),
            0,
        );
        func.emit(Opcode::LoadConst {
            rd: 0,
            idx: int_idx,
        });
        func.emit(Opcode::LoadConst {
            rd: 1,
            idx: null_idx,
        });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 1,
            count: 1,
        });
        func.emit(Opcode::SetUnion {
            rd: 3,
            r1: 0,
            r2: 2,
        });
        func.emit(Opcode::LoadVar { rd: 4, var_idx: 0 });
        func.emit(Opcode::SetIn {
            rd: 5,
            elem: 4,
            set: 3,
        });
        func.emit(Opcode::Ret { rs: 5 });

        let layout = StateLayout::new(vec![VarLayout::ScalarInt]);
        let module = lower_invariant(
            &func,
            "set_in_lazy_union_symbolic_int_model_value",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("x \\in Int \\cup {NULL} should lower as membership-only lazy union");

        // An Int-sorted candidate is unconditionally a member of the
        // SymbolicDomain(Int) arm, so no host call and no pointer scan.
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "lazy-union membership must stay static (no materialized scan)"
        );
    }

    /// WP-08 (item 6): every MATERIALIZED consumer of the new
    /// SymbolicDomain-armed lazy union stays fail-closed — only SetIn
    /// membership is admitted.
    #[test]
    fn test_lazy_union_symbolic_domain_arm_rejects_materialized_consumers() {
        let mut pool = ConstantPool::new();
        let int_idx = pool.add_value(Value::ModelValue(Rp::from("Int")));
        let null_idx = pool.add_value(Value::ModelValue(Rp::from("NULL")));

        let mut func = BytecodeFunction::new(
            "lazy_union_symbolic_domain_materialized_consumer".to_string(),
            0,
        );
        func.emit(Opcode::LoadConst {
            rd: 0,
            idx: int_idx,
        });
        func.emit(Opcode::LoadConst {
            rd: 1,
            idx: null_idx,
        });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 1,
            count: 1,
        });
        func.emit(Opcode::SetUnion {
            rd: 3,
            r1: 0,
            r2: 2,
        });
        // A materialized consumer: SetDiff over the lazy union.
        func.emit(Opcode::SetDiff {
            rd: 4,
            r1: 3,
            r2: 2,
        });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::ScalarInt]);
        let err = lower_invariant(
            &func,
            "lazy_union_symbolic_domain_materialized_consumer",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect_err("materialized consumers of a symbolic-armed lazy union must fail closed");

        let message = format!("{err}");
        assert!(
            message.contains("lazy set shape is only supported by SetIn membership"),
            "unexpected materialized-consumer error: {message}"
        );
    }

