    /// GAP C: a `FuncApply` read of a `[Dom -> SUBSET <const>]` function-range
    /// slot must carry the proven range universe onto the resulting SetBitmask
    /// register, so a downstream `\subseteq` (AllocatorImplementation
    /// `Return(c,S): S \subseteq holding[c]`) lowers natively instead of bailing
    /// with "compact SetBitmask operand requires exact universe metadata".
    ///
    /// Before the fix the layout-derived `Function` value shape dropped the
    /// universe (`SetBitmask { universe: Unknown }`), so `compact_binary_set_universe`
    /// rejected the `\subseteq`. The proven range universe now flows from the
    /// `CompoundLayout::Function { value_layout: SetBitmask { universe } }`
    /// through `tracked_shape_from_compound_layout`.
    #[test]
    fn test_func_apply_subset_range_read_threads_universe_for_subseteq() {
        use std::sync::Arc;

        let s_idx = {
            let mut pool = ConstantPool::new();
            // S = {r1}, a static subset of the proven range universe {r1, r2}.
            let idx = pool.add_value(Value::set([Value::ModelValue(Rp::from("r1"))]));
            (pool, idx)
        };
        let (pool, s_const) = s_idx;

        let mut func = BytecodeFunction::new("subset_range_read_subseteq".to_string(), 0);
        // r0 = S = {r1} (the bound subset value).
        func.emit(Opcode::LoadConst {
            rd: 0,
            idx: s_const,
        });
        // r1 = client key c (baked model value), r2 = holding (the function var).
        func.emit(Opcode::LoadImm {
            rd: 1,
            value: i64::from(tla_core::intern_name("c1").0),
        });
        func.emit(Opcode::LoadVar { rd: 2, var_idx: 0 });
        // r3 = holding[c] : SUBSET Resources (the function-range SetBitmask read).
        func.emit(Opcode::FuncApply {
            rd: 3,
            func: 2,
            arg: 1,
        });
        // r4 = (S \subseteq holding[c]).
        func.emit(Opcode::Subseteq {
            rd: 4,
            r1: 0,
            r2: 3,
        });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::Compound(
            model_value_subset_range_function_layout(&["c1", "c2", "c3"], &["r1", "r2"]),
        )]);

        lower_next_state(&func, "subset_range_read_subseteq", LoweringOptions::new().with_constants(&pool).with_layout(&layout))
        .expect(
            "S \\subseteq holding[c] must lower natively once the function-range SUBSET universe is threaded onto the FuncApply read",
        );
    }

    /// Companion fail-closed guard: an identical `\subseteq` over a function
    /// range whose value layout is a universe-less `Set` (no proven `SUBSET
    /// <const>` type) must still be rejected. This pins that the GAP C fix only
    /// admits the read when the layout actually proves the universe and never
    /// fabricates one.
    #[test]
    fn test_func_apply_universeless_set_range_read_rejects_subseteq() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let s_const = pool.add_value(Value::set([Value::ModelValue(Rp::from("r1"))]));

        let mut func = BytecodeFunction::new("universeless_set_range_read_subseteq".to_string(), 0);
        func.emit(Opcode::LoadConst {
            rd: 0,
            idx: s_const,
        });
        func.emit(Opcode::LoadImm {
            rd: 1,
            value: i64::from(tla_core::intern_name("c1").0),
        });
        func.emit(Opcode::LoadVar { rd: 2, var_idx: 0 });
        func.emit(Opcode::FuncApply {
            rd: 3,
            func: 2,
            arg: 1,
        });
        func.emit(Opcode::Subseteq {
            rd: 4,
            r1: 0,
            r2: 3,
        });
        func.emit(Opcode::Ret { rs: 4 });

        let universeless_range = CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::ExplicitScalarDomain {
                key_layout: Box::new(CompoundLayout::String),
                keys: ["c1", "c2", "c3"]
                    .iter()
                    .map(|name| SetBitmaskElement::ModelValue(tla_core::intern_name(name)))
                    .collect(),
            }),
            value_layout: Box::new(CompoundLayout::Set {
                element_layout: Box::new(CompoundLayout::Dynamic),
                element_count: Some(2),
            }),
            pair_count: Some(3),
            domain_lo: None,
        };
        let layout = StateLayout::new(vec![VarLayout::Compound(universeless_range)]);

        assert_rejects_unproven_set_bitmask_universe(lower_next_state(
            &func,
            "universeless_set_range_read_subseteq",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        ));
    }

    /// VERIFY-FIRST / regression for the Huang-style `Append(@, record)` where
    /// the source sequence is statically empty (`Capacity(0)`) and its tracked
    /// element shape disagrees with the appended element's shape.
    ///
    /// Huang's census fallback reported
    /// `source_shape=Sequence { extent: Capacity(0), element: Some(Scalar(Int)) }`
    /// appended with a two-field record. Because the source is provably empty
    /// (`Capacity(0)`), `Append(s, e)` is unconditionally the single-element
    /// sequence `<<e>>`, so the stale `Scalar(Int)` element shape never
    /// materializes and the result is fully determined by the appended element.
    ///
    /// This drives the append op directly (state-var load -> RecordNew ->
    /// Append) so the source register keeps its compact `Capacity(0)` slot and
    /// the element-shape mismatch is preserved (the FuncExcept/StoreVar path
    /// re-derives shapes from the destination layout and would mask it).
    #[test]
    fn test_lower_append_record_into_capacity_zero_int_sequence_materializes() {
        use tla_tir::bytecode::BuiltinOp;

        let mut pool = ConstantPool::new();
        let fields_start = pool.add_value(Value::String("num".into()));
        pool.add_value(Value::String("den".into()));

        let mut func = BytecodeFunction::new(
            "lower_append_record_into_capacity_zero_int_sequence".to_string(),
            0,
        );
        // r0 = state var 0 (a Capacity(0) Sequence<Int>, statically empty).
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        // r2..r3 build a two-field record (the appended element), r1 holds it.
        func.emit(Opcode::LoadImm { rd: 2, value: 1 });
        func.emit(Opcode::LoadImm { rd: 3, value: 2 });
        func.emit(Opcode::RecordNew {
            rd: 1,
            fields_start,
            values_start: 2,
            count: 2,
        });
        // r4 = Append(r0, r1): empty Int-sequence with an appended record.
        func.emit(Opcode::CallBuiltin {
            rd: 4,
            builtin: BuiltinOp::Append,
            args_start: 0,
            argc: 2,
        });
        func.emit(Opcode::Ret { rs: 4 });

        // Source layout: a statically-empty (Capacity(0)) sequence of ints,
        // exactly the shape the Huang census reported.
        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Sequence {
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(0),
            capacity_proven: false,
        })]);

        let mut ctx = Ctx::new(
            &func,
            "lower_append_record_into_capacity_zero_int_sequence",
            LoweringMode::NextState,
            Some(&pool),
            Some(&layout),
            None,
        )
        .expect("test context should initialize");
        let mut block = ctx.block_index_for_pc(0).expect("entry block should exist");
        for (pc, opcode) in func.instructions.iter().enumerate() {
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap_or_else(|err| {
                    panic!("Append over Capacity(0) source should lower natively, pc {pc} opcode {opcode:?} failed: {err}")
                })
                .unwrap_or(block);
        }
        let module = ctx.finish();
        // Pure flat manipulation: no runtime Call (e.g. @tla_seq_append).
        assert_eq!(
            inst_call_count(&module, 0),
            0,
            "Capacity(0) Append native lowering must not emit any runtime Call"
        );
    }

