    #[test]
    // Renamed from `test_store_var_recovers_flat_aggregate_pointer_from_destination_shape`:
    // commit f6287aca made this case fail closed (see the rationale in the body),
    // so the test now asserts the rejection rather than the (unsound) recovery.
    fn test_store_var_flat_aggregate_pointer_without_provenance_fails_closed() {
        let mut func =
            BytecodeFunction::new("store_recovered_flat_sequence_pointer".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 10 });
        func.emit(Opcode::LoadImm { rd: 1, value: 20 });
        func.emit(Opcode::SeqNew {
            rd: 2,
            start: 0,
            count: 2,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 2 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Sequence {
            capacity_proven: false,
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(2),
        })]);
        let pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "store_recovered_flat_sequence_pointer",
            LoweringMode::NextState,
            Some(&pool),
            Some(&layout),
            None,
        )
        .expect("test context should initialize");
        let mut block = ctx.block_index_for_pc(0).expect("entry block should exist");
        for (pc, opcode) in func.instructions.iter().enumerate().take(3) {
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap_or_else(|err| panic!("lowering pc {pc} opcode {opcode:?} failed: {err}"))
                .unwrap_or(block);
        }

        // Strip BOTH the tracked aggregate shape and the compact-slot physical
        // provenance for r2, leaving only the `AggregatePointerKind::Flat`
        // marker that `store_reg_ptr` records for the SeqNew result. With no
        // source-shape provenance, the only layout information left is the
        // destination's compact Sequence shape.
        //
        // Commit f6287aca ("Fail closed unsafe Trust-CG implied-action paths")
        // deliberately made this case fail closed: a flat aggregate pointer's
        // physical layout is not recoverable from the destination shape alone. A
        // flat `[len, e0, e1]` sequence and a flat FuncDef pair-list
        // `[len, k0, v0, k1, v1]` are indistinguishable once the source shape is
        // gone, so inferring the source layout from the destination Sequence
        // would silently emit a wrong slot copy. The earlier expectation that
        // StoreVar "recovers the source shape from the fixed destination layout"
        // encoded that unsound inference and is stale; the sound behavior is to
        // reject. (The safe recovery path — where compact-slot provenance is
        // retained — is exercised by
        // `test_store_var_recovers_raw_compact_source_from_destination_shape`.)
        ctx.aggregate_shapes.remove(&2);
        ctx.compact_state_slots.remove(&2);
        let err = ctx
            .lower_opcode(3, &func.instructions[3], block, &func.instructions)
            .expect_err(
                "StoreVar must fail closed when a flat aggregate pointer source has lost its physical source-shape provenance",
            );
        let message = format!("{err}");
        assert!(
            message.contains("lost physical source-shape provenance")
                && message.contains("refusing to infer source layout from destination"),
            "unexpected fail-closed error: {message}"
        );
    }

    #[test]
    fn test_store_var_recovers_raw_compact_source_from_destination_shape() {
        let mut func = BytecodeFunction::new("store_recovered_raw_compact_sequence".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Sequence {
            capacity_proven: false,
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(2),
        })]);
        let pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "store_recovered_raw_compact_sequence",
            LoweringMode::NextState,
            Some(&pool),
            Some(&layout),
            None,
        )
        .expect("test context should initialize");
        let mut block = ctx.block_index_for_pc(0).expect("entry block should exist");
        block = ctx
            .lower_opcode(0, &func.instructions[0], block, &func.instructions)
            .expect("LoadVar should lower")
            .expect("LoadVar should keep lowering in the current block");

        assert!(
            ctx.compact_state_slots.contains_key(&0),
            "LoadVar should retain compact physical provenance"
        );
        ctx.aggregate_shapes.remove(&0);
        block = ctx
            .lower_opcode(1, &func.instructions[1], block, &func.instructions)
            .expect("StoreVar should recover raw compact source shape from destination layout")
            .expect("StoreVar should keep lowering in the current block");

        let module = ctx.finish();
        assert!(
            (0..module.functions[0].blocks.len())
                .any(|block_idx| block_has_state_out_store_to_slot(&module, 0, block_idx, 0)),
            "recovered raw compact StoreVar should write the destination length slot"
        );
        assert!(
            block <= module.functions[0].blocks.len(),
            "returned block should remain a valid module block index"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

