    #[test]
    fn test_exists_over_scalar_compact_func_apply_fails_closed_without_set_domain_proof() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let p1 = pool.add_value(Value::ModelValue(Rp::from("p1")));

        let mut func = BytecodeFunction::new(
            "exists_over_scalar_compact_func_apply_without_proof".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: p1 });
        func.emit(Opcode::FuncApply {
            rd: 2,
            func: 0,
            arg: 1,
        });
        let begin_pc = func.emit(Opcode::ExistsBegin {
            rd: 5,
            r_binding: 3,
            r_domain: 2,
            loop_end: 0,
        });
        func.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = func.emit(Opcode::ExistsNext {
            rd: 5,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: 5 });

        let layout = StateLayout::new(vec![VarLayout::Compound(
            model_value_scalar_function_layout(&["p1", "p2"]),
        )]);

        let err = lower_next_state(
            &func,
            "exists_over_scalar_compact_func_apply_without_proof",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect_err("scalar compact function results must not be enumerable EXISTS domains");
        let message = err.to_string();
        assert!(
            message.contains("ExistsBegin: raw compact source r2")
                && message.contains("Scalar(String)")
                && message.contains("cannot be materialized as an aggregate pointer"),
            "unexpected scalar compact EXISTS-domain rejection: {message}"
        );
    }

    #[test]
    fn test_exists_over_tagged_scalar_or_set_func_apply_decodes_set_branch() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let p1 = pool.add_value(Value::ModelValue(Rp::from("p1")));
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));

        let mut func =
            BytecodeFunction::new("exists_over_tagged_scalar_or_set_func_apply".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: p1 });
        func.emit(Opcode::FuncApply {
            rd: 2,
            func: 0,
            arg: 1,
        });
        let begin_pc = func.emit(Opcode::ExistsBegin {
            rd: 5,
            r_binding: 3,
            r_domain: 2,
            loop_end: 0,
        });
        func.emit(Opcode::LoadConst { rd: 4, idx: p2 });
        func.emit(Opcode::Eq {
            rd: 6,
            r1: 3,
            r2: 4,
        });
        let next_pc = func.emit(Opcode::ExistsNext {
            rd: 5,
            r_binding: 3,
            r_body: 6,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: 5 });

        let layout = StateLayout::new(vec![VarLayout::Compound(
            model_value_tagged_scalar_or_set_function_layout(&["p1", "p2"]),
        )]);
        let module = lower_next_state(
            &func,
            "exists_over_tagged_scalar_or_set_func_apply",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("tagged scalar-or-set FuncApply should expose its set branch to EXISTS");

        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Cast {
                    op: CastOp::IntToPtr,
                    ..
                }
            )),
            0,
            "tagged EXISTS must iterate the compact set branch without pointer fallback"
        );
        assert!(
            has_runtime_error_status_path(&module, 0),
            "tagged EXISTS must retain a runtime type guard for scalar-tagged slots"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::Sub,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "tagged EXISTS should decode set payloads as -1 - raw"
        );
    }

