    #[test]
    fn test_func_except_model_value_keyed_raw_compact_state_function_updates_const_path() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let _procs = pool.add_value(Value::set([
            Value::ModelValue(Rp::from("p1")),
            Value::ModelValue(Rp::from("p2")),
            Value::ModelValue(Rp::from("p3")),
            Value::ModelValue(Rp::from("p4")),
        ]));
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));
        let li2 = pool.add_value(Value::String("Li2".into()));

        let mut func = BytecodeFunction::new("model_value_keyed_string_func_except".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: p2 });
        func.emit(Opcode::LoadConst { rd: 2, idx: li2 });
        func.emit(Opcode::FuncExcept {
            rd: 3,
            func: 0,
            path: 1,
            val: 2,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 3 });
        func.emit(Opcode::LoadBool { rd: 4, value: true });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::String),
            value_layout: Box::new(CompoundLayout::String),
            pair_count: Some(4),
            domain_lo: None,
        })]);

        let module = lower_next_state(
            &func,
            "model_value_keyed_string_func_except",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("model-value-keyed compact FuncExcept should use recovered domain metadata");

        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "constant-path model-value-keyed compact FuncExcept should keep static allocation counts"
        );
        assert!(
            has_const_alloca_count(&module, 0, 4),
            "FuncExcept feeding StoreVar should materialize a fixed-width 4-slot replacement buffer"
        );
        assert!(
            !has_select_inst(&module, 0),
            "constant-path model-value-keyed compact FuncExcept should overwrite the indexed slot directly"
        );
    }

    #[test]
    fn test_func_except_model_value_keyed_raw_slot_recovers_layout_domain_after_metadata_drop() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));
        let li2 = pool.add_value(Value::String("Li2".into()));

        let mut func = BytecodeFunction::new(
            "model_value_keyed_func_except_recover_raw_slot_domain".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: p2 });
        func.emit(Opcode::LoadConst { rd: 2, idx: li2 });
        func.emit(Opcode::FuncExcept {
            rd: 3,
            func: 0,
            path: 1,
            val: 2,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 3 });
        func.emit(Opcode::LoadBool { rd: 4, value: true });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::ExplicitScalarDomain {
                key_layout: Box::new(CompoundLayout::String),
                keys: ["p1", "p2", "p3", "p4"]
                    .into_iter()
                    .map(|name| SetBitmaskElement::ModelValue(tla_core::intern_name(name)))
                    .collect(),
            }),
            value_layout: Box::new(CompoundLayout::String),
            pair_count: Some(4),
            domain_lo: None,
        })]);

        let mut ctx = Ctx::new(
            &func,
            "model_value_keyed_func_except_recover_raw_slot_domain",
            LoweringMode::NextState,
            Some(&pool),
            Some(&layout),
            None,
        )
        .expect("test context should initialize");
        let mut block = ctx
            .block_index_for_pc(0)
            .expect("entry block should exist for test function");

        for (pc, opcode) in func.instructions.iter().enumerate().take(3) {
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap_or_else(|err| panic!("lowering pc {pc} opcode {opcode:?} failed: {err}"))
                .unwrap_or(block);
        }

        assert!(
            ctx.compact_function_domains.remove(&0).is_some(),
            "LoadVar should initially track the explicit function domain"
        );

        for (pc, opcode) in func.instructions.iter().enumerate().skip(3) {
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap_or_else(|err| panic!("lowering pc {pc} opcode {opcode:?} failed: {err}"))
                .unwrap_or(block);
        }
        assert!(
            ctx.compact_function_domains.contains_key(&3),
            "FuncExcept should recover explicit-domain metadata from the raw state slot"
        );

        let module = ctx.finish();
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "recovered-domain compact FuncExcept should keep static allocation counts"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

