    #[test]
    fn test_store_var_compact_physical_layout_allows_exact_model_value_mask_but_not_unknown() {
        let scalar_function = AggregateShape::Function {
            len: 4,
            domain_lo: None,
            domain: None,
            value: Some(Box::new(AggregateShape::Scalar(ScalarShape::String))),
        };
        let exact_mask_function = AggregateShape::Function {
            len: 4,
            domain_lo: None,
            domain: None,
            value: Some(Box::new(AggregateShape::SetBitmask {
                universe_len: 4,
                universe: SetBitmaskUniverse::Exact(vec![
                    SetBitmaskElement::ModelValue(tla_core::intern_name("p1")),
                    SetBitmaskElement::ModelValue(tla_core::intern_name("p2")),
                    SetBitmaskElement::ModelValue(tla_core::intern_name("p3")),
                    SetBitmaskElement::ModelValue(tla_core::intern_name("p4")),
                ]),
            })),
        };
        let unknown_mask_function = AggregateShape::Function {
            len: 4,
            domain_lo: None,
            domain: None,
            value: Some(Box::new(AggregateShape::SetBitmask {
                universe_len: 4,
                universe: SetBitmaskUniverse::Unknown,
            })),
        };

        assert!(Ctx::same_store_var_compact_physical_layout(
            &exact_mask_function,
            &scalar_function
        ));
        assert!(Ctx::same_store_var_compact_physical_layout(
            &scalar_function,
            &exact_mask_function
        ));
        assert!(!Ctx::same_store_var_compact_physical_layout(
            &unknown_mask_function,
            &scalar_function
        ));
        assert!(!Ctx::same_store_var_compact_physical_layout(
            &scalar_function,
            &unknown_mask_function
        ));
    }

