    #[test]
    fn test_func_except_model_value_keyed_sequence_value_copies_compact_slots() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let _procs = pool.add_value(Value::set([
            Value::ModelValue(Rp::from("p1")),
            Value::ModelValue(Rp::from("p2")),
            Value::ModelValue(Rp::from("p3")),
            Value::ModelValue(Rp::from("p4")),
        ]));
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));

        let mut func =
            BytecodeFunction::new("model_value_keyed_sequence_func_except".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: p2 });
        func.emit(Opcode::LoadImm { rd: 2, value: 7 });
        func.emit(Opcode::LoadImm { rd: 3, value: 8 });
        func.emit(Opcode::SeqNew {
            rd: 4,
            start: 2,
            count: 2,
        });
        func.emit(Opcode::FuncExcept {
            rd: 5,
            func: 0,
            path: 1,
            val: 4,
        });
        func.emit(Opcode::StoreVar { var_idx: 1, rs: 5 });
        func.emit(Opcode::LoadBool { rd: 6, value: true });
        func.emit(Opcode::Ret { rs: 6 });

        let compact_proc_to_seq = VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::String),
            value_layout: Box::new(CompoundLayout::Sequence {
                capacity_proven: false,
                element_layout: Box::new(CompoundLayout::Int),
                element_count: Some(2),
            }),
            pair_count: Some(4),
            domain_lo: None,
        });
        let layout = StateLayout::new(vec![compact_proc_to_seq.clone(), compact_proc_to_seq]);

        let module = lower_next_state(
            &func,
            "model_value_keyed_sequence_func_except",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("model-value FuncExcept with sequence values should copy compact value slots");

        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "multi-slot explicit-domain FuncExcept should keep static allocation counts"
        );
        assert!(
            has_const_alloca_count(&module, 0, 12),
            "four sequence values should materialize as 4 * 3 compact slots"
        );
        assert!(
            !has_select_inst(&module, 0),
            "constant multi-slot FuncExcept should not need dynamic key selects"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
    }

