    #[test]
    fn test_lower_compact_set_filter_over_setbitmask_preserves_mask_native_result() {
        let mut func = BytecodeFunction::new("compact_setfilter_setbitmask_result".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        let begin_pc = func.emit(Opcode::SetFilterBegin {
            rd: 1,
            r_binding: 2,
            r_domain: 0,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm { rd: 3, value: 1 });
        func.emit(Opcode::GtInt {
            rd: 4,
            r1: 2,
            r2: 3,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 2,
            r_body: 4,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);

        func.emit(Opcode::LoadImm { rd: 5, value: 2 });
        func.emit(Opcode::SetIn {
            rd: 6,
            elem: 5,
            set: 1,
        });
        func.emit(Opcode::LoadVar { rd: 7, var_idx: 1 });
        func.emit(Opcode::SetIntersect {
            rd: 8,
            r1: 1,
            r2: 7,
        });
        func.emit(Opcode::Eq {
            rd: 9,
            r1: 8,
            r2: 1,
        });
        func.emit(Opcode::Ret { rs: 9 });

        let bitmask = || VarLayout::Compound(int_range_set_bitmask_layout(1, 4));
        let layout = StateLayout::new(vec![bitmask(), bitmask()]);
        let module = lower_invariant(
            &func,
            "compact_setfilter_setbitmask_result",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("SetFilter over compact SetBitmask should preserve a mask-native result");

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::Or,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "accepted SetFilter bindings should be appended by OR-ing a universe bit into the result mask"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::And,
                    ty: Ty::I64,
                    ..
                }
            )) >= 4,
            "membership, intersection, and equality after SetFilter should stay on mask-native lowering"
        );
        assert!(
            !has_const_alloca_count(&module, 0, 5),
            "SetFilter over a four-element compact SetBitmask should not allocate a five-slot materialized result"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "compact SetFilter result should not introduce dynamic aggregate allocation"
        );
    }

