    #[test]
    fn test_lower_tagged_scalar_or_set_eq_finite_model_value_set_decodes_set_branch() {
        use std::sync::Arc;

        let p1 = tla_core::intern_name("p1");
        let p2 = tla_core::intern_name("p2");
        let universe = vec![
            SetBitmaskElement::ModelValue(p1),
            SetBitmaskElement::ModelValue(p2),
        ];
        let mut pool = ConstantPool::new();
        let finite = pool.add_value(Value::set([Value::ModelValue(Rp::from("p2"))]));

        let mut func = BytecodeFunction::new("tagged_scalar_or_set_eq_finite_set".to_string(), 0);
        func.emit(Opcode::LoadImm {
            rd: 0,
            value: -1 - (1_i64 << 1),
        });
        func.emit(Opcode::LoadConst { rd: 1, idx: finite });
        func.emit(Opcode::Eq {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        func.emit(Opcode::Ret { rs: 2 });

        let mut ctx = Ctx::new(
            &func,
            "tagged_scalar_or_set_eq_finite_set",
            LoweringMode::Invariant,
            Some(&pool),
            None,
            None,
        )
        .unwrap();
        let mut block = ctx.block_index_for_pc(0).unwrap();
        for (pc, opcode) in func.instructions.iter().enumerate() {
            ctx.aggregate_shapes.insert(
                0,
                AggregateShape::TaggedScalarOrSet {
                    scalar: ScalarShape::ModelValue,
                    universe_len: u32::try_from(universe.len()).unwrap(),
                    universe: SetBitmaskUniverse::from_elements(&universe),
                    proof_source: tla_core::intern_name("TaggedScalarOrSetEqTest"),
                },
            );
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap()
                .unwrap_or(block);
        }
        let module = ctx.finish();

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::Sub,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "tagged scalar-or-set set branch should decode -1-mask into a mask"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "tagged scalar-or-set equality with exact finite set should not use dynamic set loops"
        );
    }

