    #[test]
    fn test_lower_state_compact_set_bitmask_eq_neq_exact_set_compares_mask_slot() {
        let cases = [
            (
                "state_compact_set_bitmask_eq_exact_set",
                Opcode::Eq {
                    rd: 5,
                    r1: 0,
                    r2: 4,
                },
            ),
            (
                "state_compact_set_bitmask_neq_exact_set",
                Opcode::Neq {
                    rd: 5,
                    r1: 0,
                    r2: 4,
                },
            ),
        ];

        for (name, comparison) in cases {
            let mut func = BytecodeFunction::new(name.to_string(), 0);
            func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
            func.emit(Opcode::LoadImm { rd: 1, value: 1 });
            func.emit(Opcode::LoadImm { rd: 2, value: 2 });
            func.emit(Opcode::LoadImm { rd: 3, value: 3 });
            func.emit(Opcode::SetEnum {
                rd: 4,
                start: 1,
                count: 3,
            });
            func.emit(comparison);
            func.emit(Opcode::Ret { rs: 5 });

            let layout = StateLayout::new(vec![VarLayout::Compound(int_range_set_bitmask_layout(
                1, 3,
            ))]);
            let module = lower_invariant(
                &func,
                name,
                LoweringOptions::new()
                    .with_constants(&ConstantPool::new())
                    .with_layout(&layout),
            )
            .expect("compact SetBitmask equality should compare state masks by value");

            assert!(
                has_i64_icmp_against_const_from_state_slot(&module, 0, ICmpOp::Eq, 0, 0b111),
                "{name} must compare the compact state SetBitmask slot against the exact SetEnum mask"
            );
            assert!(
                !has_nonconst_alloca_count(&module, 0),
                "{name} should stay on the mask-native path"
            );
        }
    }

    /// WP-08 (item 6): this WAS the pinned rejection
    /// `test_reject_compact_set_bitmask_union_with_generic_materialized_set_operand`.
    /// The dynamic small-set write conversion now accepts a same-sort scalar
    /// materialized operand through the fail-closed runtime loop, so the pin
    /// flips to: compiles, and carries the runtime TypeMismatch error branch
    /// (out-of-universe element => typed runtime error, never a silent drop).
    #[test]
    fn test_compact_set_bitmask_union_accepts_dynamic_materialized_set_operand() {
        let mut func = BytecodeFunction::new(
            "compact_set_bitmask_union_dynamic_materialized_set".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadVar { rd: 1, var_idx: 1 });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 1,
            count: 1,
        });
        func.emit(Opcode::SetUnion {
            rd: 3,
            r1: 0,
            r2: 2,
        });
        func.emit(Opcode::Ret { rs: 3 });

        let layout = StateLayout::new(vec![
            VarLayout::Compound(int_range_set_bitmask_layout(1, 4)),
            VarLayout::ScalarInt,
        ]);
        let module = lower_invariant(
            &func,
            "compact_setbitmask_union_dynamic_materialized_set",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect(
            "dynamic same-sort materialized set operand should convert to a mask via the \
             fail-closed runtime loop",
        );

        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::Shl,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "dynamic element should compute its universe bit at runtime (shl)"
        );
        assert!(
            has_runtime_error_status_path(&module, 0),
            "out-of-universe element must reach a typed runtime-error branch (fail closed), \
             never a silent drop"
        );
    }

    /// WP-08 (item 6): the original wall stays pinned for operands the
    /// fail-closed loop cannot admit — here a materialized set whose element
    /// shape is NOT a same-sort scalar (a nested set element).
    #[test]
    fn test_reject_compact_set_bitmask_union_with_nonscalar_materialized_set_operand() {
        let mut func = BytecodeFunction::new(
            "compact_set_bitmask_union_nonscalar_materialized_set".to_string(),
            0,
        );
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        // r1 = {} (a set), r2 = {{}} — element shape is a set, not a scalar.
        func.emit(Opcode::SetEnum {
            rd: 1,
            start: 1,
            count: 0,
        });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 1,
            count: 1,
        });
        func.emit(Opcode::SetUnion {
            rd: 3,
            r1: 0,
            r2: 2,
        });
        func.emit(Opcode::Ret { rs: 3 });

        let layout = StateLayout::new(vec![
            VarLayout::Compound(int_range_set_bitmask_layout(1, 4)),
            VarLayout::ScalarInt,
        ]);
        let err = lower_invariant(
            &func,
            "compact_setbitmask_union_nonscalar_materialized_set",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect_err("non-scalar materialized set elements must keep failing closed");

        let message = format!("{err}");
        assert!(
            message.contains("cannot infer") && message.contains("compact SetBitmask universe"),
            "error should reject the non-scalar materialized compact conversion: {message}"
        );
    }

