    /// Count `Inst::Const { Int(value) }` occurrences matching `value` in func 0.
    fn int_const_count(module: &trust_ir::Module, value: i128) -> usize {
        module.functions[0]
            .blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter(|node| {
                matches!(
                    &node.inst,
                    Inst::Const {
                        value: Constant::Int(v),
                        ..
                    } if *v == value
                )
            })
            .count()
    }

    /// `IsFiniteSet` over a known-finite set shape (a `SetEnum` of int literals)
    /// must natively fold to the constant boolean `true` (i64 `1`) with NO
    /// aggregate allocation — purely a compile-time shape classification.
    #[test]
    fn test_lower_is_finite_set_finite_shape_folds_true() {
        use tla_tir::bytecode::BuiltinOp;
        let mut func = BytecodeFunction::new("is_finite_finite".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::LoadImm { rd: 2, value: 3 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 0,
            count: 3,
        });
        func.emit(Opcode::CallBuiltin {
            rd: 4,
            builtin: BuiltinOp::IsFiniteSet,
            args_start: 3,
            argc: 1,
        });
        func.emit(Opcode::Ret { rs: 4 });

        // BEFORE this arm existed, IsFiniteSet hit the CallBuiltin catch-all and
        // returned UnsupportedOpcode (VM fallback). AFTER, it lowers cleanly.
        let module = lower_invariant(&func, "is_finite_finite", LoweringOptions::new())
            .expect("IsFiniteSet over a finite set shape must lower natively");
        assert_eq!(module.functions.len(), 1);
        assert!(
            int_const_count(&module, 1) >= 1,
            "IsFiniteSet over a finite set should fold to the constant boolean true (i64 1)"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "IsFiniteSet is a scalar Bool fold and must not materialize an aggregate"
        );
    }

    /// `IsFiniteSet` over an unconditionally-infinite symbolic numeric domain
    /// (`Nat`) must natively fold to the constant boolean `false` (i64 `0`).
    #[test]
    fn test_lower_is_finite_set_symbolic_domain_folds_false() {
        use std::sync::Arc;
        use tla_tir::bytecode::BuiltinOp;
        let mut pool = ConstantPool::new();
        let nat_idx = pool.add_value(Value::ModelValue(Rp::from("Nat")));

        let mut func = BytecodeFunction::new("is_finite_nat".to_string(), 0);
        func.emit(Opcode::LoadConst {
            rd: 0,
            idx: nat_idx,
        });
        func.emit(Opcode::CallBuiltin {
            rd: 1,
            builtin: BuiltinOp::IsFiniteSet,
            args_start: 0,
            argc: 1,
        });
        func.emit(Opcode::Ret { rs: 1 });

        let module = lower_invariant(
            &func,
            "is_finite_nat",
            LoweringOptions::new().with_constants(&pool),
        )
        .expect("IsFiniteSet over the symbolic Nat domain must lower natively");
        assert_eq!(module.functions.len(), 1);
        assert!(
            int_const_count(&module, 0) >= 1,
            "IsFiniteSet over the infinite Nat domain should fold to the constant boolean false (i64 0)"
        );
    }

    /// Fail-closed: `IsFiniteSet` over an untracked `StateValue` (a bare
    /// `LoadVar` with no layout metadata) cannot be proven finite-or-infinite at
    /// compile time, so it must return `UnsupportedOpcode` (VM fallback) rather
    /// than guess. This is the soundness guarantee.
    #[test]
    fn test_lower_is_finite_set_unknown_shape_fails_closed() {
        use tla_tir::bytecode::BuiltinOp;
        let mut func = BytecodeFunction::new("is_finite_unknown".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::CallBuiltin {
            rd: 1,
            builtin: BuiltinOp::IsFiniteSet,
            args_start: 0,
            argc: 1,
        });
        func.emit(Opcode::Ret { rs: 1 });

        // `lower_opcode`'s `UnsupportedOpcode` is wrapped by `lower_body` into a
        // top-level `TrustIrError::Emission("while lowering function ...: <inner>")`
        // — the exact same path the pre-existing CallBuiltin catch-all takes, and
        // the path the trust-cg compiler already treats as a per-action VM
        // fallback (not a hard error). Assert the fail-closed diagnostic surfaces.
        let err = lower_invariant(&func, "is_finite_unknown", LoweringOptions::new())
            .expect_err("IsFiniteSet over an unknown shape must fail closed to the VM");
        let message = format!("{err}");
        assert!(
            message.contains("CallBuiltin(IsFiniteSet)")
                && message.contains("not provably finite-or-infinite"),
            "IsFiniteSet over an unknown shape must fail closed with the shape-classification \
             diagnostic, got: {message}"
        );
    }

    #[test]
    fn test_lower_compact_set_bitmask_cardinality_uses_mask_not_pointer() {
        use tla_tir::bytecode::BuiltinOp;

        let mut func = BytecodeFunction::new("compact_set_bitmask_cardinality".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::CallBuiltin {
            rd: 1,
            builtin: BuiltinOp::Cardinality,
            args_start: 0,
            argc: 1,
        });
        func.emit(Opcode::Ret { rs: 1 });

        let layout = StateLayout::new(vec![VarLayout::Compound(int_range_set_bitmask_layout(
            1, 4,
        ))]);
        let module = lower_invariant(
            &func,
            "compact_set_bitmask_cardinality",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("exact compact SetBitmask Cardinality should lower mask-native");

        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::Cast {
                    op: CastOp::IntToPtr,
                    ..
                }
            )),
            0,
            "compact SetBitmask Cardinality must not reinterpret the mask as an aggregate pointer"
        );
        assert_eq!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::UnOp {
                    op: UnOp::CtPop,
                    ty: Ty::I64,
                    ..
                }
            )),
            1,
            "compact SetBitmask Cardinality should count the masked u64 with ctpop"
        );
        assert_eq!(
            inst_count(&module, 0, |inst| matches!(inst, Inst::Select { .. })),
            0,
            "compact SetBitmask Cardinality should not emit the old per-bit select/add loop"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "compact SetBitmask Cardinality should not materialize an aggregate set"
        );
    }

