    #[test]
    fn test_scalar_builtin_results_clear_stale_compact_metadata() {
        use tla_tir::bytecode::BuiltinOp;

        fn seed_stale_compact_function_metadata(ctx: &mut Ctx<'_>, reg: u8) {
            ctx.aggregate_shapes.insert(
                reg,
                AggregateShape::Function {
                    len: 2,
                    domain_lo: None,
                    domain: None,
                    value: Some(Box::new(AggregateShape::Scalar(ScalarShape::Int))),
                },
            );
            ctx.compact_function_domains
                .insert(reg, CompactFunctionDomain::Raw(vec![1, 2]));
            ctx.flat_funcdef_pair_list_regs.insert(reg);
        }

        let mut cardinality =
            BytecodeFunction::new("cardinality_clears_stale_compact_metadata".to_string(), 0);
        cardinality.emit(Opcode::LoadImm { rd: 1, value: 1 });
        cardinality.emit(Opcode::LoadImm { rd: 2, value: 2 });
        cardinality.emit(Opcode::SetEnum {
            rd: 3,
            start: 1,
            count: 2,
        });
        cardinality.emit(Opcode::CallBuiltin {
            rd: 0,
            builtin: BuiltinOp::Cardinality,
            args_start: 3,
            argc: 1,
        });
        cardinality.emit(Opcode::Ret { rs: 0 });
        let mut ctx = Ctx::new(
            &cardinality,
            "cardinality_clears_stale_compact_metadata",
            LoweringMode::Invariant,
            None,
            None,
            None,
        )
        .expect("test context should initialize");
        seed_stale_compact_function_metadata(&mut ctx, 0);
        ctx.lower_body(&cardinality)
            .expect("Cardinality should lower");
        assert_eq!(
            ctx.aggregate_shapes.get(&0),
            Some(&AggregateShape::Scalar(ScalarShape::Int))
        );
        assert!(!ctx.compact_function_domains.contains_key(&0));
        assert!(!ctx.flat_funcdef_pair_list_regs.contains(&0));

        let mut len = BytecodeFunction::new("len_clears_stale_compact_metadata".to_string(), 0);
        len.emit(Opcode::LoadImm { rd: 1, value: 10 });
        len.emit(Opcode::LoadImm { rd: 2, value: 20 });
        len.emit(Opcode::SeqNew {
            rd: 3,
            start: 1,
            count: 2,
        });
        len.emit(Opcode::CallBuiltin {
            rd: 0,
            builtin: BuiltinOp::Len,
            args_start: 3,
            argc: 1,
        });
        len.emit(Opcode::Ret { rs: 0 });
        let mut ctx = Ctx::new(
            &len,
            "len_clears_stale_compact_metadata",
            LoweringMode::Invariant,
            None,
            None,
            None,
        )
        .expect("test context should initialize");
        seed_stale_compact_function_metadata(&mut ctx, 0);
        ctx.lower_body(&len).expect("Len should lower");
        assert_eq!(
            ctx.aggregate_shapes.get(&0),
            Some(&AggregateShape::Scalar(ScalarShape::Int))
        );
        assert!(!ctx.compact_function_domains.contains_key(&0));
        assert!(!ctx.flat_funcdef_pair_list_regs.contains(&0));
    }

