    /// Helper: build a `SubSeq(<<v0..>>, lo, hi)` invariant bytecode function
    /// over a freshly-built `count`-element flat sequence.
    fn build_subseq_invariant(name: &str, count: u8, lo: i64, hi: i64) -> BytecodeFunction {
        use tla_tir::bytecode::BuiltinOp;
        let mut func = BytecodeFunction::new(name.to_string(), 0);
        for i in 0..count {
            func.emit(Opcode::LoadImm {
                rd: i,
                value: 10 * (i64::from(i) + 1),
            });
        }
        let seq_reg = count;
        func.emit(Opcode::SeqNew {
            rd: seq_reg,
            start: 0,
            count,
        });
        let lo_reg = seq_reg + 1;
        let hi_reg = seq_reg + 2;
        func.emit(Opcode::LoadImm {
            rd: lo_reg,
            value: lo,
        });
        func.emit(Opcode::LoadImm {
            rd: hi_reg,
            value: hi,
        });
        let rd = seq_reg + 3;
        func.emit(Opcode::CallBuiltin {
            rd,
            builtin: BuiltinOp::SubSeq,
            args_start: seq_reg,
            argc: 3,
        });
        func.emit(Opcode::Ret { rs: rd });
        func
    }

    /// Count `Inst::Call` instructions across a lowered function. The flat trust-ir
    /// SubSeq lowering must use an indexed copy loop and emit ZERO calls — in
    /// particular it must NOT invoke the handle-based runtime `@tla_seq_subseq`.
    fn inst_call_count(module: &trust_ir::Module, func_idx: usize) -> usize {
        module.functions[func_idx]
            .blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter(|node| matches!(&node.inst, Inst::Call { .. }))
            .count()
    }

    /// VERIFY-FIRST companion: SubSeq used to hit the CallBuiltin catch-all and
    /// return `UnsupportedOpcode("CallBuiltin(SubSeq)")`. After native lowering
    /// it must lower to `Ok`, allocate a fresh aggregate via a copy loop, and
    /// emit no runtime call.
    #[test]
    fn test_lower_seq_subseq_lowers_natively_without_runtime_call() {
        let func = build_subseq_invariant("subseq_native", 3, 2, 3);
        let module = lower_invariant(&func, "subseq_native", LoweringOptions::new())
            .expect("SubSeq should now lower natively in the trust-ir pipeline");
        assert_eq!(module.functions.len(), 1);
        // The copy loop plus the empty/bounds/error branches create several
        // auxiliary blocks.
        assert!(
            module.functions[0].blocks.len() >= 5,
            "expected >= 5 blocks for the SubSeq copy loop and clamp branches, got {}",
            module.functions[0].blocks.len()
        );
        // A length-changing flat op: it allocates a dynamically-sized aggregate
        // from the runtime sub-range length.
        assert!(
            has_nonconst_alloca_count(&module, 0),
            "SubSeq should allocate a new aggregate sized from the runtime sub-range length"
        );
        // Pure flat manipulation: no @tla_seq_subseq (or any other) runtime call.
        assert_eq!(
            inst_call_count(&module, 0),
            0,
            "SubSeq native lowering must not emit any runtime Call (e.g. @tla_seq_subseq)"
        );
    }

    /// `lo > hi` collapses to the empty-sequence branch; the dispatch still
    /// lowers cleanly and avoids the runtime helper.
    #[test]
    fn test_lower_seq_subseq_empty_range_lo_gt_hi() {
        let func = build_subseq_invariant("subseq_empty_range", 3, 3, 1);
        let module = lower_invariant(&func, "subseq_empty_range", LoweringOptions::new())
            .expect("SubSeq with lo>hi should lower to the empty-range branch");
        assert_eq!(inst_call_count(&module, 0), 0);
        // There must be a constant-0 length store path (the empty aggregate).
        assert!(
            has_const_alloca_count(&module, 0, 1),
            "empty SubSeq result should allocate a single length slot"
        );
    }

    /// `hi > Len(s)` is an out-of-range bound (with lo<=hi): the lowering keeps a
    /// runtime-error path so the model checker falls back to the interpreter for
    /// the precise IndexOutOfBounds, mirroring the bytecode VM.
    #[test]
    fn test_lower_seq_subseq_out_of_range_keeps_error_path() {
        let func = build_subseq_invariant("subseq_oob", 3, 1, 9);
        let module = lower_invariant(&func, "subseq_oob", LoweringOptions::new())
            .expect("SubSeq with hi>len should still lower (with a runtime-error guard)");
        assert_eq!(inst_call_count(&module, 0), 0);
        // The bounds check introduces multiple conditional branches (lo>hi,
        // in-bounds, and the loop header).
        assert!(
            condbr_count(&module, 0) >= 2,
            "SubSeq should emit the lo>hi and in-bounds conditional branches, got {}",
            condbr_count(&module, 0)
        );
    }

    /// Shape propagation: SubSeq over a known-shaped sequence yields a
    /// capacity-bounded sequence with the element shape preserved.
    #[test]
    fn test_subseq_shape_is_capacity_bounded_with_preserved_element() {
        let seq = AggregateShape::Sequence {
            extent: SequenceExtent::Exact(3),
            element: Some(Box::new(AggregateShape::Scalar(ScalarShape::Int))),
        };
        let shape = sequence_subseq_shape(Some(&seq))
            .expect("subseq shape should be derivable from a known sequence shape");
        match shape {
            AggregateShape::Sequence { extent, element } => {
                assert_eq!(
                    extent,
                    SequenceExtent::Capacity(3),
                    "result extent should be capacity-bounded by the source"
                );
                assert_eq!(
                    element.as_deref(),
                    Some(&AggregateShape::Scalar(ScalarShape::Int)),
                    "result element shape should be preserved from the source"
                );
            }
            other => panic!("expected Sequence shape, got {other:?}"),
        }
        // A capacity-bounded source stays capacity-bounded.
        let cap_seq = AggregateShape::Sequence {
            extent: SequenceExtent::Capacity(5),
            element: None,
        };
        assert_eq!(
            sequence_subseq_shape(Some(&cap_seq)),
            Some(AggregateShape::Sequence {
                extent: SequenceExtent::Capacity(5),
                element: None,
            })
        );
        // Non-sequence operands produce no shape.
        assert_eq!(
            sequence_subseq_shape(Some(&AggregateShape::Scalar(ScalarShape::Int))),
            None
        );
    }

