    #[test]
    fn test_lower_set_builder_invariant_setenum_constant_body_deduplicates_cardinality() {
        use tla_tir::bytecode::BuiltinOp;

        let mut func = BytecodeFunction::new("set_builder_setenum".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::LoadImm { rd: 2, value: 3 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 0,
            count: 3,
        });

        let begin_pc = func.emit(Opcode::SetBuilderBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 3,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm { rd: 6, value: 42 });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 5,
            r_body: 6,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::CallBuiltin {
            rd: 7,
            builtin: BuiltinOp::Cardinality,
            args_start: 4,
            argc: 1,
        });
        func.emit(Opcode::LoadImm { rd: 8, value: 1 });
        func.emit(Opcode::Eq {
            rd: 9,
            r1: 7,
            r2: 8,
        });
        func.emit(Opcode::Ret { rs: 9 });

        let module = lower_invariant(&func, "set_builder_setenum", LoweringOptions::new())
            .expect("SetBuilderBegin over SetEnum should lower in invariants");
        assert!(
            module.functions[0].blocks.len() >= 5,
            "expected SetBuilder CFG blocks, got {}",
            module.functions[0].blocks.len()
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "SetBuilder over fixed SetEnum should allocate a fixed-capacity result"
        );
        assert_eq!(
            condbr_count(&module, 0),
            4,
            "SetBuilder dedups via a hash probe before append so a constant body \
             has cardinality 1: one condbr zero-fills the hash side index, one \
             drives the domain iteration, and two probe the table (empty-slot \
             check + value compare)"
        );
    }

