    /// `{ x + 3 : x \in 1..9 }` is a scalar-bodied comprehension. This pins
    /// down the hash-based dedup path introduced to make set construction O(n)
    /// amortized instead of O(n^2):
    ///
    /// * It lowers successfully, so the hash path accepts a scalar
    ///   (slot-identity) body shape.
    /// * It emits `URem` BinOps, which only the hash-probe dedup produces — the
    ///   URem is the *hash modulus* / probe wraparound, not the body op — so its
    ///   presence proves the optimized dedup path is active rather than the
    ///   replaced linear scan.
    /// * The `1..9` interval is statically bounded, so neither the result buffer
    ///   nor the hash side index introduces a dynamic-count `alloca`; the table
    ///   is sized with the same compile-time-constant discipline as the result.
    ///
    /// (Historically this test used a `x % 3` body; it now uses a non-div/mod
    /// scalar so the asserted URem is unambiguously the hash probe's, not the
    /// body's — the `%`-bodied comprehension is covered by
    /// `test_lower_set_builder_modulo_body_lowers_natively`.)
    #[test]
    fn test_lower_set_builder_scalar_body_uses_hash_dedup_and_stays_fixed_capacity() {
        use tla_tir::bytecode::BuiltinOp;

        let mut func = BytecodeFunction::new("set_builder_scalar".to_string(), 0);
        // domain = 1 .. 9
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 9 });
        func.emit(Opcode::Range {
            rd: 2,
            lo: 0,
            hi: 1,
        });
        // addend constant 3, kept live across the loop body
        func.emit(Opcode::LoadImm { rd: 3, value: 3 });

        let begin_pc = func.emit(Opcode::SetBuilderBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 2,
            loop_end: 0,
        });
        // body: r6 = binding + 3  (scalar slot-identity shape, no div/mod)
        func.emit(Opcode::AddInt {
            rd: 6,
            r1: 5,
            r2: 3,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 5,
            r_body: 6,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        // `{ x + 3 : x \in 1..9 }` has 9 distinct elements.
        func.emit(Opcode::CallBuiltin {
            rd: 7,
            builtin: BuiltinOp::Cardinality,
            args_start: 4,
            argc: 1,
        });
        func.emit(Opcode::LoadImm { rd: 8, value: 9 });
        func.emit(Opcode::Eq {
            rd: 9,
            r1: 7,
            r2: 8,
        });
        func.emit(Opcode::Ret { rs: 9 });

        let module = lower_invariant(&func, "set_builder_scalar", LoweringOptions::new())
            .expect("`{ x + 3 : x \\in 1..9 }` should lower with hash-based dedup");

        assert!(
            binop_count(&module, 0, BinOp::URem) > 0,
            "the hash-probe dedup must emit URem (hash modulus + probe wraparound); \
             its presence proves the optimized dedup path is active rather than the \
             replaced linear scan"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "a statically bounded 1..9 domain must keep both the result buffer and \
             the hash side index at a compile-time-constant capacity"
        );
    }

    /// A comprehension whose body uses `%` lowers natively: the `ModInt`
    /// lowering implements the interpreter's Euclidean semantics (with the
    /// strictly-positive-divisor guard), so `{ x % 3 : x \in 1..9 }` builds
    /// the correct `{0, 1, 2}` set (Cardinality 3) in native code.
    #[test]
    fn test_lower_set_builder_modulo_body_lowers_natively() {
        use tla_tir::bytecode::BuiltinOp;

        let mut func = BytecodeFunction::new("set_builder_modulo".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 9 });
        func.emit(Opcode::Range {
            rd: 2,
            lo: 0,
            hi: 1,
        });
        func.emit(Opcode::LoadImm { rd: 3, value: 3 });

        let begin_pc = func.emit(Opcode::SetBuilderBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 2,
            loop_end: 0,
        });
        // body: r6 = binding % 3  — must decline
        func.emit(Opcode::ModInt {
            rd: 6,
            r1: 5,
            r2: 3,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 5,
            r_body: 6,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::CallBuiltin {
            rd: 7,
            builtin: BuiltinOp::Cardinality,
            args_start: 4,
            argc: 1,
        });
        func.emit(Opcode::LoadImm { rd: 8, value: 3 });
        func.emit(Opcode::Eq {
            rd: 9,
            r1: 7,
            r2: 8,
        });
        func.emit(Opcode::Ret { rs: 9 });

        let module = lower_invariant(&func, "set_builder_modulo", LoweringOptions::new())
            .expect("a `%`-bodied comprehension should lower natively (Euclidean ModInt)");
        assert!(
            binop_count(&module, 0, BinOp::SRem) >= 1,
            "the `%` body must emit srem inside the comprehension loop"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::ICmp {
                    op: ICmpOp::Sle,
                    ty: Ty::I64,
                    ..
                }
            )) >= 1,
            "the `%` body must carry the strictly-positive-divisor (b <= 0) guard"
        );
    }

    #[test]
    fn test_lower_set_builder_record_body_fails_closed_until_structural_dedup() {
        let mut pool = ConstantPool::new();
        let field_start = pool.add_value(Value::String("a".into()));

        let mut func = BytecodeFunction::new("set_builder_record_body".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });

        let begin_pc = func.emit(Opcode::SetBuilderBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm { rd: 5, value: 42 });
        func.emit(Opcode::RecordNew {
            rd: 6,
            fields_start: field_start,
            values_start: 5,
            count: 1,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 4,
            r_body: 6,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: 3 });

        let error = lower_invariant(
            &func,
            "set_builder_record_body",
            LoweringOptions::new().with_constants(&pool),
        )
        .expect_err("record-valued SetBuilder body requires structural dedup lowering");
        assert!(
            error
                .to_string()
                .contains("requires structural set-builder deduplication"),
            "{error}"
        );
    }

    /// `{ <<x % 2, x % 2>> : x \in 0..3 }` is a comprehension over a
    /// *fixed-extent tuple-of-scalars* body. Such a body must currently
    /// **fail closed**: the native set-builder cannot deduplicate (nor can any
    /// downstream `\in`/CHOOSE consume) a set of tuples soundly, because each
    /// tuple is materialized as a *pointer* to a `[arity, e1, ..., ek]` buffer
    /// the loop body re-`alloca`s every iteration, and the trust-cg backend
    /// assigns every such loop-body `alloca` a *single reused* stack slot. Stored
    /// pointers therefore all alias the *last* tuple, corrupting the set past its
    /// final element (empirically: a membership probe against `(1..3) \X (1..2)`,
    /// which `lower_times` builds the same way, finds only the last tuple). A raw
    /// i64-slot dedup would additionally compare pointer identity, not TLA+ value
    /// equality. Until a stable per-element backing arena (allocated outside the
    /// loop) exists, the lowering must reject tuple bodies so the whole spec
    /// falls back to the interpreter rather than silently diverging.
    ///
    /// This test pins that fail-closed contract: lowering returns `Err`.
    #[test]
    fn test_lower_set_builder_tuple_body_fails_closed() {
        use tla_tir::bytecode::BuiltinOp;

        let mut func = BytecodeFunction::new("set_builder_tuple_fail_closed".to_string(), 0);
        // domain = 0 .. 3
        func.emit(Opcode::LoadImm { rd: 0, value: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: 3 });
        func.emit(Opcode::Range {
            rd: 2,
            lo: 0,
            hi: 1,
        });
        // addend constant 2, kept live across the loop body
        func.emit(Opcode::LoadImm { rd: 3, value: 2 });

        let begin_pc = func.emit(Opcode::SetBuilderBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 2,
            loop_end: 0,
        });
        // body: c0 = c1 = binding + 2; tuple = <<c0, c1>>. (A non-div/mod scalar
        // element op is used deliberately so the Err this test pins is the
        // *tuple-body* fail-closed rejection, not the `%`/`\div` native decline.)
        func.emit(Opcode::AddInt {
            rd: 6,
            r1: 5,
            r2: 3,
        });
        func.emit(Opcode::AddInt {
            rd: 7,
            r1: 5,
            r2: 3,
        });
        func.emit(Opcode::TupleNew {
            rd: 8,
            start: 6,
            count: 2,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 5,
            r_body: 8,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::CallBuiltin {
            rd: 9,
            builtin: BuiltinOp::Cardinality,
            args_start: 4,
            argc: 1,
        });
        func.emit(Opcode::LoadImm { rd: 10, value: 2 });
        func.emit(Opcode::Eq {
            rd: 11,
            r1: 9,
            r2: 10,
        });
        func.emit(Opcode::Ret { rs: 11 });

        let result = lower_invariant(
            &func,
            "set_builder_tuple_fail_closed",
            LoweringOptions::new(),
        );
        assert!(
            result.is_err(),
            "a fixed-extent tuple-of-scalars set-builder body must fail closed \
             (fall back to the interpreter) until a stable per-element backing \
             arena makes native sets-of-tuples sound; got Ok"
        );
    }

    /// Test CHOOSE quantifier lowering: CHOOSE x \in {10,20,30} : x > 15
    #[test]
    fn test_lower_choose() {
        let mut func = BytecodeFunction::new("choose_test".to_string(), 0);
        // Build domain set {10, 20, 30} in r3
        func.emit(Opcode::LoadImm { rd: 0, value: 10 });
        func.emit(Opcode::LoadImm { rd: 1, value: 20 });
        func.emit(Opcode::LoadImm { rd: 2, value: 30 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 0,
            count: 3,
        });

        let begin_pc = func.emit(Opcode::ChooseBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 3,
            loop_end: 0,
        });

        // Body: r7 = (r5 > 15)
        func.emit(Opcode::LoadImm { rd: 6, value: 15 });
        func.emit(Opcode::GtInt {
            rd: 7,
            r1: 5,
            r2: 6,
        });

        let next_pc = func.emit(Opcode::ChooseNext {
            rd: 4,
            r_binding: 5,
            r_body: 7,
            loop_begin: 0,
        });

        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);

        func.emit(Opcode::Ret { rs: 4 });

        let module = lower_invariant(&func, "choose_test", LoweringOptions::new())
            .expect("CHOOSE lowering should succeed");
        assert_eq!(module.functions.len(), 1);

        // CHOOSE has an extra exhausted block for runtime error.
        assert!(
            module.functions[0].blocks.len() >= 6,
            "expected >= 6 blocks for CHOOSE, got {}",
            module.functions[0].blocks.len()
        );

        // Should have a runtime error return path (for exhausted domain).
        let has_runtime_error = module.functions[0].blocks.iter().any(|b| {
            b.body.iter().any(|n| {
                // The exhausted block stores RuntimeError status then returns.
                matches!(n.inst, Inst::Const { value: Constant::Int(v), .. }
                        if v == i128::from(JitStatus::RuntimeError as u8))
            })
        });
        assert!(
            has_runtime_error,
            "CHOOSE should have a runtime error path for exhausted domain"
        );
    }

    /// Test nested quantifiers: \A x \in S : \E y \in T : x + y > 0
    #[test]
    fn test_lower_nested_forall_exists() {
        let mut func = BytecodeFunction::new("nested_test".to_string(), 0);

        // Build domain S = {1, 2} in r2
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });

        // Build domain T = {3, 4} in r5
        func.emit(Opcode::LoadImm { rd: 3, value: 3 });
        func.emit(Opcode::LoadImm { rd: 4, value: 4 });
        func.emit(Opcode::SetEnum {
            rd: 5,
            start: 3,
            count: 2,
        });

        // Outer: \A x \in S
        let forall_begin = func.emit(Opcode::ForallBegin {
            rd: 6,        // outer result
            r_binding: 7, // x
            r_domain: 2,  // S
            loop_end: 0,
        });

        // Inner: \E y \in T
        let exists_begin = func.emit(Opcode::ExistsBegin {
            rd: 8,        // inner result
            r_binding: 9, // y
            r_domain: 5,  // T
            loop_end: 0,
        });

        // Body: r10 = x + y, r12 = (r10 > 0)
        func.emit(Opcode::AddInt {
            rd: 10,
            r1: 7,
            r2: 9,
        });
        func.emit(Opcode::LoadImm { rd: 11, value: 0 });
        func.emit(Opcode::GtInt {
            rd: 12,
            r1: 10,
            r2: 11,
        });

        let exists_next = func.emit(Opcode::ExistsNext {
            rd: 8,
            r_binding: 9,
            r_body: 12,
            loop_begin: 0,
        });

        // ForallNext uses the exists result (r8) as its body result.
        let forall_next = func.emit(Opcode::ForallNext {
            rd: 6,
            r_binding: 7,
            r_body: 8,
            loop_begin: 0,
        });

        // Patch jump targets (before emitting Ret, matching compiler pattern)
        // exists_begin.loop_end -> instruction after exists_next (= forall_next)
        func.patch_jump(exists_begin, exists_next + 1);
        // exists_next.loop_begin -> instruction after exists_begin
        func.patch_jump(exists_next, exists_begin + 1);
        // forall_begin.loop_end -> instruction after forall_next
        func.patch_jump(forall_begin, forall_next + 1);
        // forall_next.loop_begin -> instruction after forall_begin
        func.patch_jump(forall_next, forall_begin + 1);

        func.emit(Opcode::Ret { rs: 6 });

        let module = lower_invariant(&func, "nested_test", LoweringOptions::new())
            .expect("nested ForAll+Exists lowering should succeed");
        assert_eq!(module.functions.len(), 1);

        // Nested quantifiers should produce many blocks.
        assert!(
            module.functions[0].blocks.len() >= 8,
            "expected >= 8 blocks for nested quantifiers, got {}",
            module.functions[0].blocks.len()
        );
    }

    #[test]
    fn test_reject_nested_forall_compound_layout_set_bitmask_without_universe_proof() {
        let mut func = BytecodeFunction::new("nested_forall_bitmask_membership".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadVar { rd: 1, var_idx: 1 });

        let outer_begin = func.emit(Opcode::ForallBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 0,
            loop_end: 0,
        });
        let inner_begin = func.emit(Opcode::ForallBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 1,
            loop_end: 0,
        });
        func.emit(Opcode::SetIn {
            rd: 6,
            elem: 5,
            set: 0,
        });
        let inner_next = func.emit(Opcode::ForallNext {
            rd: 4,
            r_binding: 5,
            r_body: 6,
            loop_begin: 0,
        });
        let outer_next = func.emit(Opcode::ForallNext {
            rd: 2,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        func.patch_jump(inner_begin, inner_next + 1);
        func.patch_jump(inner_next, inner_begin + 1);
        func.patch_jump(outer_begin, outer_next + 1);
        func.patch_jump(outer_next, outer_begin + 1);
        func.emit(Opcode::Ret { rs: 2 });

        let set_layout = || {
            VarLayout::Compound(CompoundLayout::Set {
                element_layout: Box::new(CompoundLayout::Int),
                element_count: Some(4),
            })
        };
        let layout = StateLayout::new(vec![set_layout(), set_layout()]);
        let result = lower_invariant(
            &func,
            "nested_forall_bitmask_membership",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        );
        assert_rejects_unproven_set_bitmask_universe(result);
    }

    /// Test ForAll with empty domain produces TRUE.
    /// Uses a SetEnum with count=0.
    #[test]
    fn test_lower_forall_empty_domain() {
        let mut func = BytecodeFunction::new("forall_empty".to_string(), 0);
        // Empty set in r0
        func.emit(Opcode::SetEnum {
            rd: 0,
            start: 1,
            count: 0,
        });

        let begin_pc = func.emit(Opcode::ForallBegin {
            rd: 1,
            r_binding: 2,
            r_domain: 0,
            loop_end: 0,
        });

        // Trivial body (never executed).
        func.emit(Opcode::LoadBool {
            rd: 3,
            value: false,
        });

        let next_pc = func.emit(Opcode::ForallNext {
            rd: 1,
            r_binding: 2,
            r_body: 3,
            loop_begin: 0,
        });

        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);

        func.emit(Opcode::Ret { rs: 1 });

        let module = lower_invariant(&func, "forall_empty", LoweringOptions::new())
            .expect("ForAll with empty domain should lower successfully");
        assert_eq!(module.functions.len(), 1);
    }

