        func.emit(Opcode::FuncExcept {
            rd: 9,
            func: 3,
            path: 7,
            val: 8,
        });
        func.emit(Opcode::Ret { rs: 9 });

        let module = lower_invariant(&func, "func_except_test", LoweringOptions::new())
            .expect("FuncExcept lowering should succeed");
