    #[test]
    fn test_compact_sequence_apply_scalar_result_tracks_register_slot() {
        let mut func =
            BytecodeFunction::new("compact_sequence_apply_scalar_result_slot".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: 1 });
        func.emit(Opcode::FuncApply {
            rd: 2,
            func: 0,
            arg: 1,
        });
        func.emit(Opcode::Ret { rs: 2 });

        let pool = ConstantPool::new();
        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Sequence {
            capacity_proven: false,
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(2),
        })]);
        let mut ctx = Ctx::new(
            &func,
            "compact_sequence_apply_scalar_result_slot",
            LoweringMode::Invariant,
            Some(&pool),
            Some(&layout),
            None,
        )
        .expect("test context should initialize");
        let mut block = ctx
            .block_index_for_pc(0)
            .expect("entry block should exist for test function");

        for (pc, opcode) in func.instructions.iter().enumerate().take(3) {
            block = ctx
                .lower_opcode(pc, opcode, block, &func.instructions)
                .unwrap_or_else(|err| panic!("lowering pc {pc} opcode {opcode:?} failed: {err}"))
                .unwrap_or(block);
        }

        let result_slot =
            ctx.compact_state_slots.get(&2).copied().expect(
                "scalar compact sequence apply should retain compact scalar slot provenance",
            );
        assert_eq!(
            result_slot.source_ptr,
            ctx.reg_ptr(2).expect("result register should have an alloca"),
            "scalar compact apply results must be backed by the result register slot, not a stale source or aux-block pointer"
        );
        assert_eq!(result_slot.offset, 0);
        assert!(
            result_slot.is_raw_compact_slot(),
            "result register alloca is a stable raw one-slot compact source"
        );
        assert!(
            !has_const_alloca_count(&ctx.module, ctx.func_idx, 1),
            "scalar compact sequence apply should not allocate a one-slot aggregate just to carry provenance"
        );
        let lowered_func = &ctx.module.functions[ctx.func_idx];
        let entry_block = ctx
            .block_index_for_pc(0)
            .expect("entry block should still be mapped");
        for (block_idx, block) in lowered_func.blocks.iter().enumerate() {
            if block_idx != entry_block {
                assert!(
                    block.params.is_empty(),
                    "compact sequence FuncApply aux block {block_idx} should reload scalar values locally instead of threading block args"
                );
            }
        }
    }

    #[test]
    fn test_lower_func_def_unknown_setbitmask_state_domain_rejects() {
        let mut func = BytecodeFunction::new("funcdef_known_state_domain".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        let begin_pc = func.emit(Opcode::FuncDefBegin {
            rd: 1,
            r_binding: 2,
            r_domain: 0,
            loop_end: 0,
        });
        func.emit(Opcode::Move { rd: 3, rs: 2 });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 2,
            r_body: 3,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::LoadBool { rd: 4, value: true });
        func.emit(Opcode::Ret { rs: 4 });

        let pool = ConstantPool::new();
        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Set {
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(4),
        })]);

        let err = lower_next_state(
            &func,
            "funcdef_known_state_domain",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect_err("unknown-universe compact SetBitmask FuncDef domains must fail closed");

        // The Unknown-universe `CompoundLayout::Set` var is now read into a
        // `TlaHandle` by the native-on-general-Value handle LoadVar path
        // (#4318). A `FuncDefBegin` over that handle domain is not handle-aware,
        // so the soundness wall in `load_reg_as_ptr` fails it closed — the
        // action routes to the interpreter. The rejection contract this test
        // encodes (unknown-universe set FuncDef domains MUST fail closed) still
        // holds; only the rejection site/message changed (handle guard rather
        // than the raw-compact SetBitmask path, because the var is no longer
        // materialized as a raw bitmask before FuncDefBegin sees it).
        let msg = format!("{err}");
        assert!(
            (msg.contains("FuncDefBegin: raw compact source r0")
                && msg.contains("unknown-universe SetBitmask payload"))
                || (msg.contains("holds a TlaHandle") && msg.contains("failing closed")),
            "unexpected FuncDefBegin unknown-universe-set rejection: {err}"
        );
    }

