    #[test]
    fn test_callee_symbols_are_namespaced_by_entry_module() {
        fn build_sum_chunk() -> (BytecodeChunk, u16) {
            let mut chunk = BytecodeChunk::new();

            let mut sum = BytecodeFunction::new("Sum".to_string(), 2);
            sum.emit(Opcode::AddInt {
                rd: 2,
                r1: 0,
                r2: 1,
            });
            sum.emit(Opcode::Ret { rs: 2 });
            let sum_idx = chunk.add_function(sum);

            let mut entry = BytecodeFunction::new("Inv".to_string(), 0);
            entry.emit(Opcode::LoadImm { rd: 0, value: 1 });
            entry.emit(Opcode::LoadImm { rd: 1, value: 2 });
            entry.emit(Opcode::Call {
                rd: 2,
                op_idx: sum_idx,
                args_start: 0,
                argc: 2,
            });
            entry.emit(Opcode::Ret { rs: 2 });
            let entry_idx = chunk.add_function(entry);

            (chunk, entry_idx)
        }

        let (chunk_a, entry_a) = build_sum_chunk();
        let module_a = lower_module_invariant(&chunk_a, entry_a, "InvA", LoweringOptions::new())
            .expect("first Sum helper module should lower");
        let (chunk_b, entry_b) = build_sum_chunk();
        let module_b = lower_module_invariant(&chunk_b, entry_b, "InvB", LoweringOptions::new())
            .expect("second Sum helper module should lower");

        assert_eq!(
            module_a.functions[1].name,
            "__trust_ir_callee_m4x496e7641_o0_n3x53756d"
        );
        assert_eq!(
            module_b.functions[1].name,
            "__trust_ir_callee_m4x496e7642_o0_n3x53756d"
        );
        assert_ne!(
            module_a.functions[1].name, module_b.functions[1].name,
            "same raw helper name must not produce the same JIT symbol"
        );
        assert_eq!(
            direct_call_callees(&module_a, 0),
            vec![module_a.functions[1].id],
            "first entry should call its namespaced Sum helper"
        );
        assert_eq!(
            direct_call_callees(&module_b, 0),
            vec![module_b.functions[1].id],
            "second entry should call its namespaced Sum helper"
        );
    }

    #[test]
    fn test_callee_symbols_escape_delimiter_collisions() {
        fn lowered_helper_name(module_name: &str, raw_name: &str) -> String {
            let mut chunk = BytecodeChunk::new();

            let mut helper = BytecodeFunction::new(raw_name.to_string(), 0);
            helper.emit(Opcode::LoadImm { rd: 0, value: 1 });
            helper.emit(Opcode::Ret { rs: 0 });
            chunk.add_function(helper);

            let mut entry = BytecodeFunction::new("Entry".to_string(), 0);
            entry.emit(Opcode::Call {
                rd: 0,
                op_idx: 0,
                args_start: 0,
                argc: 0,
            });
            entry.emit(Opcode::Ret { rs: 0 });
            let entry_idx = chunk.add_function(entry);

            lower_module_invariant(&chunk, entry_idx, module_name, LoweringOptions::new())
                .expect("module with delimiter-like names should lower")
                .functions[1]
                .name
                .clone()
        }

        let left = lowered_helper_name("A__callee_0__B", "C");
        let right = lowered_helper_name("A", "B__callee_0__C");

        assert_ne!(
            left, right,
            "distinct (module, op_idx, raw callee) tuples must not collide"
        );
        assert!(
            left.chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_'),
            "encoded helper symbol should stay symbol-safe: {left}"
        );
        assert!(
            right
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_'),
            "encoded helper symbol should stay symbol-safe: {right}"
        );
    }

    /// Test transitive calls: entry -> g -> f.
    #[test]
    fn test_lower_call_transitive() {
        use tla_tir::bytecode::BytecodeChunk;

        let mut chunk = BytecodeChunk::new();

        // func 0: f(x) = x * x
        let mut f = BytecodeFunction::new("f".to_string(), 1);
        f.emit(Opcode::MulInt {
            rd: 1,
            r1: 0,
            r2: 0,
        });
        f.emit(Opcode::Ret { rs: 1 });
        chunk.add_function(f);

        // func 1: g(x) = f(x) + 1
        let mut g = BytecodeFunction::new("g".to_string(), 1);
        // Call f(r0) -> r1
        g.emit(Opcode::Call {
            rd: 1,
            op_idx: 0, // call f
            args_start: 0,
            argc: 1,
        });
        g.emit(Opcode::LoadImm { rd: 2, value: 1 });
        g.emit(Opcode::AddInt {
            rd: 3,
            r1: 1,
            r2: 2,
        });
        g.emit(Opcode::Ret { rs: 3 });
        chunk.add_function(g);

        // func 2: entry() = g(5)
        let mut entry = BytecodeFunction::new("entry".to_string(), 0);
        entry.emit(Opcode::LoadImm { rd: 0, value: 5 });
        entry.emit(Opcode::Call {
            rd: 1,
            op_idx: 1, // call g
            args_start: 0,
            argc: 1,
        });
        entry.emit(Opcode::Ret { rs: 1 });
        chunk.add_function(entry);

        let module = lower_module_invariant(&chunk, 2, "transitive_test", LoweringOptions::new())
            .expect("transitive Call lowering should succeed");

        // Should have 3 functions: entry + g + f.
        assert_eq!(
            module.functions.len(),
            3,
            "expected 3 functions for transitive call chain, got {}",
            module.functions.len()
        );

        // Verify all 3 functions are present.
        let names: Vec<&str> = module.functions.iter().map(|f| f.name.as_str()).collect();
        assert!(
            names.contains(&"transitive_test"),
            "missing entry: {names:?}"
        );
        assert!(
            names.contains(&"__trust_ir_callee_m15x7472616e7369746976655f74657374_o1_n1x67"),
            "missing g: {names:?}"
        );
        assert!(
            names.contains(&"__trust_ir_callee_m15x7472616e7369746976655f74657374_o0_n1x66"),
            "missing f: {names:?}"
        );
    }

    #[test]
    fn test_call_external_self_recursion_requires_compiler_provenance() {
        let mut chunk = BytecodeChunk::new();
        let name_idx = chunk.constants.add_value(Value::String("Rec".into()));
        let mut recursive = BytecodeFunction::new("Rec".to_string(), 1);
        recursive.emit(Opcode::CallExternal {
            rd: 1,
            name_idx,
            args_start: 0,
            argc: 1,
            self_recursive: false,
        });
        recursive.emit(Opcode::Ret { rs: 1 });
        let op_idx = chunk.add_function(recursive);

        assert!(!bytecode_function_is_self_recursive(
            &chunk,
            chunk.get_function(op_idx)
        ));
        assert!(chunk_self_recursive_ops(&chunk).is_empty());
        assert_eq!(
            resolve_call_external_chunk_target(&chunk, name_idx, 1, false, Some(op_idx)),
            None
        );

        let Opcode::CallExternal { self_recursive, .. } =
            &mut chunk.functions[usize::from(op_idx)].instructions[0]
        else {
            unreachable!()
        };
        *self_recursive = true;

        assert!(bytecode_function_is_self_recursive(
            &chunk,
            chunk.get_function(op_idx)
        ));
        assert_eq!(chunk_self_recursive_ops(&chunk), HashSet::from([op_idx]));
        assert_eq!(
            resolve_call_external_chunk_target(&chunk, name_idx, 1, true, Some(op_idx)),
            Some(op_idx)
        );
        assert_eq!(
            resolve_call_external_chunk_target(&chunk, name_idx, 0, true, Some(op_idx)),
            None,
            "authenticated provenance does not bypass the arity defense"
        );
    }

    #[test]
    fn test_call_external_self_recursion_resolves_duplicate_names_relatively() {
        let mut chunk = BytecodeChunk::new();
        let name_idx = chunk.constants.add_value(Value::String("Rec".into()));
        let make_recursive = || {
            let mut recursive = BytecodeFunction::new("Rec".to_string(), 0);
            recursive.emit(Opcode::CallExternal {
                rd: 0,
                name_idx,
                args_start: 0,
                argc: 0,
                self_recursive: true,
            });
            recursive.emit(Opcode::Ret { rs: 0 });
            recursive
        };
        let first = chunk.add_function(make_recursive());
        let second = chunk.add_function(make_recursive());

        assert_eq!(
            chunk_self_recursive_ops(&chunk),
            HashSet::from([first, second])
        );
        assert_eq!(
            resolve_call_external_chunk_target(&chunk, name_idx, 0, true, Some(first)),
            Some(first)
        );
        assert_eq!(
            resolve_call_external_chunk_target(&chunk, name_idx, 0, true, Some(second)),
            Some(second)
        );
    }

    // =====================================================================
    // WP-20: tagged extern-return ABI
    // =====================================================================

    fn wp20_union_universe() -> Vec<SetBitmaskElement> {
        vec![
            SetBitmaskElement::Int(1),
            SetBitmaskElement::Int(2),
            SetBitmaskElement::Int(3),
            SetBitmaskElement::ModelValue(tla_core::intern_name("NIL")),
        ]
    }

    fn wp20_union_shape(proof: &str) -> AggregateShape {
        tagged_scalar_union_shape_from_carrier(&wp20_union_universe(), tla_core::intern_name(proof))
            .expect("nonempty universe")
    }

    /// A carrier's `proof_source` cites WHICH layout proof established its
    /// universe; it is not part of the value domain or the index encoding. Two
    /// carriers over the SAME universe therefore describe identical values and
    /// must merge — btree's `ChildNodeFor` returns `lastOf[n]` on one arm and
    /// `childOf[n, k]` on the other, both `Nodes \cup {NIL}` but cited from
    /// different proofs.
    #[test]
    fn test_wp20_union_merge_ignores_proof_citation() {
        let left = wp20_union_shape("LastOfTypeOK");
        let right = wp20_union_shape("ChildOfTypeOK");
        let merged = merge_compatible_shapes(Some(&left), Some(&right))
            .expect("same universe, different citation must merge");
        let AggregateShape::TaggedScalarUnion {
            universe,
            proof_source,
            ..
        } = &merged
        else {
            panic!("expected a tagged scalar union, got {merged:?}");
        };
        assert_eq!(universe, &wp20_union_universe());
        // Commutative and associative: the surviving citation is the smaller
        // NameId whichever order the merge sees them in.
        let expected = tla_core::intern_name("LastOfTypeOK")
            .0
            .min(tla_core::intern_name("ChildOfTypeOK").0);
        assert_eq!(proof_source.0, expected);
        assert_eq!(
            merge_compatible_shapes(Some(&right), Some(&left)),
            Some(merged)
        );
    }

    /// The citation-insensitive merge must not leak into a DIFFERENT universe:
    /// two carriers whose members differ stay unmergeable (fail closed).
    #[test]
    fn test_wp20_union_merge_still_rejects_a_different_universe() {
        let left = wp20_union_shape("TypeOK");
        let mut other_universe = wp20_union_universe();
        other_universe.push(SetBitmaskElement::Int(4));
        let right =
            tagged_scalar_union_shape_from_carrier(&other_universe, tla_core::intern_name("TypeOK"))
                .expect("nonempty universe");
        assert_eq!(merge_compatible_shapes(Some(&left), Some(&right)), None);
    }

    /// A self-recursive callee's parameter takes the union INDEX convention as
    /// soon as ANY callsite supplies a universe; the raw-scalar callsites encode
    /// into it (with the encode's fail-closed membership guard). Widening is
    /// admitted only over 1-slot raw scalars — never a compound.
    #[test]
    fn test_wp20_self_recursive_param_widens_raw_scalar_to_declared_union() {
        let union = wp20_union_shape("TypeOK");
        let int = AggregateShape::Scalar(ScalarShape::Int);
        assert_eq!(
            crate::lower::merge_self_recursive_callee_arg_shape(Some(&int), Some(&union)),
            Some(union.clone()),
            "root's raw Scalar(Int) callsite must adopt the declared universe"
        );
        assert_eq!(
            crate::lower::merge_self_recursive_callee_arg_shape(Some(&union), Some(&int)),
            Some(union.clone()),
            "widening must be symmetric"
        );
        let compound = AggregateShape::Sequence {
            extent: SequenceExtent::Capacity(2),
            element: Some(Box::new(AggregateShape::Scalar(ScalarShape::Int))),
        };
        assert_eq!(
            crate::lower::merge_self_recursive_callee_arg_shape(Some(&compound), Some(&union)),
            None,
            "a compound argument cannot be encoded into a union slot — fail closed"
        );
        // An untracked callsite argument is not something the callsite encode
        // could guard, so the parameter keeps no declared universe.
        assert_eq!(
            crate::lower::merge_self_recursive_callee_arg_shape(None, Some(&union)),
            None
        );
    }

    /// Builds `Rec(n) == IF guard[n] THEN n ELSE Rec(child[n])` plus an action
    /// `v_union' = Rec(v_root)`, mirroring btree's
    /// `focus' = FindLeafNode(root, key)`. `child`'s range is the same union as
    /// the destination var, so the recursion's own callsite is what supplies
    /// the declared parameter universe.
    fn wp20_recursive_union_chunk(union_valued_child: bool) -> (BytecodeChunk, BytecodeFunction) {
        let mut chunk = BytecodeChunk::new();
        let name_idx = chunk.constants.add_value(Value::String("Rec".into()));

        let mut rec = BytecodeFunction::new("Rec".to_string(), 1);
        rec.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0: guard
        rec.emit(Opcode::FuncApply {
            rd: 3,
            func: 2,
            arg: 0,
        }); // pc1: guard[n]
        rec.emit(Opcode::JumpFalse { rs: 3, offset: 3 }); // pc2 -> pc5
        rec.emit(Opcode::Move { rd: 4, rs: 0 }); // pc3: base case, returns n
        rec.emit(Opcode::Jump { offset: 6 }); // pc4 -> pc10
        rec.emit(Opcode::LoadVar { rd: 5, var_idx: 2 }); // pc5: child
        rec.emit(Opcode::FuncApply {
            rd: 6,
            func: 5,
            arg: 0,
        }); // pc6: child[n]
        rec.emit(Opcode::Move { rd: 7, rs: 6 }); // pc7
        rec.emit(Opcode::CallExternal {
            rd: 8,
            name_idx,
            args_start: 7,
            argc: 1,
            self_recursive: true,
        }); // pc8: Rec(child[n])
        rec.emit(Opcode::Move { rd: 4, rs: 8 }); // pc9
        rec.emit(Opcode::Move { rd: 0, rs: 4 }); // pc10: MERGE of both arms
        rec.emit(Opcode::Ret { rs: 0 }); // pc11
        let rec_idx = chunk.add_function(rec);

        let mut entry = BytecodeFunction::new("StoreRec".to_string(), 0);
        entry.emit(Opcode::LoadBool { rd: 9, value: true }); // pc0
        entry.emit(Opcode::LoadVar { rd: 1, var_idx: 3 }); // pc1: root (raw Int)
        entry.emit(Opcode::Move { rd: 2, rs: 1 }); // pc2
        entry.emit(Opcode::Call {
            rd: 3,
            op_idx: rec_idx,
            args_start: 2,
            argc: 1,
        }); // pc3
        entry.emit(Opcode::StoreVar { var_idx: 0, rs: 3 }); // pc4: union' = Rec(root)
        entry.emit(Opcode::Move { rd: 0, rs: 9 }); // pc5
        entry.emit(Opcode::Ret { rs: 0 }); // pc6

        let _ = union_valued_child;
        (chunk, entry)
    }

    fn wp20_layout(union_valued_child: bool) -> StateLayout {
        let union = CompoundLayout::TaggedScalarUnion {
            universe: wp20_union_universe(),
            proof_source: tla_core::intern_name("UnionTypeOK"),
        };
        StateLayout::new(vec![
            // v0: destination union var (btree's `focus`), cited by a DIFFERENT
            // proof than the child function's range on purpose.
            VarLayout::Compound(CompoundLayout::TaggedScalarUnion {
                universe: wp20_union_universe(),
                proof_source: tla_core::intern_name("FocusTypeOK"),
            }),
            // v1: guard function (btree's `isLeaf`). Its DOMAIN is what the
            // post-apply refinement narrows the recursion parameter to, so it is
            // the second lever this fixture varies:
            //   * declared-universe case — domain `1..3`, exactly the union's
            //     int arm;
            //   * no-universe case — domain `1..9`, DELIBERATELY wider than the
            //     union's `1..3` arm, so nothing anywhere in the recursion
            //     bounds the result inside the destination universe.
            //
            // WP-32: this second lever is load-bearing now. The union store
            // accepts a `ScalarIntDomain` source whose declared integer domain
            // is PROVEN inside the arm, so leaving this domain at `1..3` while
            // only dropping the child's union range would no longer decline —
            // the guard-apply refinement alone would prove `1..3 ⊆ [1,3]`, and
            // the store would (correctly) compile. The negative case has to
            // remove EVERY declaration that bounds the result, not just one.
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(CompoundLayout::Bool),
                pair_count: Some(if union_valued_child { 3 } else { 9 }),
                domain_lo: Some(1),
            }),
            // v2: recursion-step function (btree's `childOf`). Its range is
            // either the union (the declared-universe case) or a plain Int (no
            // universe anywhere — must stay declined).
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(if union_valued_child {
                    union
                } else {
                    CompoundLayout::Int
                }),
                pair_count: Some(3),
                domain_lo: Some(1),
            }),
            // v3: raw scalar seed (btree's `root`).
            VarLayout::ScalarInt,
        ])
    }

    /// The headline: a RECURSIVE operator's result is stored into a
    /// tagged-scalar-union state var. The recursion never inlines (it stays a
    /// separate trust-ir callee reached by a `Call`), and the parameter's
    /// declared universe — supplied by the recursion's own step function —
    /// makes the returned value a member of a known finite scalar domain, so
    /// the union store is an index passthrough instead of the `shape=None`
    /// decline.
    #[test]
    fn test_wp20_self_recursive_extern_return_stores_into_union_var() {
        let (chunk, entry) = wp20_recursive_union_chunk(true);
        let layout = wp20_layout(true);
        let module = lower_entry_next_state_with_chunk(
            &entry,
            &chunk,
            "StoreRec",
            LoweringOptions::new()
                .with_constants(&chunk.constants)
                .with_layout(&layout),
        )
        .expect("a self-recursive result with a declared union universe must store into the slot");

        // Recursion is a real call, never an inline: the callee is its own
        // trust-ir function and the entry calls it.
        assert!(
            module.functions.len() >= 2,
            "the recursive callee must be lowered as its own function, not inlined: {:?}",
            module
                .functions
                .iter()
                .map(|f| f.name.as_str())
                .collect::<Vec<_>>()
        );
        let callee = module
            .functions
            .iter()
            .find(|f| f.name.starts_with("__trust_ir_callee_"))
            .expect("the Rec callee function must exist");
        let self_calls = callee
            .blocks
            .iter()
            .flat_map(|block| block.body.iter())
            .filter(|node| matches!(&node.inst, Inst::Call { callee: c, .. } if *c == callee.id))
            .count();
        assert!(
            self_calls >= 1,
            "the recursive step must remain a direct SELF-call in the callee"
        );
    }

    /// Fail closed: with no universe anywhere in the recursion (the step
    /// function's range is a plain Int) AND no domain that bounds the result
    /// inside the destination union (the guard function's domain is `1..9`,
    /// wider than the union's `1..3` int arm), nothing declares the result's
    /// value domain, so the union store keeps today's decline rather than
    /// guessing an index for an out-of-universe raw value.
    ///
    /// WP-32 widened what counts as a declaration — a `ScalarIntDomain` proven
    /// inside the arm now encodes — so this fixture removes BOTH declarations;
    /// see `wp20_layout`.
    #[test]
    fn test_wp20_self_recursive_extern_return_without_universe_stays_declined() {
        let (chunk, entry) = wp20_recursive_union_chunk(false);
        let layout = wp20_layout(false);
        let err = lower_entry_next_state_with_chunk(
            &entry,
            &chunk,
            "StoreRec",
            LoweringOptions::new()
                .with_constants(&chunk.constants)
                .with_layout(&layout),
        )
        .expect_err("no provable result universe must stay declined");
        let message = format!("{err}");
        assert!(
            message.contains("tagged-scalar-union slot") || message.contains("shape None"),
            "unexpected decline reason: {message}"
        );
    }

    /// WP-32: the SAME recursion with NO union anywhere in the step function's
    /// RANGE still stores into the union var — because the guard apply's DOMAIN
    /// bounds the result. `Rec` returns its parameter, and the parameter was
    /// domain-checked by `guard[n]` against `DOMAIN guard = 1..3` (WP-20's
    /// post-apply refinement), which is exactly the destination union's int arm.
    /// The register therefore carries a proven Int-sorted value in `1..3`, and
    /// `(v - 1) + 0` is that member's universe index.
    ///
    /// This is the strictly-weaker-premise sibling of
    /// `test_wp20_self_recursive_extern_return_stores_into_union_var`: no
    /// declared union universe is needed anywhere, only a declared integer
    /// DOMAIN that the arm contains.
    #[test]
    fn wp32_self_recursive_int_domain_result_stores_into_union_var() {
        let (chunk, entry) = wp20_recursive_union_chunk(false);
        // Same shape as `wp20_layout(false)` except the guard's domain is
        // `1..3` — inside the union's `1..3` int arm — and the step function's
        // range stays a plain Int.
        let layout = StateLayout::new(vec![
            VarLayout::Compound(CompoundLayout::TaggedScalarUnion {
                universe: wp20_union_universe(),
                proof_source: tla_core::intern_name("FocusTypeOK"),
            }),
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(CompoundLayout::Bool),
                pair_count: Some(3),
                domain_lo: Some(1),
            }),
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(CompoundLayout::Int),
                pair_count: Some(3),
                domain_lo: Some(1),
            }),
            VarLayout::ScalarInt,
        ]);

        let module = lower_entry_next_state_with_chunk(
            &entry,
            &chunk,
            "StoreRec",
            LoweringOptions::new()
                .with_constants(&chunk.constants)
                .with_layout(&layout),
        )
        .expect("a domain-refined Int result inside the union's int arm must store into the slot");

        // The encode is the guarded int-arm shift, not a raw store: the store
        // path must still emit the fail-closed `lo <= v <= hi` compare pair and
        // the `(v - lo)` index shift, and keep a typed runtime-error edge.
        let entry_fn = 0;
        assert!(
            inst_count(&module, entry_fn, |inst| matches!(
                inst,
                Inst::ICmp {
                    op: ICmpOp::Sge,
                    ..
                }
            )) >= 1,
            "expected a lo<=v range-guard ICmp on the union store"
        );
        assert!(
            inst_count(&module, entry_fn, |inst| matches!(
                inst,
                Inst::ICmp {
                    op: ICmpOp::Sle,
                    ..
                }
            )) >= 1,
            "expected a v<=hi range-guard ICmp on the union store"
        );
        assert!(
            has_runtime_error_status_path(&module, entry_fn),
            "an out-of-arm value must return a typed runtime error, never a wrong index"
        );
    }

    /// The out-of-universe runtime path, pinned at IR level: the callsite
    /// encode of the raw `root` seed into the declared universe emits the
    /// fail-closed range guard, and the guard's failure edge stores the typed
    /// `TypeMismatch` status — a recoverable per-state interpreter fallback,
    /// never a wrong universe index.
    #[test]
    fn test_wp20_self_recursive_callsite_encode_guards_out_of_universe_values() {
        let (chunk, entry) = wp20_recursive_union_chunk(true);
        let layout = wp20_layout(true);
        let module = lower_entry_next_state_with_chunk(
            &entry,
            &chunk,
            "StoreRec",
            LoweringOptions::new()
                .with_constants(&chunk.constants)
                .with_layout(&layout),
        )
        .expect("must lower");
        // Structural scan of the ENTRY function: the raw `root` seed is
        // encoded into the declared universe's int arm `[1, 3]`, so the encode
        // must have emitted BOTH bound checks, and the guard's failure edge
        // must raise `TypeMismatch`.
        let entry_ir = &module.functions[0];
        let mut consts: HashMap<u32, i128> = HashMap::new();
        let mut lower_bound_checked = false;
        let mut upper_bound_checked = false;
        let mut raised_type_mismatch = false;
        let type_mismatch = i128::from(JitRuntimeErrorKind::TypeMismatch as u8);
        for block in &entry_ir.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Const {
                        value: Constant::Int(v),
                        ..
                    } => {
                        if let Some(r) = node.results.first() {
                            consts.insert(r.index(), *v);
                        }
                    }
                    Inst::ICmp { op, rhs, .. } => match (op, consts.get(&rhs.index())) {
                        (ICmpOp::Sge, Some(1)) => lower_bound_checked = true,
                        (ICmpOp::Sle, Some(3)) => upper_bound_checked = true,
                        _ => {}
                    },
                    Inst::Store { value, .. } => {
                        if consts.get(&value.index()) == Some(&type_mismatch) {
                            raised_type_mismatch = true;
                        }
                    }
                    _ => {}
                }
            }
        }
        assert!(
            lower_bound_checked && upper_bound_checked,
            "the callsite encode must guard the raw seed against BOTH int-arm \
             bounds of the declared universe (lo=1 seen: {lower_bound_checked}, \
             hi=3 seen: {upper_bound_checked})"
        );
        assert!(
            raised_type_mismatch,
            "the guard's failure edge must raise the typed TypeMismatch runtime \
             error (a recoverable per-state interpreter fallback), never a wrong \
             universe index"
        );
    }

    /// Test that lower_module_next_state works with Call.
    #[test]
    fn test_lower_call_next_state() {
        use tla_tir::bytecode::BytecodeChunk;

        let mut chunk = BytecodeChunk::new();

        // func 0: inc(x) = x + 1
        let mut inc = BytecodeFunction::new("inc".to_string(), 1);
        inc.emit(Opcode::LoadImm { rd: 1, value: 1 });
        inc.emit(Opcode::AddInt {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        inc.emit(Opcode::Ret { rs: 2 });
        chunk.add_function(inc);

        // func 1: Next() = x' = inc(x)
        let mut next = BytecodeFunction::new("Next".to_string(), 0);
        next.emit(Opcode::LoadVar { rd: 0, var_idx: 0 }); // x
        next.emit(Opcode::Call {
            rd: 1,
            op_idx: 0, // call inc
            args_start: 0,
            argc: 1,
        });
        next.emit(Opcode::StoreVar { var_idx: 0, rs: 1 }); // x' = inc(x)
        next.emit(Opcode::LoadBool { rd: 2, value: true });
        next.emit(Opcode::Ret { rs: 2 });
        chunk.add_function(next);

        let module =
            lower_module_next_state(&chunk, 1, "next_state_call_test", LoweringOptions::new())
                .expect("next-state Call lowering should succeed");

        assert_eq!(module.functions.len(), 2);

        // Callee in next-state mode should have 4 context params
        // (Ptr, Ptr, Ptr, I32) + hidden return buffer + 1 user arg.
        let callee_ft_idx = module.functions[1].ty;
        let callee_ft = &module.func_types[callee_ft_idx.as_usize()];
        assert_eq!(
            callee_ft.params.len(),
            6,
            "next-state callee should have 6 params (4 context + return buffer + 1 user), got {}",
            callee_ft.params.len()
        );
        assert_eq!(callee_ft.params[4], Ty::Ptr);
    }

    #[test]
    fn test_called_dense_function_stores_into_sequence_state() {
        let mut chunk = BytecodeChunk::new();

        let mut helper = BytecodeFunction::new("DenseFunction".to_string(), 0);
        helper.emit(Opcode::LoadImm { rd: 0, value: 1 });
        helper.emit(Opcode::LoadImm { rd: 1, value: 2 });
        helper.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });
        let begin_pc = helper.emit(Opcode::FuncDefBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 0,
        });
        helper.emit(Opcode::Move { rd: 5, rs: 4 });
        let next_pc = helper.emit(Opcode::LoopNext {
            r_binding: 4,
            r_body: 5,
            loop_begin: 0,
        });
        helper.patch_jump(begin_pc, next_pc + 1);
        helper.patch_jump(next_pc, begin_pc + 1);
        helper.emit(Opcode::Ret { rs: 3 });
        let helper_idx = chunk.add_function(helper);

        let mut entry = BytecodeFunction::new("StoreCalledDenseFunction".to_string(), 0);
        entry.emit(Opcode::Call {
            rd: 0,
            op_idx: helper_idx,
            args_start: 0,
            argc: 0,
        });
        entry.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });
        entry.emit(Opcode::LoadBool { rd: 1, value: true });
        entry.emit(Opcode::Ret { rs: 1 });
        let entry_idx = chunk.add_function(entry);

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Sequence {
            capacity_proven: false,
            element_layout: Box::new(CompoundLayout::Int),
            element_count: Some(2),
        })]);

        let module = lower_module_next_state(
            &chunk,
            entry_idx,
            "called_dense_function_sequence_store",
            LoweringOptions::new().with_layout(&layout),
        )
        .expect("called dense Function with domain_lo Some(1) should store into Sequence layout");

        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "caller should keep dense function-to-sequence materialization fixed"
        );
        assert!(
            !has_nonconst_alloca_count(&module, 1),
            "callee should keep dense function return materialization fixed"
        );
        assert_no_ptr_payload_store_to_state_out(&module, 0);
        assert_call_uses_caller_owned_return_buffer(&module, 0, 4, 2);
    }

    #[test]
    fn test_called_compact_function_domain_rejects_return_buffer_pointer_fallback() {
        let mut chunk = BytecodeChunk::new();

        let mut helper = BytecodeFunction::new("DenseFunction".to_string(), 0);
        helper.emit(Opcode::LoadImm { rd: 0, value: 1 });
        helper.emit(Opcode::LoadImm { rd: 1, value: 2 });
        helper.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });
        let begin_pc = helper.emit(Opcode::FuncDefBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 0,
        });
        helper.emit(Opcode::Move { rd: 5, rs: 4 });
        let next_pc = helper.emit(Opcode::LoopNext {
            r_binding: 4,
            r_body: 5,
            loop_begin: 0,
        });
        helper.patch_jump(begin_pc, next_pc + 1);
        helper.patch_jump(next_pc, begin_pc + 1);
        helper.emit(Opcode::Ret { rs: 3 });
        let helper_idx = chunk.add_function(helper);

        let mut entry = BytecodeFunction::new("DomainOfCalledDenseFunction".to_string(), 0);
        entry.emit(Opcode::Call {
            rd: 0,
            op_idx: helper_idx,
            args_start: 0,
            argc: 0,
        });
        entry.emit(Opcode::Domain { rd: 1, rs: 0 });
        entry.emit(Opcode::LoadBool { rd: 2, value: true });
        entry.emit(Opcode::Ret { rs: 2 });
        let entry_idx = chunk.add_function(entry);

        let err = lower_module_invariant(
            &chunk,
            entry_idx,
            "called_compact_function_domain_rejects",
            LoweringOptions::new(),
        )
        .expect_err("DOMAIN over a compact helper return buffer must fail closed");
        let message = format!("{err}");
        assert!(
            message.contains("Domain")
                && message.contains("compact")
                && (message.contains("aggregate-pointer")
                    || message.contains("aggregate pointer")
                    || message.contains("return buffer")
                    || message.contains("reinterpret")),
            "unexpected compact helper-return Domain rejection: {message}"
        );
    }

    /// Helper callees share the entrypoint out_ptr for runtime error /
    /// fallback signaling. Their non-Ok path must still return an i64, and
    /// callers must branch on shared status before consuming the result.
    #[test]
    fn test_lower_call_propagates_callee_status_and_keeps_callee_returns_typed() {
        use tla_tir::bytecode::BytecodeChunk;

        let mut chunk = BytecodeChunk::new();

        // func 0: overflow_if_max(x) = x + 1
        let mut helper = BytecodeFunction::new("overflow_if_max".to_string(), 1);
        helper.emit(Opcode::LoadImm { rd: 1, value: 1 });
        helper.emit(Opcode::AddInt {
            rd: 2,
            r1: 0,
            r2: 1,
        });
        helper.emit(Opcode::Ret { rs: 2 });
        chunk.add_function(helper);

        // func 1: entry() = overflow_if_max(i64::MAX)
        let mut entry = BytecodeFunction::new("entry".to_string(), 0);
        entry.emit(Opcode::LoadImm {
            rd: 0,
            value: i64::MAX,
        });
        entry.emit(Opcode::Call {
            rd: 1,
            op_idx: 0,
            args_start: 0,
            argc: 1,
        });
        entry.emit(Opcode::Ret { rs: 1 });
        chunk.add_function(entry);

        let module = lower_module_invariant(&chunk, 1, "call_status_test", LoweringOptions::new())
            .expect("call lowering with overflowing callee should succeed");

        let entry_fn = &module.functions[0];
        let helper_fn = &module.functions[1];

        let helper_has_void_return = helper_fn.blocks.iter().any(|block| {
            block
                .body
                .iter()
                .any(|node| matches!(&node.inst, Inst::Return { values } if values.is_empty()))
        });
        assert!(
            !helper_has_void_return,
            "callee runtime-error paths must still return i64"
        );

        let call_block = entry_fn
            .blocks
            .iter()
            .find(|block| {
                block
                    .body
                    .iter()
                    .any(|node| matches!(&node.inst, Inst::Call { .. }))
            })
            .expect("entry should contain a Call block");

        let has_status_load = call_block
            .body
            .iter()
            .any(|node| matches!(&node.inst, Inst::Load { ty: Ty::I8, .. }));
        assert!(
            has_status_load,
            "caller must reload shared status after helper call"
        );

        let has_ok_cmp = call_block.body.iter().any(|node| {
            matches!(
                &node.inst,
                Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: Ty::I8,
                    ..
                }
            )
        });
        assert!(
            has_ok_cmp,
            "caller must compare shared status against JitStatus::Ok"
        );

        assert!(
            matches!(
                call_block.body.last().map(|node| &node.inst),
                Some(Inst::CondBr { .. })
            ),
            "caller must branch on shared status after helper call"
        );
    }

    #[test]
    fn test_lower_call_stores_result_before_status_branch() {
        use tla_tir::bytecode::BytecodeChunk;

        let mut chunk = BytecodeChunk::new();

        let mut helper = BytecodeFunction::new("helper".to_string(), 0);
        helper.emit(Opcode::LoadImm { rd: 0, value: 7 });
        helper.emit(Opcode::Ret { rs: 0 });
        let helper_idx = chunk.add_function(helper);

        let mut entry = BytecodeFunction::new("entry".to_string(), 0);
        entry.emit(Opcode::Call {
            rd: 0,
            op_idx: helper_idx,
            args_start: 0,
            argc: 0,
        });
        entry.emit(Opcode::Ret { rs: 0 });
        let entry_idx = chunk.add_function(entry);

        let module = lower_module_invariant(
            &chunk,
            entry_idx,
            "call_result_store_test",
            LoweringOptions::new(),
        )
        .expect("helper call should lower");
        let entry_fn = &module.functions[0];
        let (call_block_idx, call_result) = entry_fn
            .blocks
            .iter()
            .enumerate()
            .find_map(|(block_idx, block)| {
                block.body.iter().find_map(|node| {
                    if matches!(&node.inst, Inst::Call { .. }) {
                        node.results
                            .first()
                            .copied()
                            .map(|result| (block_idx, result))
                    } else {
                        None
                    }
                })
            })
            .expect("entry should contain a Call with a result");
        let call_block = &entry_fn.blocks[call_block_idx];
        let cond_pos = call_block
            .body
            .iter()
            .position(|node| matches!(&node.inst, Inst::CondBr { .. }))
            .expect("call block should branch on shared status");

        assert!(
            call_block.body[..cond_pos].iter().any(|node| {
                matches!(&node.inst, Inst::Store { value, .. } if *value == call_result)
            }),
            "call result must be stored in the call block before the status branch"
        );

        let continue_id = match &call_block.body[cond_pos].inst {
            Inst::CondBr { then_target, .. } => *then_target,
            _ => unreachable!(),
        };
        let continue_block = entry_fn
            .blocks
            .iter()
            .find(|block| block.id == continue_id)
            .expect("call_ok block should exist");
        assert!(
            !continue_block.body.iter().any(|node| {
                matches!(&node.inst, Inst::Store { value, .. } if *value == call_result)
            }),
            "call_ok must not consume the call result through cross-block SSA"
        );
    }

