    // =================================================================
    // FuncSet tests
    // =================================================================

    /// Test FuncSet: build [S -> T] from two sets.
    #[test]
    fn test_lower_func_set() {
        let mut func = BytecodeFunction::new("func_set_test".to_string(), 0);
        // Domain = {1, 2}
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });
        // Range = {10, 20, 30}
        func.emit(Opcode::LoadImm { rd: 3, value: 10 });
        func.emit(Opcode::LoadImm { rd: 4, value: 20 });
        func.emit(Opcode::LoadImm { rd: 5, value: 30 });
        func.emit(Opcode::SetEnum {
            rd: 6,
            start: 3,
            count: 3,
        });
        // FuncSet [domain -> range]
        func.emit(Opcode::FuncSet {
            rd: 7,
            domain: 2,
            range: 6,
        });
        func.emit(Opcode::Ret { rs: 7 });

        let module = lower_invariant(&func, "func_set_test", LoweringOptions::new()).unwrap();
        assert_eq!(module.functions.len(), 1);

        let entry = &module.functions[0].blocks[0];
        assert!(
            entry.body.len() > 8,
            "entry block should have allocas + 2 sets + funcset, got {} instructions",
            entry.body.len()
        );

        let alloca_count: usize = module.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(&n.inst, Inst::Alloca { .. }))
            .count();
        // mem2reg-fed lowering (commit 7d14728c) now runs
        // `trust_ir::mem2reg::promote_allocas_module` in `finish()`, which
        // promotes the never-escaping, single-block, store-before-load
        // register-file allocas (one i64 per bytecode register) to true SSA.
        // This is a value-identical rewrite, so only the aggregate allocas
        // (domain set, range set, funcset) survive. The previous expectation
        // of >= 11 (8 register allocas + 3 aggregates) counted the register
        // allocas that are now promoted away; the remaining aggregate allocas
        // are what the FuncSet build actually materializes.
        assert!(
            alloca_count >= 3,
            "expected >= 3 aggregate allocas (register allocas promoted by mem2reg), got {alloca_count}"
        );
    }

