    #[test]
    fn test_lazy_powerset_of_compact_setbitmask_iteration_rejects() {
        let mut set_filter = BytecodeFunction::new("compact_subset_set_filter".to_string(), 0);
        set_filter.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        set_filter.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = set_filter.emit(Opcode::SetFilterBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        set_filter.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = set_filter.emit(Opcode::LoopNext {
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        set_filter.patch_jump(begin_pc, next_pc + 1);
        set_filter.patch_jump(next_pc, begin_pc + 1);
        set_filter.emit(Opcode::Ret { rs: 2 });

        let mut forall = BytecodeFunction::new("compact_subset_forall".to_string(), 0);
        forall.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        forall.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = forall.emit(Opcode::ForallBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        forall.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = forall.emit(Opcode::ForallNext {
            rd: 2,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        forall.patch_jump(begin_pc, next_pc + 1);
        forall.patch_jump(next_pc, begin_pc + 1);
        forall.emit(Opcode::Ret { rs: 2 });

        let mut exists = BytecodeFunction::new("compact_subset_exists".to_string(), 0);
        exists.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        exists.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = exists.emit(Opcode::ExistsBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        exists.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = exists.emit(Opcode::ExistsNext {
            rd: 2,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        exists.patch_jump(begin_pc, next_pc + 1);
        exists.patch_jump(next_pc, begin_pc + 1);
        exists.emit(Opcode::Ret { rs: 2 });

        let mut choose = BytecodeFunction::new("compact_subset_choose".to_string(), 0);
        choose.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        choose.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = choose.emit(Opcode::ChooseBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        choose.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = choose.emit(Opcode::ChooseNext {
            rd: 2,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        choose.patch_jump(begin_pc, next_pc + 1);
        choose.patch_jump(next_pc, begin_pc + 1);
        choose.emit(Opcode::Ret { rs: 2 });

        let mut func_def = BytecodeFunction::new("compact_subset_func_def".to_string(), 0);
        func_def.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func_def.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = func_def.emit(Opcode::FuncDefBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        func_def.emit(Opcode::Move { rd: 4, rs: 3 });
        let next_pc = func_def.emit(Opcode::LoopNext {
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        func_def.patch_jump(begin_pc, next_pc + 1);
        func_def.patch_jump(next_pc, begin_pc + 1);
        func_def.emit(Opcode::Ret { rs: 2 });

        let cases = vec![
            ("SetFilterBegin", set_filter),
            ("ForallBegin", forall),
            ("ExistsBegin", exists),
            ("ChooseBegin", choose),
            ("FuncDefBegin", func_def),
        ];
        let layout = StateLayout::new(vec![VarLayout::Compound(int_range_set_bitmask_layout(
            1, 3,
        ))]);

        for (opcode, func) in cases {
            let err = lower_invariant(
                &func,
                &format!("compact_subset_iter_{opcode}"),
                LoweringOptions::new()
                    .with_constants(&ConstantPool::new())
                    .with_layout(&layout),
            )
            .expect_err("compact SetBitmask SUBSET iteration must reject");
            let message = format!("{err}");
            assert!(
                message.contains(opcode)
                    && message.contains("lazy SUBSET over compact SetBitmask")
                    && message.contains("submask iteration"),
                "error should reject {opcode} compact SUBSET iteration before pointer iteration: {message}"
            );
        }
    }

    #[test]
    fn test_exists_over_const_int_powerset_uses_submask_iteration() {
        let mut func = BytecodeFunction::new("exists_const_int_subset_member".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 1 });
        func.emit(Opcode::LoadImm { rd: 2, value: 2 });
        func.emit(Opcode::SetEnum {
            rd: 3,
            start: 0,
            count: 3,
        });
        func.emit(Opcode::Powerset { rd: 4, rs: 3 });
        let begin_pc = func.emit(Opcode::ExistsBegin {
            rd: 5,
            r_binding: 6,
            r_domain: 4,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm { rd: 7, value: 2 });
        func.emit(Opcode::SetIn {
            rd: 8,
            elem: 7,
            set: 6,
        });
        let next_pc = func.emit(Opcode::ExistsNext {
            rd: 5,
            r_binding: 6,
            r_body: 8,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: 5 });

        let module = lower_invariant(
            &func,
            "exists_const_int_subset_member",
            LoweringOptions::new(),
        )
        .expect("EXISTS over SUBSET of exact integer set should lower by submask");

        assert_has_condbr_tag(&module, 0, "bounded_loop(4)", |tag| {
            is_bounded_loop(tag) && bounded_loop_n(tag) == Some(4)
        });
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "constant integer SUBSET iteration should not allocate dynamic aggregate storage"
        );
    }

    /// FORALL over `SUBSET T` for an exact integer set `T = {1, 2}` lowers via
    /// submask iteration (2^2 = 4 candidate subsets), mirroring the EXISTS
    /// case. This is the structural shape of the `SubsetQuantifierViolated`
    /// soundness fixture's `\A S \in SUBSET T : x \notin S` invariant.
    #[test]
    fn test_forall_over_const_int_powerset_uses_submask_iteration() {
        let mut func = BytecodeFunction::new("forall_const_int_subset_member".to_string(), 0);
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 2 });
        func.emit(Opcode::SetEnum {
            rd: 2,
            start: 0,
            count: 2,
        });
        func.emit(Opcode::Powerset { rd: 3, rs: 2 });
        let begin_pc = func.emit(Opcode::ForallBegin {
            rd: 4,
            r_binding: 5,
            r_domain: 3,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm { rd: 6, value: 1 });
        // body: 1 \notin S  (modelled as membership; the SetIn result feeds
        // ForallNext, which is order-independent so the verdict matches the
        // interpreter regardless of submask vs cardinality-first order).
        func.emit(Opcode::SetIn {
            rd: 7,
            elem: 6,
            set: 5,
        });
        let next_pc = func.emit(Opcode::ForallNext {
            rd: 4,
            r_binding: 5,
            r_body: 7,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: 4 });

        let module = lower_invariant(
            &func,
            "forall_const_int_subset_member",
            LoweringOptions::new(),
        )
        .expect("FORALL over SUBSET of exact integer set should lower by submask");

        assert_has_condbr_tag(&module, 0, "bounded_loop(4)", |tag| {
            is_bounded_loop(tag) && bounded_loop_n(tag) == Some(4)
        });
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "constant integer FORALL SUBSET iteration should not allocate dynamic aggregate storage"
        );
    }

    /// FAIL-CLOSED bound: an EXISTS over `SUBSET T` where the exact integer set
    /// `T` has 64 elements must DECLINE native submask lowering. The candidate
    /// subset `S` is materialized as an i64 bitmask (one bit per element of
    /// `T`), so a 64-element universe overflows the compact representation; the
    /// `2^64` submask counter is likewise unrepresentable. Lowering must return
    /// an `UnsupportedOpcode` error so the model checker falls back to the
    /// interpreter rather than emitting unbounded/incorrect code.
    #[test]
    fn test_exists_over_oversized_int_powerset_declines_submask() {
        let mut func = BytecodeFunction::new("exists_oversized_int_subset".to_string(), 0);
        // Build an exact integer set of 64 distinct values {0, 1, ..., 63}.
        const N: u8 = 64;
        for i in 0..N {
            func.emit(Opcode::LoadImm {
                rd: i,
                value: i64::from(i),
            });
        }
        func.emit(Opcode::SetEnum {
            rd: N,
            start: 0,
            count: N,
        });
        func.emit(Opcode::Powerset { rd: N + 1, rs: N });
        let begin_pc = func.emit(Opcode::ExistsBegin {
            rd: N + 2,
            r_binding: N + 3,
            r_domain: N + 1,
            loop_end: 0,
        });
        func.emit(Opcode::LoadImm {
            rd: N + 4,
            value: 1,
        });
        func.emit(Opcode::SetIn {
            rd: N + 5,
            elem: N + 4,
            set: N + 3,
        });
        let next_pc = func.emit(Opcode::ExistsNext {
            rd: N + 2,
            r_binding: N + 3,
            r_body: N + 5,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);
        func.emit(Opcode::Ret { rs: N + 2 });

        let err = lower_invariant(&func, "exists_oversized_int_subset", LoweringOptions::new())
            .expect_err(
                "EXISTS over SUBSET of a 64-element exact integer set must decline native submask \
             lowering (fail-closed), not emit a 2^64 loop",
            );
        let message = format!("{err}");
        assert!(
            message.contains("SUBSET")
                && (message.contains("too large")
                    || message.contains("cannot be represented as a compact submask universe")),
            "decline should explain the oversized SUBSET universe, got: {message}"
        );
    }

