    #[test]
    fn test_choose_subset_result_shape_reaches_helper_arg_prepass() {
        use std::sync::Arc;

        let mut chunk = BytecodeChunk::new();
        let mut pool = ConstantPool::new();
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));
        let resources = pool.add_value(Value::set([
            Value::ModelValue(Rp::from("p1")),
            Value::ModelValue(Rp::from("p2")),
        ]));

        let mut helper = BytecodeFunction::new("ContainsP2".to_string(), 1);
        helper.emit(Opcode::LoadConst { rd: 1, idx: p2 });
        helper.emit(Opcode::SetIn {
            rd: 2,
            elem: 1,
            set: 0,
        });
        helper.emit(Opcode::Ret { rs: 2 });
        let helper_idx = chunk.add_function(helper);

        let mut entry = BytecodeFunction::new("choose_subset_helper_arg".to_string(), 0);
        entry.emit(Opcode::LoadConst {
            rd: 0,
            idx: resources,
        });
        entry.emit(Opcode::Powerset { rd: 1, rs: 0 });
        let begin_pc = entry.emit(Opcode::ChooseBegin {
            rd: 2,
            r_binding: 3,
            r_domain: 1,
            loop_end: 0,
        });
        entry.emit(Opcode::LoadBool { rd: 4, value: true });
        let next_pc = entry.emit(Opcode::ChooseNext {
            rd: 2,
            r_binding: 3,
            r_body: 4,
            loop_begin: 0,
        });
        entry.patch_jump(begin_pc, next_pc + 1);
        entry.patch_jump(next_pc, begin_pc + 1);
        entry.emit(Opcode::Call {
            rd: 5,
            op_idx: helper_idx,
            args_start: 2,
            argc: 1,
        });
        entry.emit(Opcode::Ret { rs: 5 });
        let entry_idx = chunk.add_function(entry);
        chunk.constants = pool;

        let module = lower_module_invariant(
            &chunk,
            entry_idx,
            "choose_subset_helper_arg",
            LoweringOptions::new(),
        )
        .expect("CHOOSE over exact SUBSET should seed helper argument shape");

        assert!(
            (0..module.functions.len()).all(|idx| !has_nonconst_alloca_count(&module, idx)),
            "helper called with CHOOSE SUBSET result should keep compact setbitmask lowering"
        );
    }

