    #[test]
    fn test_lower_func_set_membership_with_powerset_range() {
        let mut func = BytecodeFunction::new("func_set_subset_proc_typeok".to_string(), 0);
        // Proc == 1..3
        func.emit(Opcode::LoadImm { rd: 0, value: 1 });
        func.emit(Opcode::LoadImm { rd: 1, value: 3 });
        func.emit(Opcode::Range {
            rd: 2,
            lo: 0,
            hi: 1,
        });

        // ack == [p \in Proc |-> {p}]
        let begin_pc = func.emit(Opcode::FuncDefBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 0,
        });
        func.emit(Opcode::SetEnum {
            rd: 5,
            start: 4,
            count: 1,
        });
        let next_pc = func.emit(Opcode::LoopNext {
            r_binding: 4,
            r_body: 5,
            loop_begin: 0,
        });
        func.patch_jump(begin_pc, next_pc + 1);
        func.patch_jump(next_pc, begin_pc + 1);

        func.emit(Opcode::Powerset { rd: 6, rs: 2 });
        func.emit(Opcode::FuncSet {
            rd: 7,
            domain: 2,
            range: 6,
        });
        func.emit(Opcode::SetIn {
            rd: 8,
            elem: 3,
            set: 7,
        });
        func.emit(Opcode::Ret { rs: 8 });

        let module = lower_invariant(&func, "func_set_subset_proc_typeok", LoweringOptions::new())
            .expect("ack \\in [Proc -> SUBSET Proc] should lower conservatively");

        assert!(
            module.functions[0].blocks.len() >= 16,
            "function-set SUBSET range membership should lower to nested checks, got {} blocks",
            module.functions[0].blocks.len()
        );
        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "fixed [Proc -> SUBSET Proc] membership should not emit non-const-count Alloca"
        );
    }

    #[test]
    fn test_lower_func_set_powerset_range_preserves_exact_setunion_universe() {
        use std::sync::Arc;

        let mut pool = ConstantPool::new();
        let p1 = pool.add_value(Value::ModelValue(Rp::from("p1")));
        let p2 = pool.add_value(Value::ModelValue(Rp::from("p2")));

        let mut func = BytecodeFunction::new("func_set_subset_exact_setunion_range".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadImm { rd: 1, value: 1 });
        func.emit(Opcode::LoadImm { rd: 2, value: 2 });
        func.emit(Opcode::Range {
            rd: 3,
            lo: 1,
            hi: 2,
        });
        func.emit(Opcode::LoadConst { rd: 4, idx: p1 });
        func.emit(Opcode::SetEnum {
            rd: 5,
            start: 4,
            count: 1,
        });
        func.emit(Opcode::LoadConst { rd: 6, idx: p2 });
        func.emit(Opcode::SetEnum {
            rd: 7,
            start: 6,
            count: 1,
        });
        func.emit(Opcode::SetUnion {
            rd: 8,
            r1: 5,
            r2: 7,
        });
        func.emit(Opcode::Powerset { rd: 9, rs: 8 });
        func.emit(Opcode::FuncSet {
            rd: 10,
            domain: 3,
            range: 9,
        });
        func.emit(Opcode::SetIn {
            rd: 11,
            elem: 0,
            set: 10,
        });
        func.emit(Opcode::Ret { rs: 11 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::Int),
            value_layout: Box::new(model_value_set_bitmask_layout(&["p1", "p2"])),
            pair_count: Some(2),
            domain_lo: Some(1),
        })]);

        let module = lower_invariant(
            &func,
            "func_set_subset_exact_setunion_range",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("function-set SUBSET range should retain the exact SetUnion universe");

        assert!(
            !has_nonconst_alloca_count(&module, 0),
            "exact SetUnion provenance should let the function-set range lower with fixed allocations"
        );
    }

