    #[test]
    fn pocset_empty_init_store_lowers_via_handle_abi() {
        // PocSet `Init == s = {}`: SetEnum count=0 builds `{}`. In the handle
        // path that should route through `tla_set_enum_0` and commit via
        // `tla_handle_store_to_scratch`. (count=0 takes the empty-set arm; we
        // still expect the StoreVar of a handle to round-trip — but here the
        // empty-set literal is NOT produced by a handle-mode SetEnum since our
        // gate requires count>=1, so this asserts the StoreVar fail-closed path
        // does not silently mis-handle a non-handle empty set.)
        let mut func = BytecodeFunction::new("pocset_init".to_string(), 0);
        func.emit(Opcode::SetEnum {
            rd: 0,
            start: 0,
            count: 0,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 0 });
        func.emit(Opcode::LoadBool { rd: 1, value: true });
        func.emit(Opcode::Ret { rs: 1 });
        let layout = unknown_universe_set_layout();
        let pool = ConstantPool::new();
        // The empty-set literal `{}` over count=0 does not get handle provenance
        // (gate requires count>=1), so StoreVar sees a non-handle source. This
        // must NOT take the handle StoreVar branch (which would require handle
        // provenance); it either lowers via the existing materialized path or
        // fails closed — never silently writes a raw pointer as a compound
        // scratch offset.
        let _ = lower_next_state(
            &func,
            "pocset_init",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        );
        // No panic / no UB is the assertion here (lowering is total).
    }

    /// Repro for the scalar-primed IF-THEN-ELSE soundness bug: the exact
    /// post-action-transform bytecode for `x' = (IF x = 0 THEN 5 ELSE x)`
    /// (var 1 = x). The THEN value `5` must survive lowering; if it is dropped,
    /// the compiled next-state collapses `x'` to the unchanged value and the
    /// state space vacuously collapses.
    #[test]
    fn repro_scalar_primed_if_keeps_then_value() {
        // Post-transform bytecode as dumped by TY_TRUST_CG_DUMP_ACTION_BYTECODE
        // for the IfScalar repro (only the x' = IF... conjunct; the f' = f
        // conjunct is irrelevant to whether `5` survives).
        let mut func = BytecodeFunction::new("Step".to_string(), 0);
        func.emit(Opcode::LoadBool { rd: 7, value: true }); // action-enabled flag
        func.emit(Opcode::LoadVar { rd: 1, var_idx: 1 }); // load x
        func.emit(Opcode::LoadImm { rd: 2, value: 0 });
        func.emit(Opcode::Eq {
            rd: 3,
            r1: 1,
            r2: 2,
        }); // r3 = (x == 0)
        func.emit(Opcode::JumpFalse { rs: 3, offset: 4 }); // pc4 -> else (pc8)
        func.emit(Opcode::LoadImm { rd: 5, value: 5 }); // THEN: 5
        func.emit(Opcode::Move { rd: 4, rs: 5 });
        func.emit(Opcode::Jump { offset: 3 }); // pc7 -> merge (pc10)
        func.emit(Opcode::LoadVar { rd: 6, var_idx: 1 }); // ELSE: x
        func.emit(Opcode::Move { rd: 4, rs: 6 });
        func.emit(Opcode::StoreVar { var_idx: 1, rs: 4 }); // x' := r4 (IF result)
        func.emit(Opcode::Move { rd: 0, rs: 7 });
        func.emit(Opcode::Ret { rs: 0 });

        // Realistic layout matching the IfScalar repro: var0 = f (a function
        // [1..2 -> Nat]), var1 = x (a scalar Int).
        let layout = StateLayout::new(vec![
            VarLayout::Compound(CompoundLayout::Function {
                key_layout: Box::new(CompoundLayout::Int),
                value_layout: Box::new(CompoundLayout::Int),
                pair_count: Some(2),
                domain_lo: Some(1),
            }),
            VarLayout::ScalarInt,
        ]);

        let module = lower_next_state(
            &func,
            "Step",
            LoweringOptions::new()
                .with_constants(&ConstantPool::new())
                .with_layout(&layout),
        )
        .expect("lowering should succeed");
        let ir = format!("{module:#?}");
        assert!(
            ir.contains("Int(\n                                    5,"),
            "lowered next-state IR must contain the THEN constant 5; \
             the scalar-primed IF dropped it.\nIR:\n{ir}"
        );
        assert!(
            !merge_store_recopies_same_state_slot(&module),
            "scalar-primed IF merge must store the IF result, not re-copy the \
             OLD state slot of x; the ELSE-arm LoadVar provenance leaked across \
             the merge.\nIR:\n{ir}"
        );
    }

    /// Returns true when, within any single block, the function writes
    /// `state_out[K]` from a value loaded out of `state_in[K]` for the SAME flat
    /// slot index `K` — the unsound "v' = v unchanged copy" the scalar-primed IF
    /// bug produced (the merged IF result was discarded and the OLD slot was
    /// re-copied verbatim). The flat slot index is whatever GEP index the store
    /// targets; it need not equal the logical var index.
    fn merge_store_recopies_same_state_slot(module: &trust_ir::Module) -> bool {
        use trust_ir::inst::Inst;
        let func = match module.functions.first() {
            Some(f) => f,
            None => return false,
        };
        // ABI is (out, state_in, state_out, len): params 1 and 2.
        let entry = func.blocks.first().expect("entry block");
        let state_in = match entry.params.get(1).map(|(v, _)| *v) {
            Some(v) => v.index(),
            None => return false,
        };
        let state_out = match entry.params.get(2).map(|(v, _)| *v) {
            Some(v) => v.index(),
            None => return false,
        };

        for block in &func.blocks {
            // ValueId -> const integer (covers i32/i64 GEP indices).
            let mut consts: std::collections::HashMap<u32, i128> = std::collections::HashMap::new();
            // ValueId(GEP result) -> (base param, const slot index).
            let mut gep_addr: std::collections::HashMap<u32, (u32, i128)> =
                std::collections::HashMap::new();
            // ValueId(Load result) -> (base param, const slot index) of its source.
            let mut load_slot: std::collections::HashMap<u32, (u32, i128)> =
                std::collections::HashMap::new();

            for node in &block.body {
                match &node.inst {
                    Inst::Const {
                        value: trust_ir::Constant::Int(v),
                        ..
                    } => {
                        if let Some(r) = node.results.first() {
                            consts.insert(r.index(), *v);
                        }
                    }
                    Inst::GEP { base, indices, .. } => {
                        if let (Some(r), Some(idx)) = (node.results.first(), indices.first()) {
                            if let Some(c) = consts.get(&(idx.index())) {
                                gep_addr.insert(r.index(), (base.index(), *c));
                            }
                        }
                    }
                    Inst::Load { ptr, .. } => {
                        if let Some(r) = node.results.first() {
                            if let Some(addr) = gep_addr.get(&(ptr.index())) {
                                load_slot.insert(r.index(), *addr);
                            }
                        }
                    }
                    Inst::Store { ptr, value, .. } => {
                        let Some(&(out_base, out_slot)) = gep_addr.get(&(ptr.index())) else {
                            continue;
                        };
                        if out_base != state_out {
                            continue;
                        }
                        if let Some(&(in_base, in_slot)) = load_slot.get(&(value.index())) {
                            if in_base == state_in && in_slot == out_slot {
                                return true;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        false
    }

    // =====================================================================
    // RecordSetBitmask native ABI — golden tests (steps 2/5 + 3/5).
    //
    // The interpreter encoder (`record_set_bitmask_value_to_slots` /
    // `record_set_bitmask_slot_valid_mask` in tla-check) is the GROUND TRUTH the
    // native lowering must match bit-for-bit. tla-check depends on tla-ir (not
    // the reverse), so we cannot call the interpreter encoder here; instead we
    // reimplement its exact algorithm as an in-test REFERENCE and pin the
    // production helpers against it. The reference functions below are
    // line-faithful copies of flat_state.rs:{249, 2086}.
    // =====================================================================

    /// REFERENCE copy of the interpreter's `record_set_bitmask_slot_count`
    /// (flat_state.rs `universe_len.div_ceil(64)`).
    fn ref_slot_count(universe_len: usize) -> usize {
        universe_len.div_ceil(64)
    }

    /// REFERENCE copy of the interpreter's `record_set_bitmask_slot_valid_mask`
    /// (flat_state.rs:249) — full word for non-final slots, partial for final.
    fn ref_valid_mask(universe_len: usize, slot_index: usize) -> Option<u64> {
        let slot_count = ref_slot_count(universe_len);
        if slot_index >= slot_count {
            return None;
        }
        let bits_in_slot = if slot_index + 1 == slot_count {
            let rem = universe_len % 64;
            if rem == 0 {
                64
            } else {
                rem
            }
        } else {
            64
        };
        Some(if bits_in_slot == 64 {
            u64::MAX
        } else {
            (1u64 << bits_in_slot) - 1
        })
    }

    /// REFERENCE copy of the interpreter's bit assignment in
    /// `record_set_bitmask_value_to_slots` (flat_state.rs:2086): the bit for a
    /// record is its position in the canonical universe found via `==`.
    fn ref_bit_index(universe: &[Value], value: &Value) -> Option<usize> {
        universe.iter().position(|candidate| candidate == value)
    }

    /// REFERENCE copy of the full interpreter encoder
    /// `record_set_bitmask_value_to_slots`: pack universe-record bits into
    /// `ceil(|U|/64)` i64 slots. Returns `None` if any element is outside the
    /// universe (fail-closed, exactly like the interpreter).
    fn ref_encode_set(universe: &[Value], set: &[Value]) -> Option<Vec<i64>> {
        let slot_count = ref_slot_count(universe.len());
        let mut masks = vec![0u64; slot_count];
        for elem in set {
            let index = ref_bit_index(universe, elem)?;
            masks[index / 64] |= 1u64 << (index % 64);
        }
        Some(masks.into_iter().map(|m| m as i64).collect())
    }

    /// Map a `Value::Record` to the production `RecordBitKey` (canonical
    /// field-name-string order via `RecordBitKey::from_fields`). Mirrors how a
    /// later step will derive keys from the interpreter universe records.
    fn record_to_bit_key(value: &Value) -> RecordBitKey {
        let Value::Record(record) = value else {
            panic!("record_to_bit_key requires a Value::Record, got {value:?}");
        };
        let fields = record
            .into_iter()
            .map(|(name, field_value)| {
                let element = match field_value {
                    Value::SmallInt(n) => SetBitmaskElement::Int(*n),
                    Value::Bool(b) => SetBitmaskElement::Bool(*b),
                    Value::String(s) => SetBitmaskElement::String(tla_core::intern_name(s)),
                    Value::ModelValue(m) => SetBitmaskElement::ModelValue(tla_core::intern_name(m)),
                    other => panic!("unsupported record field value in test: {other:?}"),
                };
                (name, element)
            })
            .collect();
        RecordBitKey::from_fields(fields)
    }

    fn universe_keys(universe: &[Value]) -> Vec<RecordBitKey> {
        universe.iter().map(record_to_bit_key).collect()
    }

    /// PRODUCTION-side encode mirroring the IR membership/union/diff/enum bit
    /// math: set bit `i` for each universe key the element matches, using the
    /// production `record_bit_key_index`. Byte-equality of this vs
    /// `ref_encode_set` proves the native bit indexing matches the interpreter.
    fn prod_encode_set(
        universe_keys: &[RecordBitKey],
        set_keys: &[RecordBitKey],
    ) -> Option<Vec<i64>> {
        let universe_len = universe_keys.len();
        let slot_count = record_set_bitmask_slot_count_ir(universe_len as u32);
        let mut masks = vec![0u64; slot_count];
        for key in set_keys {
            let index = record_bit_key_index(universe_keys, key)?;
            masks[index / 64] |= 1u64 << (index % 64);
        }
        Some(masks.into_iter().map(|m| m as i64).collect())
    }

    /// Tiny deterministic SplitMix64-style PRNG (no external dep) for fuzzing.
    struct Rng(u64);
    impl Rng {
        fn next_u64(&mut self) -> u64 {
            self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = self.0;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^ (z >> 31)
        }
        fn below(&mut self, n: usize) -> usize {
            (self.next_u64() % (n as u64)) as usize
        }
    }

    /// Build a finite universe of distinct two-field records `[id |-> i, kind
    /// |-> K]` (i in 0..n, K a model value), canonicalized through `SortedSet`
    /// exactly as the interpreter's `proof.record_universe` is, so the universe
    /// order here is identical to what `record_set_bitmask_value_to_slots` sees.
    fn build_record_universe(n: usize) -> Vec<Value> {
        use tla_value::value::SortedSet;
        let kinds = ["A", "B", "C"];
        let mut builder = tla_value::SetBuilder::new();
        for i in 0..n {
            let mut rec = tla_value::RecordBuilder::new();
            // Insert in a deliberately NON-canonical field order to prove the
            // canonicalization (RecordValue::from_entries + RecordBitKey) lines
            // them up regardless of insertion order.
            rec.insert_str("kind", Value::ModelValue(Rp::from(kinds[i % 3])));
            rec.insert_str("id", Value::SmallInt(i as i64));
            builder.insert(Value::Record(rec.build()));
        }
        let set: SortedSet = builder.build();
        set.iter().cloned().collect()
    }

    #[test]
    fn test_record_set_bitmask_valid_mask_matches_interpreter_1_to_512() {
        // (c) multi-slot valid-mask == flat_state.rs:249 for all 1..=512.
        for universe_len in 1u32..=512 {
            let slot_count = record_set_bitmask_slot_count_ir(universe_len);
            assert_eq!(
                slot_count,
                ref_slot_count(universe_len as usize),
                "slot_count mismatch at universe_len={universe_len}"
            );
            for slot_index in 0..slot_count {
                assert_eq!(
                    record_set_bitmask_slot_valid_mask_ir(universe_len, slot_index),
                    ref_valid_mask(universe_len as usize, slot_index),
                    "valid-mask mismatch at universe_len={universe_len}, slot={slot_index}"
                );
            }
            // Out-of-range slot is None on both sides.
            assert_eq!(
                record_set_bitmask_slot_valid_mask_ir(universe_len, slot_count),
                None,
                "out-of-range slot must be None at universe_len={universe_len}"
            );
        }
    }

    #[test]
    fn test_record_set_bitmask_bit_index_matches_interpreter_fuzzed() {
        // (a) emitted membership bit index == record_set_bitmask_value_to_slots
        // bit index; (d) out-of-universe element fails closed (None).
        // >=1000 fuzzed records across universe sizes spanning 1..=512.
        let sizes = [
            1usize, 2, 7, 31, 63, 64, 65, 100, 127, 128, 200, 256, 257, 400, 511, 512,
        ];
        let mut rng = Rng(0xD1CE_F00D_1234_5678);
        let mut total_checks = 0usize;
        for &n in &sizes {
            let universe = build_record_universe(n);
            assert_eq!(universe.len(), n, "deduped universe size at n={n}");
            let keys = universe_keys(&universe);
            // Every in-universe record's production index matches the reference
            // (which IS the interpreter's bit assignment).
            for value in &universe {
                let key = record_to_bit_key(value);
                assert_eq!(
                    record_bit_key_index(&keys, &key),
                    ref_bit_index(&universe, value),
                    "in-universe bit index mismatch at n={n}, value={value:?}"
                );
                total_checks += 1;
            }
            // Fuzz: pick random in-universe members and out-of-universe records.
            for _ in 0..64 {
                let idx = rng.below(n);
                let value = &universe[idx];
                let key = record_to_bit_key(value);
                let prod = record_bit_key_index(&keys, &key);
                let refr = ref_bit_index(&universe, value);
                assert_eq!(prod, refr, "fuzzed in-universe index mismatch at n={n}");
                assert_eq!(prod, Some(idx), "expected bit index {idx} at n={n}");
                total_checks += 1;

                // Out-of-universe record (id beyond the universe, distinct kind):
                // both must be None (fail-closed), never a silent wrong bit.
                let mut out = tla_value::RecordBuilder::new();
                out.insert_str("id", Value::SmallInt((n + 1 + rng.below(1000)) as i64));
                out.insert_str("kind", Value::ModelValue(Rp::from("Z")));
                let out_value = Value::Record(out.build());
                let out_key = record_to_bit_key(&out_value);
                assert_eq!(
                    record_bit_key_index(&keys, &out_key),
                    None,
                    "out-of-universe record must yield None at n={n}"
                );
                assert_eq!(ref_bit_index(&universe, &out_value), None);
                total_checks += 1;
            }
        }
        assert!(
            total_checks >= 1000,
            "expected >=1000 bit-index checks, ran {total_checks}"
        );
    }

    #[test]
    fn test_record_set_bitmask_encode_union_diff_byte_equal_to_interpreter_fuzzed() {
        // (b) lowered set / union / diff / {rec}-literal masks BYTE-EQUAL to the
        // interpreter encoder for the same logical sets, across 1..=8 slots.
        let sizes = [1usize, 5, 63, 64, 65, 128, 130, 256, 300, 512];
        let mut rng = Rng(0xBADC_0FFE_E0DD_F00D);
        let mut total_sets = 0usize;
        for &n in &sizes {
            let universe = build_record_universe(n);
            let keys = universe_keys(&universe);
            let slot_count = record_set_bitmask_slot_count_ir(n as u32);
            assert!(
                (1..=8).contains(&slot_count),
                "slot_count {slot_count} for n={n}"
            );

            for _ in 0..16 {
                // Two random subsets of the universe (by index).
                let pick = |rng: &mut Rng| -> Vec<usize> {
                    let mut v = Vec::new();
                    for i in 0..n {
                        if rng.next_u64() & 1 == 1 {
                            v.push(i);
                        }
                    }
                    v
                };
                let idxs_a = pick(&mut rng);
                let idxs_b = pick(&mut rng);
                let vals_a: Vec<Value> = idxs_a.iter().map(|&i| universe[i].clone()).collect();
                let vals_b: Vec<Value> = idxs_b.iter().map(|&i| universe[i].clone()).collect();
                let keys_a: Vec<RecordBitKey> = vals_a.iter().map(record_to_bit_key).collect();
                let keys_b: Vec<RecordBitKey> = vals_b.iter().map(record_to_bit_key).collect();

                // Plain encode ({rec...} enum-fold): production == interpreter.
                let ref_a = ref_encode_set(&universe, &vals_a).unwrap();
                let prod_a = prod_encode_set(&keys, &keys_a).unwrap();
                assert_eq!(prod_a, ref_a, "encode mismatch at n={n}");
                assert_eq!(prod_a.len(), slot_count, "slot width at n={n}");

                let ref_b = ref_encode_set(&universe, &vals_b).unwrap();
                let prod_b = prod_encode_set(&keys, &keys_b).unwrap();
                assert_eq!(prod_b, ref_b, "encode mismatch (b) at n={n}");

                // UNION: per-slot OR & valid-mask (mirrors lower_set_union arm)
                // vs interpreter encode of the logical union.
                let mut union_vals = vals_a.clone();
                union_vals.extend(vals_b.iter().cloned());
                let ref_union = ref_encode_set(&universe, &union_vals).unwrap();
                let mut prod_union = Vec::with_capacity(slot_count);
                for j in 0..slot_count {
                    let valid = record_set_bitmask_slot_valid_mask_ir(n as u32, j).unwrap() as i64;
                    prod_union.push((prod_a[j] | prod_b[j]) & valid);
                }
                assert_eq!(prod_union, ref_union, "union mask mismatch at n={n}");

                // DIFF: per-slot AND-NOT & valid-mask (mirrors lower_set_diff arm:
                // left & (right XOR valid) & valid) vs interpreter encode of A\B.
                let set_b: std::collections::HashSet<usize> = idxs_b.iter().copied().collect();
                let diff_vals: Vec<Value> = idxs_a
                    .iter()
                    .filter(|i| !set_b.contains(i))
                    .map(|&i| universe[i].clone())
                    .collect();
                let ref_diff = ref_encode_set(&universe, &diff_vals).unwrap();
                let mut prod_diff = Vec::with_capacity(slot_count);
                for j in 0..slot_count {
                    let valid = record_set_bitmask_slot_valid_mask_ir(n as u32, j).unwrap() as i64;
                    let right_complement = prod_b[j] ^ valid;
                    prod_diff.push((prod_a[j] & right_complement) & valid);
                }
                assert_eq!(prod_diff, ref_diff, "diff mask mismatch at n={n}");

                total_sets += 1;
            }
        }
        assert!(
            total_sets >= 100,
            "expected >=100 set encodings, ran {total_sets}"
        );
    }

    /// Set up a register `reg` as a pointer-backed compact aggregate of
    /// `slot_count` i64 slots (an alloca), tagging it with `shape`. Used to feed
    /// RecordSetBitmask / Record operands into the set-op lowering for the
    /// no-IntToPtr structural check.
    fn seed_pointer_backed_compact_reg(
        ctx: &mut Ctx<'_>,
        block_idx: usize,
        reg: u8,
        slot_count: u32,
        shape: AggregateShape,
    ) {
        let ptr = ctx.alloc_aggregate(block_idx, slot_count);
        ctx.store_compact_aggregate_result(block_idx, reg, ptr, shape)
            .expect("seed pointer-backed compact reg");
    }

    fn record_set_bitmask_shape_for(universe: &[Value]) -> AggregateShape {
        let keys = universe_keys(universe);
        AggregateShape::RecordSetBitmask {
            universe_len: universe.len() as u32,
            slot_count: record_set_bitmask_slot_count_ir(universe.len() as u32) as u32,
            universe: keys,
        }
    }

    fn two_field_record_shape() -> AggregateShape {
        // Canonical field-name order: "id" < "kind".
        AggregateShape::Record {
            fields: vec![
                (
                    tla_core::intern_name("id"),
                    Some(Box::new(AggregateShape::Scalar(ScalarShape::Int))),
                ),
                (
                    tla_core::intern_name("kind"),
                    Some(Box::new(AggregateShape::Scalar(ScalarShape::ModelValue))),
                ),
            ],
        }
    }

    fn count_int_to_ptr(module: &trust_ir::Module, func_idx: usize) -> usize {
        let mut count = 0;
        for block in &module.functions[func_idx].blocks {
            for node in &block.body {
                if matches!(
                    node.inst,
                    Inst::Cast {
                        op: CastOp::IntToPtr,
                        ..
                    }
                ) {
                    count += 1;
                }
            }
        }
        count
    }

    #[test]
    fn test_record_set_bitmask_membership_emits_no_int_to_ptr() {
        // (e) NO IntToPtr/materialized-pointer in the emitted IR for a
        // RecordSetBitmask membership operand (the rc=139 guard).
        let n = 130usize; // 3 slots, exercises multi-slot indexing.
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        // Minimal bytecode: just a SetIn we drive manually below.
        let mut func = BytecodeFunction::new("rsb_membership".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 4; // reserve r0..r4 for the manually-driven set op
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_membership",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        // r1 = element record (pointer-backed compact 2-field record).
        seed_pointer_backed_compact_reg(&mut ctx, block, 1, 2, two_field_record_shape());
        // r2 = the RecordSetBitmask mask (pointer-backed multi-slot region).
        seed_pointer_backed_compact_reg(&mut ctx, block, 2, slot_count, set_shape);

        ctx.lower_set_in(block, 3, 1, 2)
            .expect("RecordSetBitmask membership should lower")
            .expect("membership returns a block");
        let module = ctx.finish();

        assert_eq!(
            count_int_to_ptr(&module, 0),
            0,
            "RecordSetBitmask membership must emit NO IntToPtr (rc=139 guard)"
        );
        // It must also test bits via shifts/ands, not a materialized scan.
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::LShr,
                    ..
                }
            )) >= 1,
            "membership should extract bits via LShr"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(inst, Inst::CondBr { .. })) == 0,
            "membership should stay straight-line (no scan loop)"
        );
    }

    #[test]
    fn test_record_set_bitmask_union_emits_no_int_to_ptr() {
        // (e) NO IntToPtr in the emitted IR for a RecordSetBitmask union operand.
        let n = 200usize; // 4 slots.
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        let mut func = BytecodeFunction::new("rsb_union".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 4; // reserve r0..r4 for the manually-driven set ops
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_union",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        seed_pointer_backed_compact_reg(&mut ctx, block, 1, slot_count, set_shape.clone());
        seed_pointer_backed_compact_reg(&mut ctx, block, 2, slot_count, set_shape.clone());

        ctx.lower_set_union(block, 3, 1, 2)
            .expect("RecordSetBitmask union should lower")
            .expect("union returns a block");

        // The result r3 must carry the RecordSetBitmask shape again.
        assert!(
            matches!(
                ctx.aggregate_shapes.get(&3),
                Some(AggregateShape::RecordSetBitmask { slot_count: sc, .. }) if *sc == slot_count
            ),
            "union result must be tagged RecordSetBitmask with {slot_count} slots"
        );

        // Also exercise diff on the same operands.
        ctx.lower_set_diff(block, 4, 1, 2)
            .expect("RecordSetBitmask diff should lower")
            .expect("diff returns a block");

        let module = ctx.finish();
        assert_eq!(
            count_int_to_ptr(&module, 0),
            0,
            "RecordSetBitmask union/diff must emit NO IntToPtr (rc=139 guard)"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp { op: BinOp::Or, .. }
            )) >= 1,
            "union should OR mask slots"
        );
    }

    #[test]
    fn test_record_set_bitmask_union_diff_dispatches_literal_enum_fold() {
        // Track B increment 1b — the native record-set ACTION compile. A
        // `v \cup {rec}` / `v \ {rec}` whose LHS is a pointer-backed
        // RecordSetBitmask state var and whose RHS is a `{rec}` SetEnum LITERAL
        // (NOT a pointer-backed mask) must lower: the literal operand dispatches
        // `emit_record_set_bitmask_enum_fold` over the var's universe instead of
        // fail-closing on `load_record_set_bitmask_slots`. The result is tagged
        // RecordSetBitmask again and NO IntToPtr is emitted (the rc=139 guard).
        let n = 64usize; // single slot keeps the assertions simple.
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        for op in ["union", "diff"] {
            let mut func = BytecodeFunction::new("rsb_lit".to_string(), 0);
            func.emit(Opcode::Ret { rs: 0 });
            func.max_register = 5;
            let const_pool = ConstantPool::new();
            let mut ctx = Ctx::new(
                &func,
                "rsb_lit",
                LoweringMode::Invariant,
                Some(&const_pool),
                None,
                None,
            )
            .unwrap();
            let block = ctx.block_index_for_pc(0).unwrap();

            // r1 = the record-set state var (pointer-backed RecordSetBitmask).
            seed_pointer_backed_compact_reg(&mut ctx, block, 1, slot_count, set_shape.clone());

            // r2 = a literal element record `[id |-> .., kind |-> ..]`
            // (pointer-backed compact 2-field record), tracked as the SINGLE
            // element of the `{rec}` SetEnum literal in r3. The set value in r3
            // is intentionally NOT a pointer-backed mask — the dispatch must use
            // the element record in r2 via record_set_literal_element_regs.
            seed_pointer_backed_compact_reg(&mut ctx, block, 2, 1, two_field_record_shape());
            // r3 = the materialized `{rec}` literal (a plain set pointer); its
            // shape is a finite Set, and its element registers are recorded.
            seed_pointer_backed_compact_reg(
                &mut ctx,
                block,
                3,
                2,
                AggregateShape::Set {
                    len: 1,
                    element: Some(Box::new(two_field_record_shape())),
                },
            );
            ctx.record_set_literal_element_regs.insert(3, vec![2]);

            // v \cup {rec}  /  v \ {rec}: LHS=r1 (state var), RHS=r3 (literal).
            let result = if op == "union" {
                ctx.lower_set_union(block, 4, 1, 3)
            } else {
                ctx.lower_set_diff(block, 4, 1, 3)
            };
            result
                .unwrap_or_else(|e| {
                    panic!("RecordSetBitmask {op} with a literal RHS should lower, got {e:?}")
                })
                .expect("op returns a block");

            assert!(
                matches!(
                    ctx.aggregate_shapes.get(&4),
                    Some(AggregateShape::RecordSetBitmask { slot_count: sc, .. }) if *sc == slot_count
                ),
                "{op} result must be re-tagged RecordSetBitmask"
            );

            let module = ctx.finish();
            assert_eq!(
                count_int_to_ptr(&module, 0),
                0,
                "RecordSetBitmask {op} with a literal RHS must emit NO IntToPtr (rc=139 guard)"
            );
            // The enum-fold sets the literal's bit via Shl; the binary op then
            // combines slots (Or for union, And for diff's and-not).
            assert!(
                inst_count(&module, 0, |inst| matches!(
                    inst,
                    Inst::BinOp { op: BinOp::Shl, .. }
                )) >= 1,
                "{op} literal dispatch should set the element bit via the enum-fold Shl"
            );
        }
    }

    #[test]
    fn test_record_set_bitmask_union_literal_fails_closed_without_element_tracking() {
        // Fail-closed: a non-pointer-backed RHS that is NOT a tracked record-set
        // literal (no record_set_literal_element_regs entry) must NOT silently
        // lower — the action routes to the interpreter rather than read the
        // operand as a materialized set pointer.
        let n = 64usize;
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        let mut func = BytecodeFunction::new("rsb_lit_fail".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 4;
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_lit_fail",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        seed_pointer_backed_compact_reg(&mut ctx, block, 1, slot_count, set_shape);
        // r2: a materialized finite set with NO record_set_literal_element_regs
        // entry and NOT a RecordSetBitmask — must fail closed.
        seed_pointer_backed_compact_reg(
            &mut ctx,
            block,
            2,
            2,
            AggregateShape::Set {
                len: 1,
                element: Some(Box::new(two_field_record_shape())),
            },
        );

        let result = ctx.lower_set_union(block, 3, 1, 2);
        assert!(
            result.is_err(),
            "RecordSetBitmask union with an untracked non-mask RHS must fail closed, got {result:?}"
        );
    }

    #[test]
    fn test_record_set_bitmask_enum_fold_emits_no_int_to_ptr_and_correct_shift() {
        // (b)/(e) for the `{rec}` literal enum-fold: drive the IR-emitting helper
        // directly (no auto-dispatch site exists until Step 5 threads the
        // universe) and prove it emits NO IntToPtr and uses Shl to set bits.
        let n = 130usize; // 3 slots — exercises the slot index/64 split.
        let universe = build_record_universe(n);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;
        let keys = universe_keys(&universe);

        let mut func = BytecodeFunction::new("rsb_enum".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 3;
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_enum",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        // Two literal element records (pointer-backed compact 2-field records).
        let elem_ptr_a = ctx.alloc_aggregate(block, 2);
        let elem_ptr_b = ctx.alloc_aggregate(block, 2);
        let elem_a = CompactStateSlot::pointer_backed_in_block(elem_ptr_a, 0, block);
        let elem_b = CompactStateSlot::pointer_backed_in_block(elem_ptr_b, 0, block);
        let elements = vec![
            (elem_a, two_field_record_shape()),
            (elem_b, two_field_record_shape()),
        ];

        let result_slots = ctx
            .emit_record_set_bitmask_enum_fold(
                block,
                n as u32,
                slot_count,
                &keys,
                &elements,
                "test-enum-fold",
            )
            .expect("enum-fold should emit");
        assert_eq!(result_slots.len(), slot_count as usize);
        let module = ctx.finish();

        assert_eq!(
            count_int_to_ptr(&module, 0),
            0,
            "RecordSetBitmask enum-fold must emit NO IntToPtr"
        );
        assert!(
            inst_count(&module, 0, |inst| matches!(
                inst,
                Inst::BinOp { op: BinOp::Shl, .. }
            )) >= 1,
            "enum-fold should set bits via Shl"
        );
    }

    #[test]
    fn test_record_set_bitmask_membership_shape_mismatched_element_lowers_constant_false() {
        // Heterogeneous-universe semantics: an element whose FULLY tracked
        // record shape provably lacks a universe field can never Value-equal
        // any key requiring that field — membership lowers to a constant-false
        // result (every key statically unmatchable), never a silent wrong bit
        // or pointer deref. (Partially tracked shapes still fail closed; see
        // record_shape_field_certainly_absent.)
        let n = 64usize;
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        let mut func = BytecodeFunction::new("rsb_bad_elem".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 3; // reserve r0..r3 for the manually-driven set op
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_bad_elem",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        // Element is a record MISSING the "kind" universe field (fully
        // tracked: its one field carries a shape), so absence is proven.
        let bad_elem_shape = AggregateShape::Record {
            fields: vec![(
                tla_core::intern_name("id"),
                Some(Box::new(AggregateShape::Scalar(ScalarShape::Int))),
            )],
        };
        seed_pointer_backed_compact_reg(&mut ctx, block, 1, 1, bad_elem_shape);
        seed_pointer_backed_compact_reg(&mut ctx, block, 2, slot_count, set_shape);

        let result = ctx.lower_set_in(block, 3, 1, 2);
        assert!(
            result.is_ok(),
            "membership with an element provably missing a universe field lowers to a \
             constant-false result, got {result:?}"
        );
        let module = ctx.finish();
        assert_eq!(
            count_int_to_ptr(&module, 0),
            0,
            "shape-mismatched membership must not deref the element pointer"
        );
    }

    #[test]
    fn test_record_set_bitmask_membership_partially_tracked_element_still_fails_closed() {
        // The certainly-absent proof requires EVERY element field to carry a
        // tracked shape: `compact_record_field`'s None is ambiguous between
        // "field absent" and "untracked prefix", so a partially tracked
        // element must keep failing closed.
        let n = 64usize;
        let universe = build_record_universe(n);
        let set_shape = record_set_bitmask_shape_for(&universe);
        let slot_count = record_set_bitmask_slot_count_ir(n as u32) as u32;

        let mut func = BytecodeFunction::new("rsb_partial_elem".to_string(), 0);
        func.emit(Opcode::Ret { rs: 0 });
        func.max_register = 3;
        let const_pool = ConstantPool::new();
        let mut ctx = Ctx::new(
            &func,
            "rsb_partial_elem",
            LoweringMode::Invariant,
            Some(&const_pool),
            None,
            None,
        )
        .unwrap();
        let block = ctx.block_index_for_pc(0).unwrap();

        // One field with NO tracked shape: absence of "kind" is NOT provable.
        let partial_elem_shape = AggregateShape::Record {
            fields: vec![(tla_core::intern_name("id"), None)],
        };
        seed_pointer_backed_compact_reg(&mut ctx, block, 1, 1, partial_elem_shape);
        seed_pointer_backed_compact_reg(&mut ctx, block, 2, slot_count, set_shape);

        let result = ctx.lower_set_in(block, 3, 1, 2);
        assert!(
            result.is_err(),
            "membership with a partially tracked element shape must fail closed, got {result:?}"
        );
    }

    // =================================================================
    // Route B: native record-set multi-successor NextStateLoop kernel.
    // =================================================================

    /// Serializes the env-dependent NextStateLoop tests and restores
    /// `TY_RECORD_SET_NATIVE` on drop. The variable is unset by default, so the
    /// guard keeps every other test (and the default lowering path) unaffected.
    struct RecordSetNativeEnvGuard {
        _lock: std::sync::MutexGuard<'static, ()>,
        prev: Option<std::ffi::OsString>,
    }

    /// THE single raw env-mutation site for this test module — every guard path
    /// routes through it. A raw `set_var`/`remove_var` must exist somewhere to
    /// implement the primitive; this one lock-scoped helper is that somewhere.
    /// `env_mutation` is the Trust toolchain's deny-by-default env wall;
    /// `unknown_lints` keeps the stock-rustc build green (the lint is Trust-only).
    #[allow(unknown_lints, env_mutation)]
    fn raw_env_write(key: &str, value: Option<&std::ffi::OsStr>) {
        match value {
            Some(v) => std::env::set_var(key, v),
            None => std::env::remove_var(key),
        }
    }

    impl RecordSetNativeEnvGuard {
        fn enabled() -> Self {
            Self::set(Some("1"))
        }

        fn disabled() -> Self {
            Self::set(None)
        }

        fn set(value: Option<&str>) -> Self {
            static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
            let lock = LOCK.lock().unwrap_or_else(|poison| poison.into_inner());
            let prev = std::env::var_os("TY_RECORD_SET_NATIVE");
            raw_env_write("TY_RECORD_SET_NATIVE", value.map(std::ffi::OsStr::new));
            Self { _lock: lock, prev }
        }
    }

    impl Drop for RecordSetNativeEnvGuard {
        fn drop(&mut self) {
            raw_env_write("TY_RECORD_SET_NATIVE", self.prev.as_deref());
        }
    }

    /// `[x |-> Int, msgs |-> RecordSetBitmask over {[id|->0],[id|->1]}]`, the
    /// two-var state layout the record-set NextStateLoop kernel targets. `x` is a
    /// scalar next-state var written by the body; `msgs` is the proven-closed
    /// record-set domain.
    fn record_set_native_layout(is_proven_closed: bool) -> StateLayout {
        let id = tla_core::intern_name("id");
        let universe = vec![
            vec![(id, SetBitmaskElement::Int(0))],
            vec![(id, SetBitmaskElement::Int(1))],
        ];
        StateLayout::new(vec![
            VarLayout::ScalarInt,
            VarLayout::Compound(CompoundLayout::RecordSetBitmask {
                universe,
                slot_count: 1,
                is_proven_closed,
            }),
        ])
    }

    /// `\E m \in msgs : x' = 1` — a single-`StoreVar` body over a proven-closed
    /// RecordSetBitmask state var, the canonical NextStateLoop shape.
    fn record_set_native_func() -> BytecodeFunction {
        let mut f = BytecodeFunction::new("nsl_action".to_string(), 0);
        f.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0: r2 = msgs
        f.emit(Opcode::ExistsBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 4,
        }); // pc1
        f.emit(Opcode::LoadImm { rd: 5, value: 1 }); // pc2: body
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 5 }); // pc3: x' = 1
        f.emit(Opcode::ExistsNext {
            rd: 3,
            r_binding: 4,
            r_body: 3,
            loop_begin: -2,
        }); // pc4
        f.emit(Opcode::Ret { rs: 3 }); // pc5
        f
    }

    fn assert_all_blocks_terminated(module: &trust_ir::Module, func_idx: usize) {
        for block in &module.functions[func_idx].blocks {
            assert!(
                block
                    .body
                    .last()
                    .is_some_and(trust_ir::InstrNode::is_terminator),
                "block {:?} is not terminated (mem2reg/codegen would reject fallthrough)",
                block.id
            );
        }
    }

    #[test]
    fn nsl_record_set_single_store_lowers_under_env() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        let func = record_set_native_func();
        let layout = record_set_native_layout(true);
        let pool = ConstantPool::new();

        let module = lower_next_state_loop_scaffold(&func, "nsl", Some(&pool), Some(&layout))
            .expect(
                "proven-closed record-set NextStateLoop should lower under TY_RECORD_SET_NATIVE=1",
            );

        // Every block must terminate (Br/CondBr/Return) — the structural
        // validation the module/mem2reg pipeline enforces.
        assert_all_blocks_terminated(&module, 0);

        let blocks = &module.functions[0].blocks;
        let cond_brs = blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(n.inst, Inst::CondBr { .. }))
            .count();
        let returns = blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(n.inst, Inst::Return { .. }))
            .count();
        // One bit-test CondBr per universe record (2) plus an overflow-guard
        // CondBr and a reseed-loop CondBr per set bit — so strictly more than the
        // universe size. Two returns: the success tail and the shared overflow
        // exit.
        assert!(
            cond_brs >= 2,
            "expected per-bit CondBr diamonds, got {cond_brs}"
        );
        assert!(
            returns >= 2,
            "expected success + overflow returns, got {returns}"
        );
    }

    #[test]
    fn nsl_record_set_gated_off_fails_closed() {
        let _guard = RecordSetNativeEnvGuard::disabled();
        let func = record_set_native_func();
        let layout = record_set_native_layout(true);
        let pool = ConstantPool::new();

        let result = lower_next_state_loop_scaffold(&func, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(result, Err(TrustIrError::UnsupportedOpcode(_))),
            "default (env-unset) invocation must fail closed, got {result:?}"
        );
    }

    #[test]
    fn nsl_record_set_not_proven_closed_fails_closed() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        let func = record_set_native_func();
        let layout = record_set_native_layout(false);
        let pool = ConstantPool::new();

        let result = lower_next_state_loop_scaffold(&func, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(result, Err(TrustIrError::UnsupportedOpcode(_))),
            "a non-proven-closed record-set universe must fail closed, got {result:?}"
        );
    }

    #[test]
    fn nsl_record_set_multi_pair_fails_closed() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        // Two inner existentials: the single-pair recovery must reject it.
        let mut f = BytecodeFunction::new("nsl_two".to_string(), 0);
        f.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0
        f.emit(Opcode::ExistsBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 4,
        }); // pc1
        f.emit(Opcode::LoadImm { rd: 5, value: 1 }); // pc2
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 5 }); // pc3
        f.emit(Opcode::ExistsNext {
            rd: 3,
            r_binding: 4,
            r_body: 3,
            loop_begin: -2,
        }); // pc4
        f.emit(Opcode::ExistsBegin {
            rd: 6,
            r_binding: 7,
            r_domain: 2,
            loop_end: 4,
        }); // pc5: second pair
        f.emit(Opcode::LoadImm { rd: 8, value: 1 }); // pc6
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 8 }); // pc7
        f.emit(Opcode::ExistsNext {
            rd: 6,
            r_binding: 7,
            r_body: 6,
            loop_begin: -2,
        }); // pc8
        f.emit(Opcode::Ret { rs: 3 }); // pc9

        let layout = record_set_native_layout(true);
        let pool = ConstantPool::new();
        let result = lower_next_state_loop_scaffold(&f, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(result, Err(TrustIrError::UnsupportedOpcode(_))),
            "two inner existentials must fail closed, got {result:?}"
        );
    }

    #[test]
    fn nsl_record_set_disjunctive_dropped_sibling_fails_closed() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        // `(\E m \in msgs : x'=1) \/ (x'=0)`: the `JumpTrue` short-circuit skips a
        // sibling `StoreVar` outside the exists body — the expansion would drop
        // that successor, so it must fail closed.
        let mut f = BytecodeFunction::new("nsl_disj".to_string(), 0);
        f.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0
        f.emit(Opcode::ExistsBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 4,
        }); // pc1
        f.emit(Opcode::LoadImm { rd: 5, value: 1 }); // pc2
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 5 }); // pc3
        f.emit(Opcode::ExistsNext {
            rd: 3,
            r_binding: 4,
            r_body: 3,
            loop_begin: -2,
        }); // pc4
        f.emit(Opcode::JumpTrue { rs: 3, offset: 3 }); // pc5: skip to pc8
        f.emit(Opcode::LoadImm { rd: 6, value: 0 }); // pc6
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 6 }); // pc7: dropped sibling
        f.emit(Opcode::Ret { rs: 3 }); // pc8

        let layout = record_set_native_layout(true);
        let pool = ConstantPool::new();
        let result = lower_next_state_loop_scaffold(&f, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(result, Err(TrustIrError::UnsupportedOpcode(_))),
            "disjunctive dropped-sibling shape must fail closed, got {result:?}"
        );
    }

    // -----------------------------------------------------------------
    // Per-universe-key guard constant-folding over heterogeneous record
    // universes (the PaxosCommit Phase2b shape: `m.type = "..."` guards over
    // a message universe mixing record shapes with different field sets).
    // -----------------------------------------------------------------

    /// `[x |-> Int, msgs |-> RecordSetBitmask over a HETEROGENEOUS universe]`:
    /// bit 0 = `[type |-> "a", val |-> 1]`, bit 1 = `[type |-> "b"]` (no
    /// `val`). Canonical `Value::cmp` order: "a" < "b".
    fn heterogeneous_record_set_layout() -> StateLayout {
        let type_id = tla_core::intern_name("type");
        let val_id = tla_core::intern_name("val");
        let universe = vec![
            vec![
                (
                    type_id,
                    SetBitmaskElement::String(tla_core::intern_name("a")),
                ),
                (val_id, SetBitmaskElement::Int(1)),
            ],
            vec![(
                type_id,
                SetBitmaskElement::String(tla_core::intern_name("b")),
            )],
        ];
        StateLayout::new(vec![
            VarLayout::ScalarInt,
            VarLayout::Compound(CompoundLayout::RecordSetBitmask {
                universe,
                slot_count: 1,
                is_proven_closed: true,
            }),
        ])
    }

    /// Constant pool for the heterogeneous-universe tests: field ids 0/1 =
    /// `type`/`val`, value idx 0 = the string the type guard compares against.
    fn heterogeneous_guard_pool(guard_type: &str) -> ConstantPool {
        let mut pool = ConstantPool::new();
        pool.add_field_id(tla_core::intern_name("type").0); // field_idx 0
        pool.add_field_id(tla_core::intern_name("val").0); // field_idx 1
        pool.add_value(Value::String(Rp::from(guard_type))); // idx 0
        pool
    }

    /// `\E m \in msgs : m.type = <guard_type> /\ x' = m.val` — a type-guard
    /// body whose `m.val` read only exists on universe bit 0.
    fn heterogeneous_guard_func() -> BytecodeFunction {
        let mut f = BytecodeFunction::new("nsl_guard".to_string(), 0);
        f.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0: r2 = msgs
        f.emit(Opcode::ExistsBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 10,
        }); // pc1
        f.emit(Opcode::RecordGet {
            rd: 5,
            rs: 4,
            field_idx: 0,
        }); // pc2: r5 = m.type
        f.emit(Opcode::LoadConst { rd: 6, idx: 0 }); // pc3: r6 = guard type
        f.emit(Opcode::Eq {
            rd: 7,
            r1: 5,
            r2: 6,
        }); // pc4
        f.emit(Opcode::Move { rd: 3, rs: 7 }); // pc5: stage guard into r_body
        f.emit(Opcode::JumpFalse { rs: 3, offset: 4 }); // pc6 -> pc10 (body end)
        f.emit(Opcode::RecordGet {
            rd: 8,
            rs: 4,
            field_idx: 1,
        }); // pc7: r8 = m.val (bit 0 only)
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 8 }); // pc8: x' = m.val
        f.emit(Opcode::LoadBool { rd: 3, value: true }); // pc9: trailing true
        f.emit(Opcode::ExistsNext {
            rd: 3,
            r_binding: 4,
            r_body: 3,
            loop_begin: -8,
        }); // pc10
        f.emit(Opcode::Ret { rs: 3 }); // pc11
        f
    }

    fn count_insts(module: &trust_ir::Module, pred: impl Fn(&Inst) -> bool) -> usize {
        module.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .filter(|n| pred(&n.inst))
            .count()
    }

    #[test]
    fn nsl_guard_const_fold_skips_dead_key_and_omits_true_guard() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        let func = heterogeneous_guard_func();
        let layout = heterogeneous_record_set_layout();
        let pool = heterogeneous_guard_pool("a");

        // Bit 1 (`[type |-> "b"]`) fails the `m.type = "a"` guard at compile
        // time, so its diamond — including the `m.val` RecordGet that has no
        // compact offset there — must not be emitted at all; bit 0's guard
        // folds TRUE, so no runtime guard branch remains either.
        let module = lower_next_state_loop_scaffold(&func, "nsl", Some(&pool), Some(&layout))
            .expect("dead-key guard fold should make the heterogeneous universe lowerable");
        assert_all_blocks_terminated(&module, 0);

        // Exactly ONE live key: one bit-test LShr, and exactly the three
        // structural CondBrs of a single diamond (bit test, overflow guard,
        // reseed loop) — a fourth would be a leftover runtime guard branch.
        let bit_tests = count_insts(&module, |inst| {
            matches!(
                inst,
                Inst::BinOp {
                    op: BinOp::LShr,
                    ..
                }
            )
        });
        assert_eq!(
            bit_tests, 1,
            "dead universe key must emit no bit-test diamond"
        );
        let cond_brs = count_insts(&module, |inst| matches!(inst, Inst::CondBr { .. }));
        assert_eq!(
            cond_brs, 3,
            "statically-true guard must omit its runtime CondBr (bit test + overflow + reseed only)"
        );
    }

    #[test]
    fn nsl_guard_const_fold_live_key_missing_field_still_fails_closed() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        let func = heterogeneous_guard_func();
        let layout = heterogeneous_record_set_layout();
        // Guard selects bit 1 (`[type |-> "b"]`), whose LIVE body then reads
        // the missing `m.val`: the existing fail-closed RecordGet error must
        // stand (the interpreter type-errors there; never emit a wrong value).
        let pool = heterogeneous_guard_pool("b");

        let result = lower_next_state_loop_scaffold(&func, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(&result, Err(TrustIrError::UnsupportedOpcode(msg)) if msg.contains("val")),
            "missing-field read on a LIVE key must keep failing closed, got {result:?}"
        );
    }

    #[test]
    fn nsl_guard_const_fold_missing_field_prefix_blocks_dead_key_skip() {
        let _guard = RecordSetNativeEnvGuard::enabled();
        // A `m.val` read BEFORE the type guard: for bit 1 the interpreter
        // raises a type error before ever evaluating the (false) guard, so the
        // pre-scan must NOT silently skip the key — the whole action fails
        // closed instead (interpreter fallback preserves the error).
        let mut f = BytecodeFunction::new("nsl_prefix".to_string(), 0);
        f.emit(Opcode::LoadVar { rd: 2, var_idx: 1 }); // pc0
        f.emit(Opcode::ExistsBegin {
            rd: 3,
            r_binding: 4,
            r_domain: 2,
            loop_end: 10,
        }); // pc1
        f.emit(Opcode::RecordGet {
            rd: 8,
            rs: 4,
            field_idx: 1,
        }); // pc2: r8 = m.val — PREFIX read, missing on bit 1
        f.emit(Opcode::RecordGet {
            rd: 5,
            rs: 4,
            field_idx: 0,
        }); // pc3: r5 = m.type
        f.emit(Opcode::LoadConst { rd: 6, idx: 0 }); // pc4
        f.emit(Opcode::Eq {
            rd: 7,
            r1: 5,
            r2: 6,
        }); // pc5
        f.emit(Opcode::Move { rd: 3, rs: 7 }); // pc6
        f.emit(Opcode::JumpFalse { rs: 3, offset: 3 }); // pc7 -> pc10 (body end)
        f.emit(Opcode::StoreVar { var_idx: 0, rs: 8 }); // pc8: x' = m.val
        f.emit(Opcode::LoadBool { rd: 3, value: true }); // pc9: trailing true
        f.emit(Opcode::ExistsNext {
            rd: 3,
            r_binding: 4,
            r_body: 3,
            loop_begin: -8,
        }); // pc10
        f.emit(Opcode::Ret { rs: 3 }); // pc11
        let layout = heterogeneous_record_set_layout();
        let pool = heterogeneous_guard_pool("a");

        let result = lower_next_state_loop_scaffold(&f, "nsl", Some(&pool), Some(&layout));
        assert!(
            matches!(&result, Err(TrustIrError::UnsupportedOpcode(msg)) if msg.contains("val")),
            "a missing-field read before the guard must fail closed (interpreter raises), got {result:?}"
        );
    }

    // =====================================================================
    // Lever L1: AggregateShape::LazyUnion — static-only lazy set unions.
    // =====================================================================

    /// Constant pool with idx0 = {p1,p2,p3} (model values), idx1 = {dIV},
    /// idx2 = {{}} (the singleton empty set, for NonEmptyPowerset).
    fn lazy_union_proc_pool() -> (ConstantPool, u16, u16, u16) {
        use std::sync::Arc;
        let mut pool = ConstantPool::new();
        let procs = pool.add_value(Value::set([
            Value::ModelValue(Rp::from("p1")),
            Value::ModelValue(Rp::from("p2")),
            Value::ModelValue(Rp::from("p3")),
        ]));
        let div = pool.add_value(Value::set([Value::ModelValue(Rp::from("dIV"))]));
        let empty_set = Value::set(Vec::<Value>::new());
        let singleton_empty = pool.add_value(Value::set([empty_set]));
        (pool, procs, div, singleton_empty)
    }

    fn lazy_union_proc_elements() -> Vec<SetBitmaskElement> {
        ["p1", "p2", "p3"]
            .into_iter()
            .map(|name| SetBitmaskElement::ModelValue(tla_core::intern_name(name)))
            .collect()
    }

    /// var 0: `temp`-shaped function — ModelValue keys {p1,p2,p3}, tagged
    /// `scalar | subset-of-Proc` range slots (the Dijkstra `temp` layout).
    fn lazy_union_tagged_temp_layout() -> StateLayout {
        StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::ExplicitScalarDomain {
                key_layout: Box::new(CompoundLayout::String),
                keys: lazy_union_proc_elements(),
            }),
            value_layout: Box::new(CompoundLayout::TaggedScalarOrSet {
                scalar_kind: ScalarSlotKind::ModelValue,
                set_universe: lazy_union_proc_elements(),
                proof_source: tla_core::intern_name("LazyUnionTempTypeOK"),
            }),
            pair_count: Some(3),
            domain_lo: None,
        })])
    }

    /// Emit `temp \in [{p1,p2,p3} -> (SUBSET Proc) \cup (Proc \cup {dIV})]`
    /// (the Dijkstra MCTypeOK temp conjunct) against the tagged temp layout.
    fn lazy_union_dijkstra_temp_membership_func(procs: u16, div: u16) -> BytecodeFunction {
        let mut func = BytecodeFunction::new("lazy_union_temp_typeok".to_string(), 0);
        func.emit(Opcode::LoadConst { rd: 0, idx: procs });
        func.emit(Opcode::Powerset { rd: 1, rs: 0 });
        func.emit(Opcode::LoadConst { rd: 2, idx: procs });
        func.emit(Opcode::LoadConst { rd: 3, idx: div });
        func.emit(Opcode::SetUnion {
            rd: 4,
            r1: 2,
            r2: 3,
        });
        func.emit(Opcode::SetUnion {
            rd: 5,
            r1: 1,
            r2: 4,
        });
        func.emit(Opcode::LoadVar { rd: 6, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 7, idx: procs });
        func.emit(Opcode::FuncSet {
            rd: 8,
            domain: 7,
            range: 5,
        });
        func.emit(Opcode::SetIn {
            rd: 9,
            elem: 6,
            set: 8,
        });
        func.emit(Opcode::Ret { rs: 9 });
        func
    }

    #[test]
    fn test_lazy_union_scalar_membership_lowers() {
        // `x \in ((SUBSET {9}) \cup {1, 2}) \cup {3, 4}` — a nested lazy union
        // with one set-sort arm and two scalar-sort arms over an Int scalar.
        let mut pool = ConstantPool::new();
        let nine = pool.add_value(Value::set([Value::SmallInt(9)]));
        let one_two = pool.add_value(Value::set([Value::SmallInt(1), Value::SmallInt(2)]));
        let three_four = pool.add_value(Value::set([Value::SmallInt(3), Value::SmallInt(4)]));

        let mut func = BytecodeFunction::new("lazy_union_scalar_member".to_string(), 0);
        func.emit(Opcode::LoadConst { rd: 0, idx: nine });
        func.emit(Opcode::Powerset { rd: 1, rs: 0 });
        func.emit(Opcode::LoadConst {
            rd: 2,
            idx: one_two,
        });
        func.emit(Opcode::SetUnion {
            rd: 3,
            r1: 1,
            r2: 2,
        });
        func.emit(Opcode::LoadConst {
            rd: 4,
            idx: three_four,
        });
        func.emit(Opcode::SetUnion {
            rd: 5,
            r1: 3,
            r2: 4,
        });
        func.emit(Opcode::LoadImm { rd: 6, value: 3 });
        func.emit(Opcode::SetIn {
            rd: 7,
            elem: 6,
            set: 5,
        });
        func.emit(Opcode::Ret { rs: 7 });

        lower_invariant(
            &func,
            "lazy_union_scalar_member",
            LoweringOptions::new().with_constants(&pool),
        )
        .expect("scalar membership in a nested lazy union should lower");
    }

    #[test]
    fn test_lazy_union_dijkstra_temp_typeok_conjunct_lowers() {
        let (pool, procs, div, _) = lazy_union_proc_pool();
        let func = lazy_union_dijkstra_temp_membership_func(procs, div);
        let layout = lazy_union_tagged_temp_layout();
        lower_invariant(
            &func,
            "lazy_union_temp_typeok",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("temp \\in [Proc -> (SUBSET Proc) \\cup (Proc \\cup {dIV})] should lower natively");
    }

    #[test]
    fn test_lazy_union_nonempty_powerset_arm_lowers() {
        // `temp \in [Proc -> ((SUBSET Proc) \ {{}}) \cup (Proc \cup {dIV})]`
        // — the `(SUBSET S) \ {{}}` idiom becomes a NonEmptyPowerset arm.
        let (pool, procs, div, singleton_empty) = lazy_union_proc_pool();
        let mut func = BytecodeFunction::new("lazy_union_nonempty_arm".to_string(), 0);
        func.emit(Opcode::LoadConst { rd: 0, idx: procs });
        func.emit(Opcode::Powerset { rd: 1, rs: 0 });
        func.emit(Opcode::LoadConst {
            rd: 2,
            idx: singleton_empty,
        });
        func.emit(Opcode::SetDiff {
            rd: 3,
            r1: 1,
            r2: 2,
        });
        func.emit(Opcode::LoadConst { rd: 4, idx: procs });
        func.emit(Opcode::LoadConst { rd: 5, idx: div });
        func.emit(Opcode::SetUnion {
            rd: 6,
            r1: 4,
            r2: 5,
        });
        func.emit(Opcode::SetUnion {
            rd: 7,
            r1: 3,
            r2: 6,
        });
        func.emit(Opcode::LoadVar { rd: 8, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 9, idx: procs });
        func.emit(Opcode::FuncSet {
            rd: 10,
            domain: 9,
            range: 7,
        });
        func.emit(Opcode::SetIn {
            rd: 11,
            elem: 8,
            set: 10,
        });
        func.emit(Opcode::Ret { rs: 11 });

        let layout = lazy_union_tagged_temp_layout();
        lower_invariant(
            &func,
            "lazy_union_nonempty_arm",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("a NonEmptyPowerset lazy-union arm should lower natively");
    }

    /// Emit `(SUBSET Proc) \cup (Proc \cup {dIV})` into r5 and return the
    /// partially built function for fail-closed consumer tests.
    fn lazy_union_value_prefix(procs: u16, div: u16, name: &str) -> BytecodeFunction {
        let mut func = BytecodeFunction::new(name.to_string(), 0);
        func.emit(Opcode::LoadConst { rd: 0, idx: procs });
        func.emit(Opcode::Powerset { rd: 1, rs: 0 });
        func.emit(Opcode::LoadConst { rd: 2, idx: procs });
        func.emit(Opcode::LoadConst { rd: 3, idx: div });
        func.emit(Opcode::SetUnion {
            rd: 4,
            r1: 2,
            r2: 3,
        });
        func.emit(Opcode::SetUnion {
            rd: 5,
            r1: 1,
            r2: 4,
        });
        func
    }

    #[test]
    fn test_lazy_union_setdiff_fails_closed() {
        let (pool, procs, div, _) = lazy_union_proc_pool();
        let mut func = lazy_union_value_prefix(procs, div, "lazy_union_setdiff");
        func.emit(Opcode::LoadConst { rd: 6, idx: div });
        func.emit(Opcode::SetDiff {
            rd: 7,
            r1: 5,
            r2: 6,
        });
        func.emit(Opcode::Ret { rs: 7 });
        let result = lower_invariant(
            &func,
            "lazy_union_setdiff",
            LoweringOptions::new().with_constants(&pool),
        );
        let err = format!("{result:?}");
        assert!(
            result.is_err() && err.contains("lazy set shape is only supported by SetIn membership"),
            "SetDiff over a lazy union must fail closed, got {result:?}"
        );
    }

