    #[test]
    fn test_lazy_union_equality_fails_closed() {
        // A LazyUnion register holds an inert placeholder; raw i64 equality
        // over two of them would compare placeholders (always equal).
        let (pool, procs, div, _) = lazy_union_proc_pool();
        let mut func = lazy_union_value_prefix(procs, div, "lazy_union_eq");
        func.emit(Opcode::LoadConst { rd: 6, idx: procs });
        func.emit(Opcode::Powerset { rd: 7, rs: 6 });
        func.emit(Opcode::LoadConst { rd: 8, idx: div });
        func.emit(Opcode::SetUnion {
            rd: 9,
            r1: 7,
            r2: 8,
        });
        func.emit(Opcode::Eq {
            rd: 10,
            r1: 5,
            r2: 9,
        });
        func.emit(Opcode::Ret { rs: 10 });
        let result = lower_invariant(
            &func,
            "lazy_union_eq",
            LoweringOptions::new().with_constants(&pool),
        );
        let err = format!("{result:?}");
        assert!(
            result.is_err() && err.contains("LazyUnion is membership-only"),
            "Eq over lazy-union operands must fail closed, got {result:?}"
        );
    }

