    #[test]
    fn test_lazy_union_non_exact_universe_entry_fails_closed() {
        // var 0's per-entry value layout is `Set { element_count }` — a compact
        // SetBitmask whose universe is UNKNOWN on the IR side. Lazy-union range
        // membership requires exact universe metadata and must fail closed.
        let (pool, procs, div, _) = lazy_union_proc_pool();
        let func = lazy_union_dijkstra_temp_membership_func(procs, div);
        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::ExplicitScalarDomain {
                key_layout: Box::new(CompoundLayout::String),
                keys: lazy_union_proc_elements(),
            }),
            value_layout: Box::new(CompoundLayout::Set {
                element_layout: Box::new(CompoundLayout::String),
                element_count: Some(3),
            }),
            pair_count: Some(3),
            domain_lo: None,
        })]);
        let result = lower_invariant(
            &func,
            "lazy_union_temp_typeok",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        );
        let err = format!("{result:?}");
        assert!(
            result.is_err()
                && err.contains("lazy-union set membership requires exact universe metadata"),
            "lazy-union membership over an Unknown-universe SetBitmask entry must fail closed, got {result:?}"
        );
    }

    /// H2 (domain aliasing): `f \in [{q1,q2,q3} -> R]` where `f`'s layout keys
    /// are `{p1,p2,p3}` — same cardinality, different key sets. The old
    /// cardinality-only gate compiled this to TRUE; the key-set equality gate
    /// must fail closed instead.
    #[test]
    fn test_funcset_domain_key_mismatch_fails_closed() {
        use std::sync::Arc;
        let mut pool = ConstantPool::new();
        let qs = pool.add_value(Value::set([
            Value::ModelValue(Rp::from("q1")),
            Value::ModelValue(Rp::from("q2")),
            Value::ModelValue(Rp::from("q3")),
        ]));
        let labels = pool.add_value(Value::set([Value::string("a"), Value::string("b")]));

        let mut func = BytecodeFunction::new("funcset_domain_alias".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 0 });
        func.emit(Opcode::LoadConst { rd: 1, idx: qs });
        func.emit(Opcode::LoadConst { rd: 2, idx: labels });
        func.emit(Opcode::FuncSet {
            rd: 3,
            domain: 1,
            range: 2,
        });
        func.emit(Opcode::SetIn {
            rd: 4,
            elem: 0,
            set: 3,
        });
        func.emit(Opcode::Ret { rs: 4 });

        let layout = StateLayout::new(vec![VarLayout::Compound(CompoundLayout::Function {
            key_layout: Box::new(CompoundLayout::ExplicitScalarDomain {
                key_layout: Box::new(CompoundLayout::String),
                keys: lazy_union_proc_elements(),
            }),
            value_layout: Box::new(CompoundLayout::String),
            pair_count: Some(3),
            domain_lo: None,
        })]);
        let result = lower_invariant(
            &func,
            "funcset_domain_alias",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        );
        let err = format!("{result:?}");
        assert!(
            result.is_err() && err.contains("do not equal the function-set domain element set"),
            "cardinality-equal but key-set-different function-set domains must fail closed (H2), got {result:?}"
        );
    }

