    // =====================================================================
    // Item 4 M1 — compound-READ callout admission + emission (WP-03b)
    // =====================================================================

    /// Serializes the `TY_HYBRID_COMPOUND_READ` gate and restores it on drop.
    /// The variable is unset by default, so every other test in this file — and
    /// the default lowering path — keeps the M0 hard decline.
    struct CompoundReadEnvGuard {
        _lock: std::sync::MutexGuard<'static, ()>,
        prev: Option<std::ffi::OsString>,
    }

    impl CompoundReadEnvGuard {
        fn enabled() -> Self {
            Self::set(Some("1"))
        }

        fn disabled() -> Self {
            Self::set(None)
        }

        fn set(value: Option<&str>) -> Self {
            static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
            let lock = LOCK.lock().unwrap_or_else(|poison| poison.into_inner());
            let prev = std::env::var_os("TY_HYBRID_COMPOUND_READ");
            raw_env_write(
                "TY_HYBRID_COMPOUND_READ",
                value.map(std::ffi::OsStr::new),
            );
            Self { _lock: lock, prev }
        }
    }

    impl Drop for CompoundReadEnvGuard {
        fn drop(&mut self) {
            raw_env_write("TY_HYBRID_COMPOUND_READ", self.prev.as_deref());
        }
    }

    /// Count of `Inst::Call` sites targeting `symbol` in the entry function.
    fn host_call_count(module: &trust_ir::Module, symbol: &str) -> usize {
        let Some(callee_id) = module
            .functions
            .iter()
            .find(|f| f.blocks.is_empty() && f.name == symbol)
            .map(|f| f.id)
        else {
            return 0;
        };
        module
            .functions
            .iter()
            .filter(|f| !f.blocks.is_empty())
            .flat_map(|f| f.blocks.iter())
            .flat_map(|b| b.body.iter())
            .filter(|node| matches!(&node.inst, Inst::Call { callee, .. } if *callee == callee_id))
            .count()
    }

    /// Every i64 constant materialized in the module, in emission order.
    fn i64_consts(module: &trust_ir::Module) -> Vec<i64> {
        module
            .functions
            .iter()
            .filter(|f| !f.blocks.is_empty())
            .flat_map(|f| f.blocks.iter())
            .flat_map(|b| b.body.iter())
            .filter_map(|node| match &node.inst {
                Inst::Const {
                    ty: Ty::I64,
                    value: Constant::Int(v),
                } => i64::try_from(*v).ok(),
                _ => None,
            })
            .collect()
    }

    /// `v0` is a flat scalar-int slot; `v1` is the hybrid Dynamic placeholder
    /// whose value lives only in the checker's compound parent state.
    fn m1_layout() -> StateLayout {
        StateLayout::new(vec![
            VarLayout::ScalarInt,
            VarLayout::Compound(CompoundLayout::Dynamic),
        ])
        .with_hybrid_flat_view()
    }

    /// `v1[k]` with a model-value key, stored into the flat int var `v0`.
    /// The single-key btree `keysOf[n]` shape.
    fn one_key_chain(pool: &mut ConstantPool) -> BytecodeFunction {
        let n1 = pool.add_value(Value::ModelValue(Rp::from("n1")));
        let mut func = BytecodeFunction::new("m1_one_key".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::LoadConst { rd: 1, idx: n1 });
        func.emit(Opcode::FuncApply {
            rd: 2,
            func: 0,
            arg: 1,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 2 });
        func.emit(Opcode::LoadBool { rd: 3, value: true });
        func.emit(Opcode::Ret { rs: 3 });
        func
    }

    #[test]
    fn m1_one_key_chain_lowers_to_the_apply1_callout_with_declared_kinds() {
        let _gate = CompoundReadEnvGuard::enabled();
        let mut pool = ConstantPool::new();
        let func = one_key_chain(&mut pool);
        let layout = m1_layout();

        let module = lower_next_state(
            &func,
            "m1_one_key",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("a chain-terminating scalar read of a placeholder var must lower");

        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply1_i64"),
            1,
            "exactly one fused single-key callout"
        );
        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply2_i64"),
            0
        );
        // The declared ABI operands, in emission order: var_idx 1, key kind
        // ModelValue (3), expected leaf kind Int (0). The key kind must be
        // explicit — String and ModelValue intern to the SAME NameId, so the
        // raw i64 alone cannot distinguish them at the boundary.
        let consts = i64_consts(&module);
        assert!(
            consts.windows(3).any(|w| w == [1, 3, 0]),
            "expected (var_idx=1, key_kind=ModelValue=3, expect_kind=Int=0), saw {consts:?}"
        );
        // The placeholder slot is never loaded: the root LoadVar is elided.
        assert_eq!(
            compound_read_callout_extern_names(&module),
            vec!["tla_hybrid_compound_apply1_i64".to_string()],
        );
    }

    #[test]
    fn m1_two_key_tuple_chain_lowers_to_the_apply2_callout_without_building_the_key() {
        let _gate = CompoundReadEnvGuard::enabled();
        let mut pool = ConstantPool::new();
        let n1 = pool.add_value(Value::ModelValue(Rp::from("n1")));

        // `v1[<<n1, 7>>]` — btree's `childOf[n, k]` shape.
        let mut func = BytecodeFunction::new("m1_two_key_tuple".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::LoadConst { rd: 1, idx: n1 });
        func.emit(Opcode::LoadImm { rd: 2, value: 7 });
        func.emit(Opcode::TupleNew {
            rd: 3,
            start: 1,
            count: 2,
        });
        func.emit(Opcode::FuncApply {
            rd: 4,
            func: 0,
            arg: 3,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 4 });
        func.emit(Opcode::LoadBool { rd: 5, value: true });
        func.emit(Opcode::Ret { rs: 5 });

        let layout = m1_layout();
        let module = lower_next_state(
            &func,
            "m1_two_key_tuple",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("a tuple-keyed placeholder read must lower to the fused two-key callout");

        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply2_i64"),
            1,
            "one fused two-key callout — the intermediate function is never materialized"
        );
        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply1_i64"),
            0
        );
        // var_idx 1, then key0 kind ModelValue (3), key1 kind Int (0), then
        // the expected leaf kind Int (0).
        let consts = i64_consts(&module);
        assert!(
            consts.windows(4).any(|w| w == [1, 3, 0, 0]),
            "expected (var_idx=1, key0_kind=3, key1_kind=0, expect_kind=0), saw {consts:?}"
        );
    }

    #[test]
    fn m1_two_key_curried_chain_lowers_to_a_single_apply2_callout() {
        let _gate = CompoundReadEnvGuard::enabled();
        let mut pool = ConstantPool::new();
        let n1 = pool.add_value(Value::ModelValue(Rp::from("n1")));

        // `v1[n1][7]` — the curried reading of the same access.
        let mut func = BytecodeFunction::new("m1_two_key_curried".to_string(), 0);
        func.emit(Opcode::LoadVar { rd: 0, var_idx: 1 });
        func.emit(Opcode::LoadConst { rd: 1, idx: n1 });
        func.emit(Opcode::FuncApply {
            rd: 2,
            func: 0,
            arg: 1,
        });
        func.emit(Opcode::LoadImm { rd: 3, value: 7 });
        func.emit(Opcode::FuncApply {
            rd: 4,
            func: 2,
            arg: 3,
        });
        func.emit(Opcode::StoreVar { var_idx: 0, rs: 4 });
        func.emit(Opcode::LoadBool { rd: 5, value: true });
        func.emit(Opcode::Ret { rs: 5 });

        let layout = m1_layout();
        let module = lower_next_state(
            &func,
            "m1_two_key_curried",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("a curried two-key placeholder read must lower");

        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply2_i64"),
            1,
            "the intermediate apply emits nothing — one callout answers the whole chain"
        );
        assert_eq!(
            host_call_count(&module, "tla_hybrid_compound_apply1_i64"),
            0,
            "the inner apply must NOT become its own callout: its result is a \
             function, not a scalar leaf"
        );
    }

    /// The emitted module must audit clean AND be attributed to the callout
    /// set, never the boxed handle-mode set (wishlist item 8).
    #[test]
    fn m1_callout_module_is_attributed_to_the_callout_extern_set() {
        let _gate = CompoundReadEnvGuard::enabled();
        let mut pool = ConstantPool::new();
        let func = one_key_chain(&mut pool);
        let layout = m1_layout();

        let module = lower_next_state(
            &func,
            "m1_one_key",
            LoweringOptions::new()
                .with_constants(&pool)
                .with_layout(&layout),
        )
        .expect("must lower");

        assert_eq!(
            unsanctioned_tla_extern_names(&module),
            Vec::<String>::new(),
            "the compound-read callout is sanctioned; nothing unsanctioned may appear"
        );
        assert_eq!(
            compound_read_callout_extern_names(&module),
            vec!["tla_hybrid_compound_apply1_i64".to_string()],
        );
        for boxed in SANCTIONED_HANDLE_MODE_TLA_EXTERNS {
            assert!(
                !host_extern_names(&module).contains(*boxed),
                "an M1 compound read must never reach a boxed handle-mode kernel ({boxed})"
            );
        }
        assert!(SANCTIONED_COMPOUND_READ_CALLOUT_EXTERNS
            .contains(&"tla_hybrid_compound_apply1_i64"));
    }

    /// Default-OFF proof: the identical bytecode declines exactly as it did
    /// under M0 when the gate is unset.
